export enum RepairStep {
  Safety = 'safety',
  Identification = 'identification',
  Boardview = 'boardview',
  Measurement = 'measurement',
  Diagnostics = 'diagnostics',
  Component = 'component'
}

export interface PCBAnalysisResult {
  manufacturer: string;
  model: string;
  boardNumber: string;
  confidence: number;
  identifiedComponents: string[];
}

export interface DiagnosticTurn {
  role: 'user' | 'assistant';
  content: string;
  thinking?: string;
  timestamp: number;
}

import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzePCBImage = async (base64Image: string): Promise<any> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        parts: [
          { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
          { text: "Analyze this PCB image. Identify the manufacturer, model name, and board number if visible. Also list prominent components like CPU, GPU, or power management ICs. Return as JSON." }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [
      ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
      { role: 'user', parts: [{ text: currentIssue }] }
    ],
    config: {
      systemInstruction: "You are a world-class electronic repair expert (Gusrepart AI). Provide highly systematic, step-by-step diagnostic guidance for fixing electronic boards. Use thinking mode for complex reasoning.",
      thinkingConfig: { thinkingBudget: 32768 }
    }
  });
  return response.text;
};

export const searchComponentInfo = async (query: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: query,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });
  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.searchEntryPoint?.renderedContent
  };
};

export const generateRepairVideo = async (prompt: string): Promise<string | undefined> => {
  const ai = getAI();
  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '16:9'
    }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 5000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }

  return operation.response?.generatedVideos?.[0]?.video?.uri;
};

export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (base64Audio) {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioData = decodeBase64(base64Audio);
    const buffer = await decodeRawPCM(audioData, ctx, 24000, 1);
    onAudioReady(buffer);
  }
};

// Utils for audio
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPCM(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / channels;
  const buffer = ctx.createBuffer(channels, frameCount, sampleRate);
  for (let channel = 0; channel < channels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * channels + channel] / 32768.0;
    }
  }
  return buffer;
}

