import React, { useState, useRef } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage } from '../services/gemini';
import { PCBAnalysisResult } from '../types';

const PCBIdentification: React.FC = () => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<PCBAnalysisResult | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      setPreview(base64);
      setIsAnalyzing(true);

      try {
        const pureBase64 = base64.split(',')[1];
        const analysis = await analyzePCBImage(pureBase64);
        setResult(analysis);
      } catch (error) {
        console.error("Analysis failed", error);
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden">
      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black leading-tight tracking-tight">Identificación de PCB</h1>
            <p className="text-[#92a4c9] text-base font-normal">Escanee una placa o cargue una imagen para identificar componentes automáticamente.</p>
          </div>

          <div className="mb-6">
            <div className="flex border-b border-[#324467] gap-8">
              <button className="flex items-center gap-2 border-b-[3px] border-primary text-primary pb-3 px-1">
                <span className="material-symbols-outlined text-xl">upload_file</span>
                <span className="text-sm font-bold tracking-wide">Cargar Imagen</span>
              </button>
            </div>
          </div>

          <div className="flex-1 flex flex-col min-h-[400px]">
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleFileSelect} 
            />

            <div 
              onClick={() => fileInputRef.current?.click()}
              className="flex-1 flex flex-col items-center justify-center gap-6 rounded-xl border-2 border-dashed border-[#324467] bg-[#111722] hover:bg-[#161e2c] transition-colors relative group cursor-pointer p-8 overflow-hidden"
            >
              {preview ? (
                <img src={preview} alt="PCB Preview" className="absolute inset-0 w-full h-full object-contain opacity-40" />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center opacity-[0.05] pointer-events-none">
                  <span className="material-symbols-outlined text-[300px]">developer_board</span>
                </div>
              )}

              <div className="flex flex-col items-center gap-4 z-10 text-center">
                <div className={`size-16 rounded-full ${isAnalyzing ? 'animate-spin' : ''} bg-primary/10 flex items-center justify-center text-primary mb-2 group-hover:scale-110 transition-transform duration-300`}>
                  <span className="material-symbols-outlined text-4xl">{isAnalyzing ? 'sync' : 'cloud_upload'}</span>
                </div>
                <p className="text-xl font-bold leading-tight max-w-[480px]">
                  {isAnalyzing ? 'Analizando PCB con Gemini 3 Pro...' : 'Arrastre la imagen de la PCB o haga clic para explorar'}
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] xl:w-[480px] bg-background-dark flex flex-col shrink-0 border-t lg:border-t-0 overflow-y-auto">
        <div className="p-6 flex flex-col gap-6 h-full">
          <h2 className="text-xl font-bold leading-tight">Detalles del Dispositivo</h2>

          {result ? (
            <>
              <div className="flex flex-col gap-5">
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold uppercase tracking-wider text-[#92a4c9] ml-1">Fabricante Detectado</label>
                  <div className="w-full h-11 px-4 rounded-lg bg-border-dark border border-slate-700 text-white flex items-center">
                    {result.manufacturer}
