                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold uppercase tracking-wider text-[#92a4c9] ml-1">Modelo / Referencia</label>
                  <div className="w-full h-11 px-4 rounded-lg bg-border-dark border border-slate-700 text-white flex items-center">
                    {result.model} ({result.boardNumber})
                  </div>
                </div>
              </div>

              <div className="mt-2 p-4 rounded-xl border border-primary/30 bg-primary/10">
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <span className="material-symbols-outlined text-green-500 text-xl">check_circle</span>
                    <span className="text-sm font-bold text-white">Análisis Completo</span>
