          )}

          <div className="flex-1 flex flex-col gap-4 mt-4 overflow-hidden">
            <h3 className="text-sm font-bold text-white">Historial Reciente</h3>
            <div className="flex flex-col gap-2 overflow-y-auto pr-2 pb-2">
              {[
                { name: "MacBook Air M1", time: "Hace 2 horas", img: "https://picsum.photos/id/1/40/40" },
                { name: "PS5 Motherboard", time: "Hace 1 día", img: "https://picsum.photos/id/2/40/40" },
              ].map((item, i) => (
                <div key={i} className="flex items-center gap-3 p-2 rounded-lg hover:bg-[#1a2332] cursor-pointer transition-colors group">
                  <div className="size-10 rounded bg-slate-700 bg-cover bg-center shrink-0" style={{backgroundImage: `url(${item.img})`}}></div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-white truncate">{item.name}</p>
                    <p className="text-xs text-slate-400 truncate">{item.time}</p>
                  </div>
