export default PCBIdentification;

import React, { useState, useEffect, useRef } from 'react';
import { getDiagnosticAdvice } from '../services/gemini';
import { DiagnosticTurn } from '../types';

const DiagnosticDecisionTree: React.FC = () => {
  const [history, setHistory] = useState<DiagnosticTurn[]>([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
  }, [history]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userTurn: DiagnosticTurn = {
      role: 'user',
      content: input,
      timestamp: Date.now()
    };

    setHistory(prev => [...prev, userTurn]);
    setInput("");
    setIsLoading(true);

    try {
      const advice = await getDiagnosticAdvice(history, input);
      const assistantTurn: DiagnosticTurn = {
        role: 'assistant',
        content: advice || "Lo siento, no pude procesar esa solicitud.",
        timestamp: Date.now()
      };
      setHistory(prev => [...prev, assistantTurn]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#111722]">
      <div className="p-6 border-b border-border-dark bg-[#111722] flex justify-between items-center">
        <div>
          <h1 className="text-white text-2xl font-bold">Diagnóstico Experto con IA</h1>
          <p className="text-[#92a4c9] text-sm">Gemini 3 Pro con Modo Pensamiento (32k tokens)</p>
        </div>
        <button 
          onClick={() => setHistory([])}
          className="px-4 py-2 bg-border-dark hover:bg-surface-dark text-white rounded text-sm"
        >
          Reiniciar Sesión
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
        {history.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-30 text-center">
            <span className="material-symbols-outlined text-8xl mb-4">psychology</span>
            <p className="max-w-md">Describa los síntomas del dispositivo para iniciar el diagnóstico lógico sistemático.</p>
          </div>
        )}

        {history.map((turn, i) => (
          <div key={i} className={`flex ${turn.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-xl ${turn.role === 'user' ? 'bg-primary text-white' : 'bg-[#1a2332] border border-border-dark text-white'}`}>
              <div className="text-xs font-bold uppercase mb-1 opacity-50">{turn.role}</div>
              <div className="prose prose-invert text-sm whitespace-pre-wrap leading-relaxed">
                {turn.content}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-[#1a2332] border border-border-dark p-4 rounded-xl flex items-center gap-3">
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-primary rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-primary rounded-full animate-bounce delay-75"></div>
                <div className="w-2 h-2 bg-primary rounded-full animate-bounce delay-150"></div>
              </div>
              <span className="text-xs text-[#92a4c9]">Gemini está razonando el problema...</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 bg-[#161b26] border-t border-border-dark">
        <form onSubmit={handleSubmit} className="flex gap-4">
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            placeholder="Ej: El dispositivo no enciende, PPBUS_G3H mide 12.3V..."
            className="flex-1 bg-[#0d1017] border border-border-dark text-white p-4 rounded-xl focus:ring-2 focus:ring-primary outline-none"
          />
          <button 
            type="submit"
            disabled={isLoading}
            className="px-6 py-4 bg-primary hover:bg-primary-hover rounded-xl text-white font-bold transition-colors disabled:opacity-50"
          >
            Analizar
          </button>
        </form>
      </div>
    </div>
  );
};

export default DiagnosticDecisionTree;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const newMessages = [...messages, { role: 'user' as const, text: input }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const chat = ai.chats.create({ 
        model: 'gemini-3-pro-preview',
        config: { systemInstruction: "Eres un asistente experto en electrónica de Gusrepart. Ayuda a los técnicos con dudas rápidas sobre soldadura, componentes y esquemas." }
      });

