import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzePCBImage = async (base64Images: string[]): Promise<any> => {
  const ai = getAI();

  const imageParts = base64Images.map(base64 => ({
    inlineData: { data: base64, mimeType: 'image/jpeg' }
  }));

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        role: 'user',
        parts: [
          ...imageParts,
          { text: "Analiza estas imágenes de una PCB (pueden ser diferentes lados o ángulos). Identifica el fabricante, modelo, número de placa y componentes críticos. Devuelve la respuesta estrictamente en formato JSON." }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

