  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [images, setImages] = useState<string[]>(persistedImages);
  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  // Sincronizar cambios locales con el estado global de App
  useEffect(() => {
    onUpdate(images, result);
  }, [images, result]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      setActiveSlot(null);
    };
    reader.readAsDataURL(file);
  };

  const triggerUpload = (slot: number) => {
    setActiveSlot(slot);
    fileInputRef.current?.click();
  };

  const removeImage = (slot: number) => {
    const newImages = [...images];
    newImages.splice(slot, 1);
    setImages(newImages.filter(Boolean));
  };

  const runAnalysis = async () => {
    if (images.length === 0) return;
    setIsAnalyzing(true);
    try {
      const pureBase64s = images.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
