import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string): Promise<MeasurementPoint[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Basado en este análisis de hardware: ${JSON.stringify(pcbResult)} y este análisis funcional: ${functionalAnalysis}, genera un plan de 4 a 6 puntos de medición críticos para diagnosticar la placa. Devuelve un JSON array de objetos con: id, component, testPoint, mode (V, Diode, Ohm), expectedValue (ej: "0.450V", "12V"), description (por qué medir esto).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            component: { type: Type.STRING },
            testPoint: { type: Type.STRING },
            mode: { type: Type.STRING },
            expectedValue: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["id", "component", "testPoint", "mode", "expectedValue", "description"]
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

export const getFinalVerdict = async (pcbResult: any, measurements: MeasurementPoint[]): Promise<string> => {
  const ai = getAI();
  const data = {
    board: pcbResult,
    measurements: measurements.map(m => ({
      ponto: m.component,
      esperado: m.expectedValue,
      medido: m.measuredValue,
      descripcion: m.description
    }))
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analiza estos resultados de laboratorio: ${JSON.stringify(data)}. Da un veredicto final de reparación: 1. Causa probable. 2. Componente defectuoso. 3. Pasos para la solución. Sé muy técnico y preciso.`,
    config: { thinkingConfig: { thinkingBudget: 10000 } }
  });

  return response.text || "No se pudo generar un veredicto.";
};

