export const enhancePCBImage = async (base64Image: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image,
            mimeType: 'image/jpeg',
          },
        },
        {
          text: 'Actúa como un sistema de mejora de imágenes para microelectrónica. Procesa esta imagen de PCB para: 1. Aumentar la nitidez de los bordes de los componentes. 2. Reducir el ruido del sensor. 3. Resaltar los números de serie y marcas en los integrados. Devuelve únicamente la imagen mejorada.',
        },
      ],
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No se pudo generar la imagen mejorada");
};

export const analyzePCBImage = async (base64Images: string[]): Promise<any> => {
  const ai = getAI();

  const imageParts = base64Images.map(base64 => ({
    inlineData: { data: base64, mimeType: 'image/jpeg' }
  }));

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        role: 'user',
        parts: [
          ...imageParts,
          { text: "Analiza estas imágenes de una PCB. 1. Identifica fabricante, modelo y board number. 2. Identifica componentes críticos. 3. Busca visualmente posibles fallos (corrosión, componentes quemados, decoloración). 4. Devuelve un JSON con: manufacturer, model, boardNumber, confidence, identifiedComponents, detectedAnomalies (array de strings)." }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { type: Type.ARRAY, items: { type: Type.STRING } },
          detectedAnomalies: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents", "detectedAnomalies"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const searchSchematics = async (boardInfo: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Busca enlaces de descarga o visualización de esquemas técnicos, manuales de servicio o boardviews para la placa: ${boardInfo}. Prioriza sitios como badcaps, vlab, o repositorios oficiales.`,
    config: {
      tools: [{ googleSearch: {} }]
    }
  });

  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const sources = response.candidates?.[0]?.groundingMetadata?.searchEntryPoint?.renderedContent || "";

  return {
    summary: response.text,
    sources: sources
  };
};

export const getFunctionalAnalysis = async (components: string[], boardModel: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Basado en esta placa ${boardModel} y sus componentes [${components.join(', ')}], genera una guía de funcionamiento. ¿Cuál es el flujo de energía principal? ¿Qué voltajes críticos deberían medirse en estos componentes específicos? Explica como un experto técnico.`,
  });
