export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (base64Audio) {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioData = decodeBase64(base64Audio);
    const buffer = await decodeRawPCM(audioData, ctx, 24000, 1);
    onAudioReady(buffer);
  }
};

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPCM(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / channels;
  const buffer = ctx.createBuffer(channels, frameCount, sampleRate);
  for (let channel = 0; channel < channels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * channels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import ComponentDetails from './screens/ComponentDetails';
import DatabaseScreen from './screens/DatabaseScreen';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const App: React.FC = () => {
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);

  // Estado persistente
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");

  // Hidratación inicial desde IndexedDB
  useEffect(() => {
    const loadPersistedData = async () => {
      try {
        const images = await getSessionData('pcbImages');
        const result = await getSessionData('pcbResult');
        const schematics = await getSessionData('schematicInfo');
        const functional = await getSessionData('functionalAI');

        if (images) setPcbImages(images);
        if (result) setPcbResult(result);
        if (schematics) setSchematicInfo(schematics);
        if (functional) setFunctionalAI(functional);
      } catch (e) {
        console.error("Failed to load persistence", e);
      } finally {
        setIsLoaded(true);
      }
    };
    loadPersistedData();
  }, []);

  // Guardado automático al cambiar estados
  useEffect(() => {
    if (isLoaded) {
      saveSessionData('pcbImages', pcbImages);
      saveSessionData('pcbResult', pcbResult);
      saveSessionData('schematicInfo', schematicInfo);
      saveSessionData('functionalAI', functionalAI);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, isLoaded]);

  const clearSession = async () => {
    if (pcbResult) {
      await saveRepairToHistory({ pcbResult, pcbImages });
    }
    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    await clearSessionStorage();
  };

  if (!isLoaded) return <div className="h-screen w-full bg-background-dark flex items-center justify-center">
    <div className="flex flex-col items-center gap-4">
      <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      <p className="text-text-secondary font-mono text-sm">Recuperando sesión de trabajo...</p>
    </div>
  </div>;

  return (
    <HashRouter>
      <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display">
        <Sidebar onNewRepair={clearSession} />
        <div className="flex-1 flex flex-col min-w-0 relative">
          <Header />
          <main className="flex-1 overflow-hidden relative">
            <Routes>
              <Route path="/" element={<Dashboard onStart={clearSession} />} />
              <Route path="/pcb-id" 
                element={
                  <PCBIdentification 
                    persistedImages={pcbImages} 
                    persistedResult={pcbResult}
                    onUpdate={(imgs, res, schematics, functional) => {
                      setPcbImages(imgs);
                      setPcbResult(res);
                      if (schematics) setSchematicInfo(schematics);
                      if (functional) setFunctionalAI(functional);
                    }}
                  />
                } 
              />
              <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
              <Route path="/measure" element={<GuidedMeasurement pcbImages={pcbImages} pcbResult={pcbResult} functionalAI={functionalAI} />} />
              <Route path="/diagnostics" element={<DiagnosticDecisionTree />} />
              <Route path="/component" element={<ComponentDetails />} />
              <Route path="/database" element={<DatabaseScreen />} />
            </Routes>
          </main>

          <ChatBot />

          <button 
            onClick={() => setIsLiveOpen(true)}
            className="fixed bottom-6 right-20 z-50 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 transition-transform flex items-center justify-center"
          >
            <span className="material-symbols-outlined text-white">mic</span>
          </button>

          {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
        </div>
      </div>
    </HashRouter>
  );
};

export default App;

