const GuidedMeasurement: React.FC<GuidedMeasurementProps> = ({ pcbImages, pcbResult, functionalAI }) => {
  const [points, setPoints] = useState<MeasurementPoint[]>([]);
  const [activeIdx, setActiveIdx] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [isVerdictLoading, setIsVerdictLoading] = useState(false);
  const [verdict, setVerdict] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
    const initPlan = async () => {
      if (pcbResult && functionalAI) {
        setIsLoading(true);
        try {
          const plan = await generateMeasurementPlan(pcbResult, functionalAI);
          setPoints(plan.map(p => ({ ...p, status: 'pending' })));
        } catch (e) {
          console.error("Failed to generate plan", e);
        } finally {
          setIsLoading(false);
        }
      }
    };
    initPlan();
  }, [pcbResult, functionalAI]);

  const handleValueChange = (val: string) => {
    const newPoints = [...points];
    newPoints[activeIdx].measuredValue = val;

    // Validación básica simplificada (la IA hará el análisis final profundo)
    const expected = parseFloat(newPoints[activeIdx].expectedValue);
    const measured = parseFloat(val);

    if (!isNaN(measured)) {
      if (measured < 0.01 && expected > 0.1) newPoints[activeIdx].status = 'fail';
      else newPoints[activeIdx].status = 'ok';
    } else {
      newPoints[activeIdx].status = 'pending';
    }

    setPoints(newPoints);
  };

  const handleSpeak = async () => {
    if (!points[activeIdx]) return;
    const current = points[activeIdx];
    const text = `Técnico, por favor localice el componente ${current.component}. Medición requerida en ${current.testPoint} modo ${current.mode === 'V' ? 'Voltaje' : 'Diodo'}. El valor esperado es de ${current.expectedValue}. ${current.description}`;

    setIsPlaying(true);
    await textToSpeech(text, (buffer) => {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);
      source.start();
    });
  };

  const generateVerdict = async () => {
    setIsVerdictLoading(true);
    try {
      const res = await getFinalVerdict(pcbResult, points);
      setVerdict(res);
    } catch (e) {
      alert("Error al generar veredicto");
    } finally {
      setIsVerdictLoading(false);
    }
  };

  if (!pcbResult) return (
    <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
      <span className="material-symbols-outlined text-8xl mb-4">analytics</span>
      <h2 className="text-2xl font-bold">Primero Analice una Placa</h2>
      <p className="mt-2">Vaya a PCB Analyzer para identificar el hardware antes de medir.</p>
      <Link to="/pcb-id" className="mt-6 px-6 py-3 bg-primary rounded-xl text-white font-bold">Ir al Analizador</Link>
    </div>
  );

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-[#0f1219]">
      {/* Visor de Placa Real */}
      <div className="flex-1 relative overflow-hidden flex flex-col bg-black">
        <div className="w-full h-full relative overflow-hidden flex items-center justify-center">
          {pcbImages.length > 0 ? (
            <div className="relative w-full h-full">
              <img 
                src={pcbImages[0]} 
                alt="PCB View" 
                className="w-full h-full object-contain opacity-70"
              />
              <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>

              {/* Overlay de puntero IA */}
              {points[activeIdx] && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="relative">
                    <div className="size-20 border-2 border-primary rounded-full animate-ping opacity-50"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 size-4 bg-primary rounded-full shadow-[0_0_20px_#135bec]"></div>
                    <div className="absolute top-12 left-1/2 -translate-x-1/2 bg-primary px-3 py-1 rounded text-[10px] font-bold whitespace-nowrap">
                      ZONA: {points[activeIdx].component}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="text-text-secondary italic">No hay imagen disponible</div>
          )}

          <div className="absolute bottom-6 left-6 flex gap-4">
             <button onClick={handleSpeak} className={`p-4 rounded-full bg-primary text-white shadow-xl flex items-center gap-2 ${isPlaying ? 'animate-pulse' : ''}`}>
               <span className="material-symbols-outlined">{isPlaying ? 'graphic_eq' : 'volume_up'}</span>
               <span className="text-xs font-bold">Asistente Vocal</span>
             </button>
          </div>
        </div>
      </div>

      {/* Panel de Control de Mediciones */}
      <div className="w-full lg:w-[450px] bg-[#111722] border-l border-[#232f48] flex flex-col h-full z-20 shadow-2xl overflow-y-auto">
        <div className="p-6 border-b border-[#232f48] bg-surface-dark/50">
          <span className="text-[10px] uppercase tracking-[0.2em] font-bold text-primary">Protocolo de Laboratorio</span>
          <h2 className="text-xl font-bold text-white mt-1">Guía de Medición Sistemática</h2>
          <p className="text-xs text-text-secondary mt-1">Placa: {pcbResult.model} ({pcbResult.boardNumber})</p>
        </div>

        <div className="flex-1 p-6 space-y-6">
          {isLoading ? (
            <div className="space-y-4 animate-pulse">
              {[1, 2, 3].map(i => <div key={i} className="h-20 bg-border-dark rounded-xl"></div>)}
            </div>
          ) : (
            <div className="space-y-4">
              {points.map((p, idx) => (
                <div 
                  key={p.id}
                  onClick={() => setActiveIdx(idx)}
                  className={`p-4 rounded-xl border transition-all cursor-pointer ${activeIdx === idx ? 'bg-primary/10 border-primary ring-1 ring-primary/30' : 'bg-surface-dark border-border-dark hover:border-white/20'}`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex gap-3">
                      <div className={`size-8 rounded flex items-center justify-center font-bold text-xs ${p.status === 'ok' ? 'bg-green-500/20 text-green-500' : p.status === 'fail' ? 'bg-red-500/20 text-red-500' : 'bg-white/5 text-white/40'}`}>
                        {idx + 1}
                      </div>
                      <div>
                        <h4 className="text-sm font-bold text-white">{p.component} - {p.testPoint}</h4>
                        <p className="text-[10px] text-text-secondary mt-0.5">{p.mode === 'V' ? 'Modo Voltaje' : 'Modo Diodo'}</p>
                      </div>
                    </div>
                    <div className="text-right">
                       <span className="text-[10px] font-mono text-primary">{p.expectedValue} Exp.</span>
                    </div>
                  </div>

                  {activeIdx === idx && (
                    <div className="mt-4 space-y-3 animate-in fade-in slide-in-from-top-2">
                       <p className="text-xs text-text-secondary leading-relaxed italic border-l-2 border-primary/40 pl-3">{p.description}</p>
                       <div className="relative">
                          <input 
                            value={p.measuredValue || ''}
                            onChange={(e) => handleValueChange(e.target.value)}
                            placeholder="0.000"
                            autoFocus
                            className="w-full bg-black/40 border border-border-dark rounded-lg p-3 text-xl font-mono font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                          />
                          <span className="absolute right-3 top-1/2 -translate-y-1/2 font-bold text-primary">{p.mode}</span>
                       </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

          {verdict && (
            <div className="bg-primary/10 border border-primary/30 p-5 rounded-2xl animate-in zoom-in-95">
               <h3 className="font-bold flex items-center gap-2 mb-2 text-primary">
                 <span className="material-symbols-outlined">gavel</span>
                 Veredicto IA Gusrepart
               </h3>
               <div className="text-xs text-text-secondary leading-relaxed whitespace-pre-wrap">
                 {verdict}
               </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-[#232f48] bg-surface-dark/80 backdrop-blur-md">
          {points.every(p => p.measuredValue) ? (
            <button 
              onClick={generateVerdict}
              disabled={isVerdictLoading}
              className="w-full bg-primary hover:bg-primary-hover text-white py-4 rounded-xl font-bold shadow-xl shadow-primary/25 transition-all flex items-center justify-center gap-2 group text-lg disabled:opacity-50"
            >
              <span className="material-symbols-outlined">{isVerdictLoading ? 'sync' : 'psychology_alt'}</span>
              <span>{isVerdictLoading ? 'Analizando mediciones...' : 'Generar Diagnóstico Final'}</span>
