import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { saveRepairToHistory } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const ImageEditorModal = ({ 
  image, 
  onSave, 
  onClose 
}: { 
  image: string; 
  onSave: (newImage: string) => void; 
  onClose: () => void;
}) => {
  const [zoom, setZoom] = useState(1);
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const handleEnhance = async () => {
    setIsEnhancing(true);
    try {
      const pureBase64 = image.split(',')[1];
      const improved = await enhancePCBImage(pureBase64);
      onSave(improved);
    } catch (e) {
      alert("Error al mejorar la imagen con IA.");
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleCrop = () => {
    if (!canvasRef.current || !containerRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.src = image;
    img.onload = () => {
      // Calculamos el área visible basada en zoom y offset
      // Para simplificar, capturamos el centro según el zoom actual
      canvas.width = 1024;
      canvas.height = 1024;
      if (ctx) {
        ctx.fillStyle = "#000";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Simulación de recorte centralizado
        const sSize = Math.min(img.width, img.height) / zoom;
        const sx = (img.width - sSize) / 2;
        const sy = (img.height - sSize) / 2;

        ctx.drawImage(img, sx, sy, sSize, sSize, 0, 0, 1024, 1024);
        onSave(canvas.toDataURL('image/jpeg', 0.9));
      }
    };
  };

  return (
    <div className="fixed inset-0 z-[110] bg-black/95 flex flex-col backdrop-blur-md">
      <div className="p-4 border-b border-white/10 flex justify-between items-center bg-[#111722]">
        <h3 className="font-bold flex items-center gap-2">
          <span className="material-symbols-outlined text-primary">edit_square</span>
          Editor de Inspección
        </h3>
        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
          <span className="material-symbols-outlined">close</span>
        </button>
      </div>

      <div className="flex-1 relative overflow-hidden flex items-center justify-center p-4">
        <div 
          ref={containerRef}
          className="relative max-w-full max-h-full transition-transform duration-200"
          style={{ transform: `scale(${zoom})`, cursor: 'move' }}
        >
          <img src={image} alt="Editor" className="rounded-lg shadow-2xl max-w-full max-h-[70vh] object-contain" />
        </div>

        {isEnhancing && (
          <div className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center gap-4 z-10">
            <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
            <p className="text-primary font-bold animate-pulse">IA Gusrepart: Optimizando Micro-detalles...</p>
          </div>
        )}
      </div>

      <div className="p-6 bg-[#111722] border-t border-white/10 flex flex-col gap-6">
        <div className="flex items-center gap-4 max-w-md mx-auto w-full">
          <span className="material-symbols-outlined text-text-secondary">zoom_out</span>
          <input 
            type="range" 
            min="1" max="5" step="0.1" 
            value={zoom} 
            onChange={(e) => setZoom(parseFloat(e.target.value))}
            className="flex-1 accent-primary" 
          />
          <span className="material-symbols-outlined text-text-secondary">zoom_in</span>
          <span className="text-xs font-mono text-primary w-12">{zoom.toFixed(1)}x</span>
        </div>

        <div className="flex flex-wrap justify-center gap-4">
          <button 
            onClick={handleCrop}
            className="px-6 py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-sm font-bold flex items-center gap-2 transition-all"
          >
            <span className="material-symbols-outlined text-lg">crop</span>
            Aplicar Recorte
          </button>

          <button 
            onClick={handleEnhance}
            disabled={isEnhancing}
            className="px-6 py-3 bg-primary hover:bg-primary-hover rounded-xl text-sm font-bold flex items-center gap-2 shadow-lg shadow-primary/20 transition-all disabled:opacity-50"
          >
            <span className="material-symbols-outlined text-lg">auto_fix_high</span>
            Mejorar Calidad IA
          </button>
        </div>
      </div>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [images, setImages] = useState<string[]>(persistedImages);
  const [result, setResult] = useState<PCBAnalysisResult | any>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [editingIndex, setEditingIndex] = useState<number | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      setActiveSlot(null);
    };
    reader.readAsDataURL(file);
  };

  const runAnalysis = async () => {
    if (images.length === 0) return;
    setIsAnalyzing(true);
    setSaveSuccess(false);
    setStatus("Analizando visualmente la PCB...");
    try {
      const pureBase64s = images.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);

      setStatus("Buscando esquemas técnicos en la web...");
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);

      setStatus("Generando modelo funcional con IA...");
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);

      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error("Analysis failed", error);
      setStatus("Error en el análisis.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const handleSaveToDatabase = async () => {
    if (!result) return;
    setIsSaving(true);
    try {
      await saveRepairToHistory({
        pcbResult: result,
        pcbImages: images,
        timestamp: Date.now()
      });
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (e) {
      alert("Error al guardar en la base de datos");
    } finally {
      setIsSaving(false);
    }
  };

  const handleEditorSave = (newImage: string) => {
    if (editingIndex === null) return;
    const newImages = [...images];
    newImages[editingIndex] = newImage;
    setImages(newImages);
    setEditingIndex(null);
    onUpdate(newImages, result);
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden">
      {editingIndex !== null && (
        <ImageEditorModal 
          image={images[editingIndex]} 
          onSave={handleEditorSave}
          onClose={() => setEditingIndex(null)}
        />
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black leading-tight tracking-tight">Inspección de Hardware AI</h1>
            <p className="text-[#92a4c9] text-base font-normal">Sube fotos nítidas para detectar fallos físicos y obtener esquemas automáticos.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 min-h-[400px]">
            {[0, 1].map((slot) => (
              <div 
                key={slot}
                className={`relative flex flex-col items-center justify-center gap-4 rounded-xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-[#324467]'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden cursor-pointer`}
              >
                {images[slot] ? (
                  <>
                    <img src={images[slot]} alt={`PCB ${slot + 1}`} className="absolute inset-0 w-full h-full object-cover opacity-80" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
                      <button 
                        onClick={(e) => { e.stopPropagation(); setEditingIndex(slot); }} 
                        className="p-3 bg-primary/20 hover:bg-primary/40 rounded-full backdrop-blur-md text-primary"
                        title="Editar / Zoom / IA"
                      >
                        <span className="material-symbols-outlined">edit</span>
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); const n = [...images]; n.splice(slot, 1); setImages(n.filter(Boolean)); }} 
                        className="p-3 bg-red-500/20 hover:bg-red-500/40 rounded-full backdrop-blur-md text-red-500"
                        title="Eliminar"
                      >
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <div 
                    /* Fix: Use a proper function block instead of logical expression to avoid truthiness check errors with void functions */
                    onClick={() => {
                      if (!isAnalyzing) {
                        setActiveSlot(slot);
                        fileInputRef.current?.click();
                      }
                    }}
                    className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center"
                  >
                    <div className="size-14 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform">
                      <span className="material-symbols-outlined text-3xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-[#92a4c9]">{slot === 0 ? 'Frente de Placa' : 'Reverso de Placa'}</p>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col items-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse">{status}</p>}
             <button 
              onClick={runAnalysis}
              disabled={images.length === 0 || isAnalyzing}
              className={`px-12 py-4 rounded-xl font-bold text-lg flex items-center gap-3 transition-all ${isAnalyzing ? 'bg-primary/50 cursor-wait' : 'bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 hover:translate-y-[-2px] disabled:opacity-30 disabled:cursor-not-allowed'}`}
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'search_check'}</span>
               <span>{isAnalyzing ? 'Procesando...' : 'Analizar e Identificar'}</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] xl:w-[480px] bg-background-dark flex flex-col shrink-0 border-t lg:border-t-0 overflow-y-auto">
        <div className="p-6 flex flex-col gap-6 h-full">
          <h2 className="text-xl font-bold leading-tight flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">analytics</span>
            Diagnóstico de Visión
          </h2>

          {result ? (
            <div className="space-y-6">
              <div className="space-y-4">
                <div className="bg-border-dark/50 p-4 rounded-xl border border-white/5 relative">
                  <p className="text-[10px] uppercase font-bold text-text-secondary mb-2 tracking-widest">Hardware ID</p>
                  <p className="text-white font-bold">{result.manufacturer} {result.model}</p>
                  <p className="text-primary text-xs font-mono mt-1">{result.boardNumber}</p>

                  <button 
                    onClick={handleSaveToDatabase}
                    disabled={isSaving}
                    className={`absolute top-4 right-4 p-2 rounded-lg transition-all ${saveSuccess ? 'bg-green-500 text-white' : 'bg-primary/10 text-primary hover:bg-primary/20'}`}
                    title="Guardar en Base de Datos"
                  >
                    <span className="material-symbols-outlined text-sm">{saveSuccess ? 'check' : 'save'}</span>
                  </button>
                </div>

                {result.detectedAnomalies && result.detectedAnomalies.length > 0 && (
                  <div className="bg-red-500/10 p-4 rounded-xl border border-red-500/20">
                    <p className="text-[10px] uppercase font-bold text-red-500 mb-2 tracking-widest">Anomalías Detectadas</p>
                    <ul className="space-y-2">
                      {result.detectedAnomalies.map((a: string, i: number) => (
                        <li key={i} className="text-xs text-red-200/80 flex items-start gap-2">
                          <span className="material-symbols-outlined text-[14px] mt-0.5">warning</span>
                          {a}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>

              <div className="space-y-3">
                <p className="text-[10px] uppercase font-bold text-text-secondary tracking-widest">Componentes Identificados</p>
                <div className="flex flex-wrap gap-2">
                  {result.identifiedComponents.map((c: string, i: number) => (
                    <span key={i} className="px-2 py-1 bg-surface-dark border border-white/5 rounded text-[10px] font-mono text-white/70">
                      {c}
                    </span>
                  ))}
                </div>
              </div>

              <div className="flex flex-col gap-3">
                <Link to="/boardview" className="w-full flex items-center justify-center gap-2 rounded-xl bg-primary h-14 text-white font-bold text-sm tracking-wide shadow-xl shadow-primary/25 hover:bg-blue-600 transition-all">
                  <span>Ir a Esquemas y Boardview</span>
                  <span className="material-symbols-outlined text-lg">arrow_forward</span>
                </Link>
                {saveSuccess && (
                  <p className="text-center text-green-400 text-[10px] font-bold animate-fade-in">¡Guardado en Base de Datos!</p>
                )}
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center py-20 text-center opacity-20">
              <span className="material-symbols-outlined text-7xl mb-4">memory</span>
              <p className="max-w-[200px]">Los resultados aparecerán tras el análisis.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

