const DB_NAME = 'GusrepartDB';
const DB_VERSION = 1;
const STORE_NAME = 'session';

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveSessionData = async (key: string, data: any) => {
  const db = await initDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put(data, key);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
};

export const getSessionData = async (key: string): Promise<any> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(key);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const deleteSessionData = async (key: string) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).delete(key);
};

export const clearSessionStorage = async () => {
  await deleteSessionData('pcbImages');
  await deleteSessionData('pcbResult');
  await deleteSessionData('schematicInfo');
  await deleteSessionData('functionalAI');
  await deleteSessionData('measurements');
  await deleteSessionData('diagHistory');
};

export const saveRepairToHistory = async (repair: any) => {
  const db = await initDB();
  const history = (await getSessionData('history')) || [];

  // Si ya existe (estamos editando), lo actualizamos por timestamp o ID
  const existingIndex = history.findIndex((h: any) => h.timestamp === repair.timestamp);

  if (existingIndex >= 0) {
    history[existingIndex] = { ...repair, lastModified: Date.now() };
  } else {
    history.push({ ...repair, timestamp: repair.timestamp || Date.now() });
  }

  await saveSessionData('history', history);
};

export const findSimilarRepairs = async (model: string) => {
  const history = (await getSessionData('history')) || [];
  if (!model) return [];
  return history.filter((h: any) => 
    h.pcbResult?.model?.toLowerCase().includes(model.toLowerCase()) ||
    h.pcbResult?.boardNumber?.toLowerCase().includes(model.toLowerCase())
  );
};

import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs } from "./storage";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const ai = getAI();

  // BUSQUEDA DE MEMORIA LOCAL
  let localContext = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) {
      localContext = `HISTORIAL DEL TALLER: Se han encontrado ${similar.length} reparaciones similares de este modelo. Resultados previos: ${similar.map(s => s.pcbResult.detectedAnomalies.join(", ")).join("; ")}.`;
    }
  }

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [
      ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
      { role: 'user', parts: [{ text: currentIssue }] }
    ],
    config: {
      systemInstruction: `Eres Gusrepart AI, experto en microelectrónica. ${localContext} Usa estos datos históricos para ser más preciso. Si el historial indica fallos comunes, menciónalos.`,
      thinkingConfig: { thinkingBudget: 32768 }
    }
  });
  return response.text;
};

// ... (resto de funciones generateMeasurementPlan, analyzePCBImage, etc se mantienen iguales)
export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string): Promise<MeasurementPoint[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Basado en este análisis de hardware: ${JSON.stringify(pcbResult)} y este análisis funcional: ${functionalAnalysis}, genera un plan de 4 a 6 puntos de medición críticos para diagnosticar la placa. Devuelve un JSON array de objetos con: id, component, testPoint, mode (V, Diode, Ohm), expectedValue (ej: "0.450V", "12V"), description (por qué medir esto).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            component: { type: Type.STRING },
            testPoint: { type: Type.STRING },
            mode: { type: Type.STRING },
            expectedValue: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["id", "component", "testPoint", "mode", "expectedValue", "description"]
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

export const getFinalVerdict = async (pcbResult: any, measurements: MeasurementPoint[]): Promise<string> => {
  const ai = getAI();
  const data = {
    board: pcbResult,
    measurements: measurements.map(m => ({
      ponto: m.component,
      esperado: m.expectedValue,
      medido: m.measuredValue,
      descripcion: m.description
    }))
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analiza estos resultados de laboratorio: ${JSON.stringify(data)}. Da un veredicto final de reparación: 1. Causa probable. 2. Componente defectuoso. 3. Pasos para la solución. Sé muy técnico y preciso.`,
    config: { thinkingConfig: { thinkingBudget: 10000 } }
  });

  return response.text || "No se pudo generar un veredicto.";
};

export const enhancePCBImage = async (base64Image: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image,
            mimeType: 'image/jpeg',
          },
        },
        {
          text: 'Actúa como un sistema de mejora de imágenes para microelectrónica. Procesa esta imagen de PCB para: 1. Aumentar la nitidez de los bordes de los componentes. 2. Reducir el ruido del sensor. 3. Resaltar los números de serie y marcas en los integrados. Devuelve únicamente la imagen mejorada.',
        },
      ],
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No se pudo generar la imagen mejorada");
};

export const analyzePCBImage = async (base64Images: string[]): Promise<any> => {
  const ai = getAI();

  const imageParts = base64Images.map(base64 => ({
    inlineData: { data: base64, mimeType: 'image/jpeg' }
  }));

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        role: 'user',
        parts: [
          ...imageParts,
          { text: "Analiza estas imágenes de una PCB. 1. Identifica fabricante, modelo y board number. 2. Identifica componentes críticos. 3. Busca visualmente posibles fallos (corrosión, componentes quemados, decoloración). 4. Devuelve un JSON con: manufacturer, model, boardNumber, confidence, identifiedComponents, detectedAnomalies (array de strings)." }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { type: Type.ARRAY, items: { type: Type.STRING } },
          detectedAnomalies: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents", "detectedAnomalies"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

