import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getSessionData, saveSessionData, deleteRepairFromHistory } from '../services/storage';

interface DatabaseScreenProps {
  onLoadRepair: (repair: any) => void;
}

const DatabaseScreen: React.FC<DatabaseScreenProps> = ({ onLoadRepair }) => {
  const [history, setHistory] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'history' | 'components' | 'schematics'>('history');
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    const data = await getSessionData('history');
    if (data) {
      setHistory([...data].sort((a, b) => b.timestamp - a.timestamp));
    }
    setIsLoading(false);
  };

  const handleDeleteItem = async (e: React.MouseEvent, timestamp: number, model: string) => {
    e.stopPropagation();
    if (window.confirm(`¿Seguro que quieres eliminar la reparación de "${model}"? Esta acción es irreversible.`)) {
      await deleteRepairFromHistory(timestamp);
      await loadData();
    }
  };

  const handleClearAll = async () => {
    if (window.confirm("¡ATENCIÓN! Estás a punto de borrar TODO el historial de reparaciones. ¿Proceder?")) {
      await saveSessionData('history', []);
      setHistory([]);
    }
  };

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
      <div className="max-w-6xl mx-auto flex flex-col gap-8">
        <div className="flex justify-between items-end border-b border-border-dark pb-6">
          <div className="flex flex-col gap-2">
            <h1 className="text-4xl font-black text-white">Base de Datos Local</h1>
            <p className="text-text-secondary font-medium">Historial inmutable y librería técnica.</p>
          </div>
          <div className="flex bg-border-dark p-1 rounded-xl">
            {(['history', 'components', 'schematics'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === tab ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-text-secondary hover:text-white'}`}
              >
                {tab === 'history' ? 'Historial' : tab === 'components' ? 'Librería' : 'Esquemas'}
              </button>
            ))}
          </div>
        </div>

        {activeTab === 'history' && (
          <div className="flex flex-col gap-6">
            {history.length > 0 && (
              <div className="flex justify-end">
                <button 
                  onClick={handleClearAll}
                  className="px-4 py-2 bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/20 rounded-lg text-xs font-bold transition-all flex items-center gap-2"
                >
                  <span className="material-symbols-outlined text-[16px]">delete_forever</span>
                  Vaciar Historial Completo
                </button>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {isLoading ? (
                <div className="col-span-full py-20 text-center animate-pulse text-text-secondary font-mono">Indexando base de datos...</div>
              ) : history.length === 0 ? (
                <div className="col-span-full py-24 text-center bg-surface-dark/30 rounded-3xl border-2 border-dashed border-border-dark">
                  <span className="material-symbols-outlined text-7xl text-primary/20 mb-4">database_off</span>
                  <p className="text-text-secondary font-bold">No hay registros de reparaciones.</p>
                </div>
              ) : (
                history.map((item) => (
                  <div key={item.timestamp} className="bg-surface-dark border border-border-dark rounded-2xl overflow-hidden group hover:border-primary/50 transition-all flex flex-col shadow-xl">
                    <div className="h-44 bg-black/40 relative">
                      {item.pcbImages?.[0] ? (
                        <img src={item.pcbImages[0]} className="w-full h-full object-cover opacity-60 group-hover:opacity-80 transition-opacity" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-slate-900/50">
                          <span className="material-symbols-outlined text-6xl text-white/5 font-light">memory</span>
                        </div>
                      )}
                      <button 
                        onClick={(e) => handleDeleteItem(e, item.timestamp, item.pcbResult?.model)}
                        className="absolute top-3 right-3 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity hover:scale-110 shadow-lg"
                        title="Eliminar permanentemente"
                      >
                        <span className="material-symbols-outlined text-[18px]">delete</span>
                      </button>
                    </div>
                    <div className="p-5 flex-1 flex flex-col">
                      <div className="mb-4">
                        <h3 className="text-lg font-bold text-white truncate">{item.pcbResult?.model}</h3>
                        <p className="text-xs text-primary font-mono">{item.pcbResult?.boardNumber}</p>
                      </div>
                      <div className="flex flex-wrap gap-1 mb-4">
                        {item.pcbResult?.identifiedComponents?.slice(0, 3).map((c: any, i: number) => (
                          <span key={i} className="text-[9px] bg-border-dark px-2 py-0.5 rounded text-white/60">{c}</span>
                        ))}
                      </div>
                      <div className="mt-auto pt-4 flex items-center justify-between border-t border-white/5">
                        <span className="text-[10px] text-text-secondary font-medium">{new Date(item.timestamp).toLocaleDateString()}</span>
                        <button 
                          onClick={() => { onLoadRepair(item); navigate('/pcb-id'); }}
                          className="px-4 py-2 bg-primary hover:bg-primary-hover text-white rounded-lg text-[11px] font-bold shadow-lg shadow-primary/20 transition-all"
                        >
                          Retomar Reparación
                        </button>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DatabaseScreen;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { generateMeasurementPlan, getFinalVerdict, textToSpeech } from '../services/gemini';
import { MeasurementPoint } from '../types';

interface GuidedMeasurementProps {
  pcbImages: string[];
  pcbResult: any;
  functionalAI: string;
  persistedPoints: MeasurementPoint[];
  onUpdate: (points: MeasurementPoint[]) => void;
}

const GuidedMeasurement: React.FC<GuidedMeasurementProps> = ({ pcbImages, pcbResult, functionalAI, persistedPoints, onUpdate }) => {
  const [points, setPoints] = useState<MeasurementPoint[]>(persistedPoints || []);
  const [activeIdx, setActiveIdx] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [isVerdictLoading, setIsVerdictLoading] = useState(false);
  const [verdict, setVerdict] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
    const initPlan = async () => {
      if (pcbResult && functionalAI && points.length === 0) {
        setIsLoading(true);
        try {
          const plan = await generateMeasurementPlan(pcbResult, functionalAI);
          const formatted = plan.map(p => ({ ...p, status: 'pending' }));
          setPoints(formatted);
          onUpdate(formatted);
        } catch (e) {
          console.error("Failed to generate plan", e);
        } finally {
          setIsLoading(false);
        }
      }
    };
    initPlan();
  }, [pcbResult, functionalAI]);

  const handleValueChange = (val: string) => {
    const newPoints = [...points];
    newPoints[activeIdx].measuredValue = val;

    const expected = parseFloat(newPoints[activeIdx].expectedValue);
    const measured = parseFloat(val);

    if (!isNaN(measured)) {
      if (measured < 0.01 && expected > 0.1) newPoints[activeIdx].status = 'fail';
      else newPoints[activeIdx].status = 'ok';
    } else {
      newPoints[activeIdx].status = 'pending';
    }

    setPoints(newPoints);
    onUpdate(newPoints);
  };

  const handleSpeak = async () => {
    if (!points[activeIdx]) return;
    const current = points[activeIdx];
    const text = `Técnico, por favor localice el componente ${current.component}. Medición requerida en ${current.testPoint} modo ${current.mode === 'V' ? 'Voltaje' : 'Diodo'}. El valor esperado es de ${current.expectedValue}. ${current.description}`;

    setIsPlaying(true);
    await textToSpeech(text, (buffer) => {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);
      source.start();
    });
  };

  const generateVerdict = async () => {
    setIsVerdictLoading(true);
    try {
      const res = await getFinalVerdict(pcbResult, points);
      setVerdict(res);
    } catch (e) {
      alert("Error al generar veredicto");
    } finally {
      setIsVerdictLoading(false);
    }
  };

  if (!pcbResult) return (
    <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
      <span className="material-symbols-outlined text-8xl mb-4">analytics</span>
      <h2 className="text-2xl font-bold">Primero Analice una Placa</h2>
      <Link to="/pcb-id" className="mt-6 px-6 py-3 bg-primary rounded-xl text-white font-bold">Ir al Analizador</Link>
    </div>
  );

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-[#0f1219]">
      <div className="flex-1 relative overflow-hidden flex flex-col bg-black">
        <div className="w-full h-full relative overflow-hidden flex items-center justify-center">
          {pcbImages.length > 0 ? (
            <div className="relative w-full h-full">
              <img src={pcbImages[0]} alt="PCB View" className="w-full h-full object-contain opacity-70" />
              <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>
              {points[activeIdx] && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="relative">
                    <div className="size-20 border-2 border-primary rounded-full animate-ping opacity-50"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 size-4 bg-primary rounded-full shadow-[0_0_20px_#135bec]"></div>
                    <div className="absolute top-12 left-1/2 -translate-x-1/2 bg-primary px-3 py-1 rounded text-[10px] font-bold whitespace-nowrap uppercase tracking-wider">
                       Test: {points[activeIdx].component}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="text-text-secondary italic">Imagen de referencia no disponible</div>
          )}

          <div className="absolute bottom-6 left-6 flex gap-4">
             <button onClick={handleSpeak} className={`p-4 rounded-full bg-primary text-white shadow-xl flex items-center gap-2 ${isPlaying ? 'animate-pulse' : ''}`}>
               <span className="material-symbols-outlined">{isPlaying ? 'graphic_eq' : 'volume_up'}</span>
               <span className="text-xs font-bold">Voz IA</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[450px] bg-[#111722] border-l border-[#232f48] flex flex-col h-full z-20 shadow-2xl overflow-y-auto">
        <div className="p-6 border-b border-[#232f48] bg-surface-dark/50">
          <span className="text-[10px] uppercase tracking-[0.2em] font-bold text-primary">Diagnóstico Sistemático</span>
          <h2 className="text-xl font-bold text-white mt-1">Guía de Medición</h2>
        </div>

        <div className="flex-1 p-6 space-y-6">
          {isLoading ? (
            <div className="space-y-4 animate-pulse">
              {[1, 2, 3].map(i => <div key={i} className="h-24 bg-border-dark rounded-xl"></div>)}
            </div>
          ) : (
            <div className="space-y-4">
              {points.map((p, idx) => (
                <div 
                  key={p.id}
                  onClick={() => setActiveIdx(idx)}
                  className={`p-4 rounded-xl border transition-all cursor-pointer ${activeIdx === idx ? 'bg-primary/10 border-primary shadow-[0_0_15px_rgba(19,91,236,0.1)]' : 'bg-surface-dark border-border-dark hover:border-white/10'}`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex gap-3">
                      <div className={`size-8 rounded flex items-center justify-center font-bold text-xs ${p.status === 'ok' ? 'bg-green-500/20 text-green-500' : p.status === 'fail' ? 'bg-red-500/20 text-red-500' : 'bg-white/5 text-white/40'}`}>
                        {idx + 1}
                      </div>
                      <div>
                        <h4 className="text-sm font-bold text-white uppercase">{p.component}</h4>
                        <p className="text-[10px] text-text-secondary mt-0.5">{p.testPoint} | Modo {p.mode}</p>
                      </div>
                    </div>
                    <span className="text-[10px] font-mono text-primary font-bold">{p.expectedValue} Exp.</span>
                  </div>

                  {activeIdx === idx && (
                    <div className="mt-4 space-y-3">
                       <p className="text-[11px] text-text-secondary leading-relaxed italic border-l-2 border-primary/40 pl-3">{p.description}</p>
                       <div className="relative">
                          <input 
                            value={p.measuredValue || ''}
                            onChange={(e) => handleValueChange(e.target.value)}
                            placeholder="0.000"
                            autoFocus
                            className={`w-full bg-black/40 border ${p.status === 'fail' ? 'border-red-500/50' : 'border-border-dark'} rounded-lg p-3 text-xl font-mono font-bold text-white focus:ring-1 focus:ring-primary outline-none`}
                          />
                          <span className="absolute right-3 top-1/2 -translate-y-1/2 font-bold text-primary text-sm">{p.mode}</span>
                       </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

          {verdict && (
            <div className="bg-primary/10 border border-primary/30 p-5 rounded-2xl animate-in zoom-in-95">
               <h3 className="font-bold flex items-center gap-2 mb-2 text-primary">
                 <span className="material-symbols-outlined">gavel</span>
                 Diagnóstico Final AI
               </h3>
               <div className="text-xs text-text-secondary leading-relaxed whitespace-pre-wrap font-medium">
                 {verdict}
               </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-[#232f48] bg-surface-dark/80 backdrop-blur-md sticky bottom-0">
          {points.length > 0 && points.every(p => p.measuredValue) ? (
            <button 
              onClick={generateVerdict}
              disabled={isVerdictLoading}
              className="w-full bg-primary hover:bg-primary-hover text-white py-4 rounded-xl font-bold shadow-xl shadow-primary/20 transition-all flex items-center justify-center gap-2 group text-lg disabled:opacity-50"
            >
              <span className="material-symbols-outlined">{isVerdictLoading ? 'sync' : 'verified'}</span>
              <span>{isVerdictLoading ? 'Procesando...' : 'Obtener Veredicto'}</span>
            </button>
          ) : (
             <div className="text-center py-2">
                <p className="text-[10px] text-text-secondary font-bold uppercase tracking-widest mb-2">Faltan Mediciones</p>
                <div className="flex gap-1.5 justify-center">
                  {points.map((p, i) => (
                    <div key={i} className={`size-1.5 rounded-full transition-colors ${p.measuredValue ? 'bg-primary' : 'bg-border-dark'}`}></div>
                  ))}
                </div>
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default GuidedMeasurement;

import React, { useState, useEffect, useRef } from 'react';
import { getDiagnosticAdvice } from '../services/gemini';
import { DiagnosticTurn } from '../types';

interface DiagnosticProps {
  persistedHistory: DiagnosticTurn[];
  pcbResult: any;
  onUpdate: (history: DiagnosticTurn[]) => void;
}

const DiagnosticDecisionTree: React.FC<DiagnosticProps> = ({ persistedHistory, pcbResult, onUpdate }) => {
  const [history, setHistory] = useState<DiagnosticTurn[]>(persistedHistory || []);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo(0, scrollRef.current.scrollHeight);
    onUpdate(history);
  }, [history]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userTurn: DiagnosticTurn = {
      role: 'user',
      content: input,
      timestamp: Date.now()
    };

    setHistory(prev => [...prev, userTurn]);
    setInput("");
    setIsLoading(true);

    try {
      const advice = await getDiagnosticAdvice(
        history.map(h => ({ role: h.role === 'user' ? 'user' : 'assistant', content: h.content })), 
        input, 
        pcbResult?.model
      );
      const assistantTurn: DiagnosticTurn = {
        role: 'assistant',
        content: advice || "No pude procesar la respuesta.",
        timestamp: Date.now()
      };
      setHistory(prev => [...prev, assistantTurn]);
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-[#111722]">
      <div className="p-6 border-b border-border-dark bg-[#111722] flex justify-between items-center">
        <div>
          <h1 className="text-white text-2xl font-bold">Diagnóstico AI</h1>
          <p className="text-[#92a4c9] text-sm font-medium">
            {pcbResult ? `Analizando: ${pcbResult.model}` : 'Gemini 3 Pro + Memoria de Taller'}
          </p>
        </div>
        <button 
          onClick={() => { if(confirm("¿Reiniciar chat? No se borrará del historial si has guardado la reparación.")) setHistory([]); }}
          className="px-4 py-2 bg-border-dark hover:bg-surface-dark text-white rounded-lg text-xs font-bold transition-all"
        >
          Nueva Consulta
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
        {history.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-30 text-center">
            <span className="material-symbols-outlined text-8xl mb-4 text-primary">psychology</span>
            <p className="max-w-md font-medium text-lg">Describe los síntomas para iniciar el análisis lógico.</p>
            <p className="text-sm mt-2">Ej: "No enciende, consumo de 0.01A en fuente".</p>
          </div>
        )}

        {history.map((turn, i) => (
          <div key={i} className={`flex ${turn.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl shadow-lg ${turn.role === 'user' ? 'bg-primary text-white' : 'bg-[#1a2332] border border-border-dark text-white'}`}>
              <div className="text-[10px] font-bold uppercase mb-2 tracking-widest opacity-40">{turn.role === 'user' ? 'Técnico' : 'Gusrepart AI'}</div>
              <div className="prose prose-invert prose-sm whitespace-pre-wrap leading-relaxed">
                {turn.content}
              </div>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-[#1a2332] border border-border-dark p-4 rounded-2xl flex items-center gap-4 animate-pulse">
              <div className="flex gap-1.5">
                <div className="w-2 h-2 bg-primary rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-primary rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-2 h-2 bg-primary rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
              <span className="text-xs font-bold text-primary uppercase tracking-widest">IA Razonando...</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 bg-[#161b26] border-t border-border-dark">
        <form onSubmit={handleSubmit} className="flex gap-4 max-w-5xl mx-auto">
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            placeholder="Introduce síntomas o valores medidos..."
            className="flex-1 bg-[#0d1017] border border-border-dark text-white p-4 rounded-xl focus:ring-2 focus:ring-primary outline-none text-sm"
          />
          <button 
            type="submit"
            disabled={isLoading}
            className="px-8 py-4 bg-primary hover:bg-primary-hover rounded-xl text-white font-bold transition-all shadow-lg shadow-primary/20 disabled:opacity-50"
          >
            Analizar
          </button>
        </form>
      </div>
    </div>
  );
};

export default DiagnosticDecisionTree;

