};

export default GuidedMeasurement;

import React, { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { saveRepairToHistory, findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [images, setImages] = useState<string[]>(persistedImages);
  const [result, setResult] = useState<PCBAnalysisResult | any>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  // Sincronizar con el estado global (importante para "Nueva Reparación")
  useEffect(() => {
    setImages(persistedImages);
    setResult(persistedResult);
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      onUpdate(newImages, result); // Notificar cambio
      setActiveSlot(null);
      // Limpiar el input para permitir seleccionar la misma imagen si se desea
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const runAnalysis = async () => {
    if (images.length === 0) return;
    setIsAnalyzing(true);
    setSaveSuccess(false);
    setStatus("Analizando visualmente la PCB...");
    try {
      const pureBase64s = images.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);

      setStatus("Buscando esquemas técnicos en la web...");
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);

      setStatus("Generando modelo funcional con IA...");
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);

      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error("Analysis failed", error);
      setStatus("Error en el análisis.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const handleSaveToDatabase = async () => {
    if (!result) return;
    setIsSaving(true);
    try {
      await saveRepairToHistory({
        pcbResult: result,
        pcbImages: images,
        timestamp: Date.now()
      });
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (e) {
      alert("Error al guardar en la base de datos");
    } finally {
      setIsSaving(false);
    }
  };

  const openFileSelector = (slot: number) => {
    if (isAnalyzing) return;
    setActiveSlot(slot);
    fileInputRef.current?.click();
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden">
      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black leading-tight tracking-tight">Inspección de Hardware AI</h1>
            <p className="text-[#92a4c9] text-base font-normal">Sube fotos nítidas para detectar fallos físicos y obtener esquemas automáticos.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 min-h-[400px]">
            {[0, 1].map((slot) => (
              <div 
                key={slot}
                className={`relative flex flex-col items-center justify-center gap-4 rounded-xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-[#324467]'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden cursor-pointer`}
              >
                {images[slot] ? (
                  <>
                    <img src={images[slot]} alt={`PCB ${slot + 1}`} className="absolute inset-0 w-full h-full object-cover opacity-80" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
                      <button 
                        onClick={(e) => { e.stopPropagation(); openFileSelector(slot); }} 
                        className="p-3 bg-primary/20 hover:bg-primary/40 rounded-full backdrop-blur-md text-primary"
                        title="Cambiar imagen"
                      >
                        <span className="material-symbols-outlined">edit</span>
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); const n = [...images]; n[slot] = ""; setImages(n); onUpdate(n, result); }} 
                        className="p-3 bg-red-500/20 hover:bg-red-500/40 rounded-full backdrop-blur-md text-red-500"
                        title="Borrar imagen"
                      >
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <div onClick={() => openFileSelector(slot)} className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center">
                    <div className="size-14 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform">
                      <span className="material-symbols-outlined text-3xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-[#92a4c9]">{slot === 0 ? 'Frente de Placa' : 'Reverso de Placa'}</p>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col items-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse">{status}</p>}
             <button onClick={runAnalysis} disabled={images.filter(Boolean).length === 0 || isAnalyzing} className={`px-12 py-4 rounded-xl font-bold text-lg flex items-center gap-3 transition-all ${isAnalyzing ? 'bg-primary/50 cursor-wait' : 'bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 hover:translate-y-[-2px] disabled:opacity-30 disabled:cursor-not-allowed'}`}>
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'search_check'}</span>
               <span>{isAnalyzing ? 'Procesando...' : 'Analizar e Identificar'}</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] xl:w-[480px] bg-background-dark flex flex-col shrink-0 border-t lg:border-t-0 overflow-y-auto">
        <div className="p-6 flex flex-col gap-6 h-full">
          <h2 className="text-xl font-bold leading-tight flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">analytics</span>
            Diagnóstico de Visión
          </h2>

          {result ? (
            <div className="space-y-6">
              <div className="space-y-4">
                <div className="bg-border-dark/50 p-4 rounded-xl border border-white/5 relative">
                  <p className="text-[10px] uppercase font-bold text-text-secondary mb-2 tracking-widest">Hardware ID</p>
                  <p className="text-white font-bold">{result.manufacturer} {result.model}</p>
                  <p className="text-primary text-xs font-mono mt-1">{result.boardNumber}</p>

                  <button onClick={handleSaveToDatabase} disabled={isSaving} className={`absolute top-4 right-4 p-2 rounded-lg transition-all ${saveSuccess ? 'bg-green-500 text-white' : 'bg-primary/10 text-primary hover:bg-primary/20'}`} title="Guardar en Base de Datos">
                    <span className="material-symbols-outlined text-sm">{saveSuccess ? 'check' : 'save'}</span>
                  </button>
                </div>

                {similarCases.length > 0 && (
                   <div className="bg-primary/10 p-4 rounded-xl border border-primary/20 animate-in fade-in slide-in-from-right-4">
                      <p className="text-[10px] uppercase font-bold text-primary mb-2 tracking-widest flex items-center gap-2">
                         <span className="material-symbols-outlined text-[14px]">history_edu</span>
                         {similarCases.length} Casos Similares en BD
                      </p>
                      <div className="space-y-2">
                         {similarCases.slice(0, 2).map((c, i) => (
                           <div key={i} className="text-[10px] text-text-secondary border-b border-white/5 pb-2 last:border-0">
                              Fallo previo: {c.pcbResult.detectedAnomalies[0] || "No especificado"}
                           </div>
                         ))}
                      </div>
                   </div>
                )}

                {result.detectedAnomalies && result.detectedAnomalies.length > 0 && (
                  <div className="bg-red-500/10 p-4 rounded-xl border border-red-500/20">
                    <p className="text-[10px] uppercase font-bold text-red-500 mb-2 tracking-widest">Anomalías Detectadas</p>
                    <ul className="space-y-2">
                      {result.detectedAnomalies.map((a: string, i: number) => (
                        <li key={i} className="text-xs text-red-200/80 flex items-start gap-2">
                          <span className="material-symbols-outlined text-[14px] mt-0.5">warning</span>
                          {a}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>

              <div className="space-y-3">
                <p className="text-[10px] uppercase font-bold text-text-secondary tracking-widest">Componentes Identificados</p>
                <div className="flex flex-wrap gap-2">
                  {result.identifiedComponents.map((c: string, i: number) => (
                    <span key={i} className="px-2 py-1 bg-surface-dark border border-white/5 rounded text-[10px] font-mono text-white/70">{c}</span>
                  ))}
                </div>
              </div>

              <div className="flex flex-col gap-3">
                <Link to="/boardview" className="w-full flex items-center justify-center gap-2 rounded-xl bg-primary h-14 text-white font-bold text-sm tracking-wide shadow-xl shadow-primary/25 hover:bg-blue-600 transition-all">
                  <span>Ir a Esquemas y Boardview</span>
                  <span className="material-symbols-outlined text-lg">arrow_forward</span>
                </Link>
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center py-20 text-center opacity-20">
              <span className="material-symbols-outlined text-7xl mb-4">memory</span>
              <p className="max-w-[200px]">Los resultados aparecerán tras el análisis.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PCBIdentification;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { generateMeasurementPlan, getFinalVerdict, textToSpeech } from '../services/gemini';
import { MeasurementPoint } from '../types';

interface GuidedMeasurementProps {
  pcbImages: string[];
  pcbResult: any;
  functionalAI: string;
  persistedPoints: MeasurementPoint[];
  onUpdate: (points: MeasurementPoint[]) => void;
}

const GuidedMeasurement: React.FC<GuidedMeasurementProps> = ({ pcbImages, pcbResult, functionalAI, persistedPoints, onUpdate }) => {
  const [points, setPoints] = useState<MeasurementPoint[]>(persistedPoints || []);
  const [activeIdx, setActiveIdx] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [isVerdictLoading, setIsVerdictLoading] = useState(false);
  const [verdict, setVerdict] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Sincronizar con props
  useEffect(() => {
    setPoints(persistedPoints || []);
  }, [persistedPoints]);

  useEffect(() => {
    const initPlan = async () => {
      if (pcbResult && functionalAI && points.length === 0) {
        setIsLoading(true);
        try {
          const plan = await generateMeasurementPlan(pcbResult, functionalAI);
          const formatted: MeasurementPoint[] = plan.map(p => ({ ...p, status: 'pending' }));
          setPoints(formatted);
          onUpdate(formatted);
        } catch (e) {
          console.error("Failed to generate plan", e);
        } finally {
          setIsLoading(false);
        }
      }
    };
    initPlan();
  }, [pcbResult, functionalAI]);

  const handleValueChange = (val: string) => {
    const newPoints = [...points];
    newPoints[activeIdx].measuredValue = val;

    const expected = parseFloat(newPoints[activeIdx].expectedValue);
    const measured = parseFloat(val);

    if (!isNaN(measured)) {
      if (measured < 0.01 && expected > 0.1) newPoints[activeIdx].status = 'fail';
      else newPoints[activeIdx].status = 'ok';
    } else {
      newPoints[activeIdx].status = 'pending';
    }

    setPoints(newPoints);
    onUpdate(newPoints);
  };

  const handleSpeak = async () => {
    if (!points[activeIdx]) return;
    const current = points[activeIdx];
    const text = `Técnico, por favor localice el componente ${current.component}. Medición requerida en ${current.testPoint} modo ${current.mode === 'V' ? 'Voltaje' : 'Diodo'}. El valor esperado es de ${current.expectedValue}. ${current.description}`;

    setIsPlaying(true);
    await textToSpeech(text, (buffer) => {
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);
      source.start();
    });
  };

  const generateVerdict = async () => {
    setIsVerdictLoading(true);
    try {
      const res = await getFinalVerdict(pcbResult, points);
      setVerdict(res);
    } catch (e) {
      alert("Error al generar veredicto");
    } finally {
      setIsVerdictLoading(false);
    }
  };

  if (!pcbResult) return (
    <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
      <span className="material-symbols-outlined text-8xl mb-4">analytics</span>
      <h2 className="text-2xl font-bold">Primero Analice una Placa</h2>
      <Link to="/pcb-id" className="mt-6 px-6 py-3 bg-primary rounded-xl text-white font-bold">Ir al Analizador</Link>
    </div>
  );

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-[#0f1219]">
      <div className="flex-1 relative overflow-hidden flex flex-col bg-black">
        <div className="w-full h-full relative overflow-hidden flex items-center justify-center">
          {pcbImages.length > 0 ? (
            <div className="relative w-full h-full">
              <img src={pcbImages[0]} alt="PCB View" className="w-full h-full object-contain opacity-70" />
              <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>
              {points[activeIdx] && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="relative">
                    <div className="size-20 border-2 border-primary rounded-full animate-ping opacity-50"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 size-4 bg-primary rounded-full shadow-[0_0_20px_#135bec]"></div>
                    <div className="absolute top-12 left-1/2 -translate-x-1/2 bg-primary px-3 py-1 rounded text-[10px] font-bold whitespace-nowrap uppercase tracking-wider">
                       Test: {points[activeIdx].component}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="text-text-secondary italic">Imagen de referencia no disponible</div>
          )}

          <div className="absolute bottom-6 left-6 flex gap-4">
             <button onClick={handleSpeak} className={`p-4 rounded-full bg-primary text-white shadow-xl flex items-center gap-2 ${isPlaying ? 'animate-pulse' : ''}`}>
               <span className="material-symbols-outlined">{isPlaying ? 'graphic_eq' : 'volume_up'}</span>
               <span className="text-xs font-bold">Voz IA</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[450px] bg-[#111722] border-l border-[#232f48] flex flex-col h-full z-20 shadow-2xl overflow-y-auto">
        <div className="p-6 border-b border-[#232f48] bg-surface-dark/50">
          <span className="text-[10px] uppercase tracking-[0.2em] font-bold text-primary">Diagnóstico Sistemático</span>
          <h2 className="text-xl font-bold text-white mt-1">Guía de Medición</h2>
