const DB_NAME = 'GusrepartDB';
const DB_VERSION = 1;
const STORE_NAME = 'session';

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveSessionData = async (key: string, data: any) => {
  try {
    const db = await initDB();
    return new Promise<void>((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(data, key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    console.error(`Error guardando ${key}:`, e);
  }
};

export const getSessionData = async (key: string): Promise<any> => {
  try {
    const db = await initDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(key);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    return null;
  }
};

export const deleteSessionData = async (key: string) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).delete(key);
};

export const clearSessionStorage = async () => {
  await deleteSessionData('pcbImages');
  await deleteSessionData('pcbResult');
  await deleteSessionData('schematicInfo');
  await deleteSessionData('functionalAI');
  await deleteSessionData('measurements');
  await deleteSessionData('diagHistory');
  await deleteSessionData('currentRepairTimestamp');
};

export const saveRepairToHistory = async (repair: any) => {
  const history = (await getSessionData('history')) || [];

  // Buscar si ya existe para sobreescribir o añadir
  const existingIndex = history.findIndex((h: any) => h.timestamp === repair.timestamp);

  if (existingIndex >= 0) {
    history[existingIndex] = { ...repair, lastModified: Date.now() };
  } else {
    history.push({ 
      ...repair, 
      timestamp: repair.timestamp || Date.now(),
      lastModified: Date.now() 
    });
  }

  await saveSessionData('history', history);
  return repair.timestamp || Date.now();
};

export const deleteRepairFromHistory = async (timestamp: number) => {
  const history = (await getSessionData('history')) || [];
  const newHistory = history.filter((h: any) => h.timestamp !== timestamp);
  await saveSessionData('history', newHistory);
};

export const findSimilarRepairs = async (model: string) => {
  const history = (await getSessionData('history')) || [];
  if (!model) return [];
  return history.filter((h: any) => 
    h.pcbResult?.model?.toLowerCase().includes(model.toLowerCase()) ||
    h.pcbResult?.boardNumber?.toLowerCase().includes(model.toLowerCase())
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import ComponentDetails from './screens/ComponentDetails';
import DatabaseScreen from './screens/DatabaseScreen';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const App: React.FC = () => {
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Estado de la sesión actual
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  // Carga inicial de datos persistidos
  useEffect(() => {
    const loadPersistedData = async () => {
      try {
        const images = await getSessionData('pcbImages');
        const result = await getSessionData('pcbResult');
        const schematics = await getSessionData('schematicInfo');
        const functional = await getSessionData('functionalAI');
        const meas = await getSessionData('measurements');
        const diag = await getSessionData('diagHistory');
        const ts = await getSessionData('currentRepairTimestamp');

        if (images) setPcbImages(images);
        if (result) setPcbResult(result);
        if (schematics) setSchematicInfo(schematics);
        if (functional) setFunctionalAI(functional);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) {
        console.error("Error al hidratar sesión inicial", e);
      } finally {
        setIsLoaded(true);
      }
    };
    loadPersistedData();
  }, []);

  // Sincronización automática con la sesión temporal
  useEffect(() => {
    if (isLoaded) {
      saveSessionData('pcbImages', pcbImages);
      saveSessionData('pcbResult', pcbResult);
      saveSessionData('schematicInfo', schematicInfo);
      saveSessionData('functionalAI', functionalAI);
      saveSessionData('measurements', measurements);
      saveSessionData('diagHistory', diagHistory);
      saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded]);

  // Función de Guardado Global (Memoria de largo plazo)
  const handleGlobalSave = useCallback(async () => {
    const hasImages = pcbImages.some(img => img && img.trim().length > 0);
    const hasData = hasImages || pcbResult || diagHistory.length > 0;

    if (!hasData) {
      alert("No hay información nueva para guardar. Sube al menos una imagen.");
      return;
    }

    setIsSaving(true);

    try {
      let targetTimestamp = currentRepairTimestamp || Date.now();
      let mode: 'update' | 'new' = 'new';

      if (currentRepairTimestamp) {
        const confirmSave = window.confirm(
          "Se ha detectado una sesión abierta.\n\n" +
          "• ACEPTAR: Sobreescribir el archivo actual.\n" +
          "• CANCELAR: Crear una nueva entrada en la base de datos."
        );
        if (confirmSave) {
          mode = 'update';
        } else {
          targetTimestamp = Date.now();
          mode = 'new';
        }
      }

      const repairRecord = {
        timestamp: targetTimestamp,
        pcbImages,
        pcbResult,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };

      const savedTs = await saveRepairToHistory(repairRecord);
      setCurrentRepairTimestamp(savedTs);

      alert(mode === 'update' ? "¡Registro actualizado con éxito!" : "¡Nueva reparación guardada en el historial!");
    } catch (e) {
      console.error("Error crítico en handleGlobalSave:", e);
      alert("Error al intentar acceder a la base de datos local.");
    } finally {
      setIsSaving(false);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp]);

  const clearSession = async () => {
    const hasData = pcbImages.some(img => img && img.length > 0) || pcbResult || diagHistory.length > 0;
    if (!hasData) {
       resetAppState();
       return;
    }

    if (window.confirm("¿Deseas iniciar una nueva reparación? Se limpiará el espacio de trabajo actual.")) {
      resetAppState();
      await clearSessionStorage();
    }
  };

  const resetAppState = () => {
    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    setMeasurements([]);
    setDiagHistory([]);
    setCurrentRepairTimestamp(null);
  };

  const loadRepairFromHistory = (repair: any) => {
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
  };

  // El botón de guardar se habilita si hay imágenes o resultados
  const canSave = pcbImages.some(img => img && img.length > 0) || !!pcbResult || diagHistory.length > 0;

  if (!isLoaded) return null;

  return (
    <HashRouter>
      <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display">
        <Sidebar onNewRepair={clearSession} />
        <div className="flex-1 flex flex-col min-w-0 relative">
          <Header onSave={canSave ? handleGlobalSave : undefined} isSaving={isSaving} />
          <main className="flex-1 overflow-hidden relative">
            <Routes>
              <Route path="/" element={<Dashboard onStart={clearSession} />} />
              <Route path="/pcb-id" 
                element={
                  <PCBIdentification 
                    persistedImages={pcbImages} 
                    persistedResult={pcbResult}
                    onUpdate={(imgs, res, schematics, functional) => {
                      setPcbImages([...imgs]);
                      if (res !== undefined) setPcbResult(res);
                      if (schematics !== undefined) setSchematicInfo(schematics);
                      if (functional !== undefined) setFunctionalAI(functional);
                    }}
                  />
                } 
              />
              <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
              <Route path="/measure" 
                element={
                  <GuidedMeasurement 
                    pcbImages={pcbImages} 
                    pcbResult={pcbResult} 
                    functionalAI={functionalAI}
                    persistedPoints={measurements}
                    onUpdate={setMeasurements}
                  />
                } 
              />
              <Route path="/diagnostics" 
                element={
                  <DiagnosticDecisionTree 
                    persistedHistory={diagHistory}
                    pcbResult={pcbResult}
                    onUpdate={setDiagHistory}
                  />
                } 
              />
              <Route path="/component" element={<ComponentDetails />} />
              <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepairFromHistory} />} />
            </Routes>
          </main>

          <ChatBot />

          <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-50 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 transition-transform">
            <span className="material-symbols-outlined text-white">mic</span>
          </button>

          {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
        </div>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  // Inicializar siempre con 2 slots si viene vacío
  const [images, setImages] = useState<string[]>(() => {
    if (persistedImages && persistedImages.length > 0) return persistedImages;
    return ["", ""];
  });
  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  useEffect(() => {
    if (persistedImages && persistedImages.length > 0) {
      setImages(persistedImages);
    }
    setResult(persistedResult);
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);

      // Notificar al App.tsx inmediatamente para que el botón de Guardar se active/actualice
      onUpdate(newImages, result || undefined);

      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (slot: number) => {
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  const runAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) return;

    setIsAnalyzing(true);
    setStatus("Analizando visualmente la PCB...");
    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);

      setStatus("Buscando esquemas técnicos...");
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);

      setStatus("Generando modelo funcional...");
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);

      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error("Análisis fallido", error);
      setStatus("Error en el análisis de IA.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const openFileSelector = (slot: number) => {
    if (isAnalyzing) return;
    setActiveSlot(slot);
    fileInputRef.current?.click();
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden">
      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6 text-white">
            <h1 className="text-3xl md:text-4xl font-black leading-tight tracking-tight text-white">Inspección de Hardware AI</h1>
            <p className="text-[#92a4c9] text-base font-normal">Sube fotos nítidas para detectar fallos físicos y obtener esquemas automáticos.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 min-h-[400px]">
            {[0, 1].map((slot) => (
              <div 
                key={slot}
                className={`relative flex flex-col items-center justify-center gap-4 rounded-xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-[#324467]'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden cursor-pointer`}
              >
                {images[slot] ? (
                  <>
                    <img src={images[slot]} alt={`PCB ${slot + 1}`} className="absolute inset-0 w-full h-full object-cover opacity-80" />
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 z-10">
                      <button 
                        onClick={(e) => { e.stopPropagation(); openFileSelector(slot); }} 
                        className="p-3 bg-primary/20 hover:bg-primary/40 rounded-full backdrop-blur-md text-primary"
                        title="Cambiar imagen"
                      >
                        <span className="material-symbols-outlined">edit</span>
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); handleRemoveImage(slot); }} 
                        className="p-3 bg-red-500/20 hover:bg-red-500/40 rounded-full backdrop-blur-md text-red-500"
                        title="Borrar imagen"
                      >
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <div onClick={() => openFileSelector(slot)} className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center">
                    <div className="size-14 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform">
                      <span className="material-symbols-outlined text-3xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-[#92a4c9]">{slot === 0 ? 'Frente de Placa' : 'Reverso de Placa'}</p>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col items-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse">{status}</p>}
             <button 
               onClick={runAnalysis} 
               disabled={images.filter(img => img && img.length > 0).length === 0 || isAnalyzing} 
               className={`px-12 py-4 rounded-xl font-bold text-lg flex items-center gap-3 transition-all ${isAnalyzing ? 'bg-primary/50 cursor-wait' : 'bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 hover:translate-y-[-2px] disabled:opacity-30 disabled:cursor-not-allowed text-white'}`}
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'search_check'}</span>
               <span>{isAnalyzing ? 'Procesando...' : 'Analizar e Identificar'}</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] xl:w-[480px] bg-background-dark flex flex-col shrink-0 border-t lg:border-t-0 overflow-y-auto">
        <div className="p-6 flex flex-col gap-6 h-full text-white">
          <h2 className="text-xl font-bold leading-tight flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">analytics</span>
            Diagnóstico de Visión
          </h2>

          {result ? (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="bg-border-dark/50 p-4 rounded-xl border border-white/5">
                <p className="text-[10px] uppercase font-bold text-text-secondary mb-2 tracking-widest">Hardware ID</p>
                <p className="text-white font-bold">{result.manufacturer} {result.model}</p>
                <p className="text-primary text-xs font-mono mt-1">{result.boardNumber}</p>
              </div>

              {similarCases.length > 0 && (
                 <div className="bg-primary/10 p-4 rounded-xl border border-primary/20">
                    <p className="text-[10px] uppercase font-bold text-primary mb-2 tracking-widest flex items-center gap-2">
                       <span className="material-symbols-outlined text-[14px]">history_edu</span>
                       {similarCases.length} Casos Similares
                    </p>
                    <div className="space-y-2">
                       {similarCases.slice(0, 2).map((c, i) => (
                         <div key={i} className="text-[10px] text-text-secondary border-b border-white/5 pb-2 last:border-0">
                            Fallo previo: {c.pcbResult?.detectedAnomalies?.[0] || "No especificado"}
                         </div>
                       ))}
                    </div>
                 </div>
              )}

              {result.detectedAnomalies?.length > 0 && (
                <div className="bg-red-500/10 p-4 rounded-xl border border-red-500/20">
                  <p className="text-[10px] uppercase font-bold text-red-500 mb-2 tracking-widest">Anomalías Detectadas</p>
                  <ul className="space-y-2">
                    {result.detectedAnomalies.map((a: string, i: number) => (
                      <li key={i} className="text-xs text-red-200/80 flex items-start gap-2">
                        <span className="material-symbols-outlined text-[14px] mt-0.5">warning</span>
                        {a}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="space-y-3">
                <p className="text-[10px] uppercase font-bold text-text-secondary tracking-widest">Componentes Identificados</p>
                <div className="flex flex-wrap gap-2">
                  {result.identifiedComponents?.map((c: string, i: number) => (
                    <span key={i} className="px-2 py-1 bg-surface-dark border border-white/5 rounded text-[10px] font-mono text-white/70">{c}</span>
                  ))}
                </div>
              </div>

              <Link to="/boardview" className="w-full flex items-center justify-center gap-2 rounded-xl bg-primary h-14 text-white font-bold text-sm tracking-wide shadow-xl shadow-primary/25 hover:bg-blue-600 transition-all">
                <span>Ir a Esquemas y Boardview</span>
                <span className="material-symbols-outlined text-lg">arrow_forward</span>
              </Link>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center py-20 text-center opacity-20">
              <span className="material-symbols-outlined text-7xl mb-4">memory</span>
              <p className="max-w-[200px]">Los resultados aparecerán tras subir una imagen y pulsar Analizar.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

