import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);
  const [images, setImages] = useState<string[]>(persistedImages?.length > 0 ? persistedImages : ["", ""]);
  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  // Estados para el Zoom Interactivo
  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  useEffect(() => {
    if (persistedImages && persistedImages.length > 0 && JSON.stringify(persistedImages) !== JSON.stringify(images)) {
      setImages(persistedImages);
    }
    setResult(persistedResult);
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot] || isEnhancing !== null) return;

    setIsEnhancing(slot);
    setStatus("Gemini optimizando nitidez...");
    try {
      const enhanced = await enhancePCBImage(images[slot].split(',')[1]);
      const newImages = [...images];
      newImages[slot] = enhanced;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
    } catch (err) {
      alert("Error al mejorar imagen");
    } finally {
      setIsEnhancing(null);
      setStatus("");
    }
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  const runAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) return;

    setIsAnalyzing(true);
    setStatus("Analizando visualmente la PCB...");
    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);

      setStatus("Buscando esquemas técnicos...");
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);

      setStatus("Generando modelo funcional...");
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);

      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error("Análisis fallido", error);
      setStatus("Error en el análisis de IA.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    if (!result) return;
    const newResult = { ...result, [field]: value };
    setResult(newResult);
    onUpdate(images, newResult);
  };

  // Lógica de Zoom y Pan
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    setScale(prev => Math.min(Math.max(1, prev + delta), 5));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (scale <= 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({
      x: e.clientX - dragStart.x,
      y: e.clientY - dragStart.y
    });
  };

  const resetZoom = () => {
    setScale(1);
    setPosition({ x: 0, y: 0 });
    setZoomImage(null);
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {/* Visor de Zoom Avanzado */}
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
        >
          <div className="absolute top-6 left-6 z-10 flex flex-col gap-2">
            <h3 className="text-white font-bold text-lg">Visor de Alta Precisión</h3>
            <p className="text-text-secondary text-xs">Usa la rueda para zoom y arrastra para mover</p>
          </div>

          <div className="absolute top-6 right-6 z-10 flex gap-2">
            <button onClick={() => setScale(s => Math.min(s + 0.5, 5))} className="p-3 bg-white/10 hover:bg-white/20 rounded-full text-white">
              <span className="material-symbols-outlined">zoom_in</span>
            </button>
            <button onClick={() => setScale(s => Math.max(s - 0.5, 1))} className="p-3 bg-white/10 hover:bg-white/20 rounded-full text-white">
              <span className="material-symbols-outlined">zoom_out</span>
            </button>
            <button onClick={resetZoom} className="p-3 bg-red-500/20 hover:bg-red-500/40 rounded-full text-red-500">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>

          <div 
            className="transition-transform duration-75 cursor-move"
            style={{ 
              transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
            }}
          >
            <img 
              src={zoomImage} 
              className="max-w-none h-[80vh] object-contain select-none pointer-events-none" 
              alt="Zoomed PCB" 
            />
          </div>
        </div>
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6 text-white">
            <h1 className="text-3xl md:text-4xl font-black leading-tight tracking-tight">Inspección de Hardware AI</h1>
            <p className="text-[#92a4c9] text-base font-normal">Sube fotos y usa el visor de precisión para detectar fallas.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 flex-1 min-h-[400px]">
            {[0, 1].map((slot) => (
              <div 
                key={slot}
                onClick={() => images[slot] ? setZoomImage(images[slot]) : setActiveSlot(slot) || fileInputRef.current?.click()}
                className={`relative flex flex-col items-center justify-center gap-4 rounded-xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-[#324467]'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden cursor-pointer shadow-lg`}
              >
                {images[slot] ? (
                  <>
                    <img src={images[slot]} alt={`PCB ${slot + 1}`} className="absolute inset-0 w-full h-full object-cover opacity-80" />
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3 z-10">
                      <button 
                        onClick={(e) => { e.stopPropagation(); setZoomImage(images[slot]); }} 
                        className="p-3 bg-white/10 hover:bg-white/20 rounded-full text-white"
                        title="Zoom de Precisión"
                      >
                        <span className="material-symbols-outlined">zoom_in</span>
                      </button>
                      <button 
                        onClick={(e) => handleEnhance(e, slot)} 
                        className={`p-3 rounded-full text-white ${isEnhancing === slot ? 'bg-primary animate-spin' : 'bg-primary/20 hover:bg-primary/40'}`}
                        title="Mejorar con IA"
                        disabled={isEnhancing !== null}
                      >
                        <span className="material-symbols-outlined">{isEnhancing === slot ? 'sync' : 'auto_fix'}</span>
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); setActiveSlot(slot); fileInputRef.current?.click(); }} 
                        className="p-3 bg-white/10 hover:bg-white/20 rounded-full text-white"
                        title="Cambiar"
                      >
                        <span className="material-symbols-outlined">edit</span>
                      </button>
                      <button 
                        onClick={(e) => handleRemoveImage(e, slot)} 
                        className="p-3 bg-red-500/20 hover:bg-red-500/40 rounded-full text-red-500"
                        title="Borrar"
                      >
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center">
                    <div className="size-14 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform">
                      <span className="material-symbols-outlined text-3xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-[#92a4c9]">{slot === 0 ? 'Frente de Placa' : 'Reverso de Placa'}</p>
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col items-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse">{status}</p>}
             <button 
               onClick={runAnalysis} 
               disabled={images.filter(img => img && img.length > 0).length === 0 || isAnalyzing} 
               className={`px-12 py-4 rounded-xl font-bold text-lg flex items-center gap-3 transition-all ${isAnalyzing ? 'bg-primary/50 cursor-wait' : 'bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 hover:translate-y-[-2px] disabled:opacity-30 disabled:cursor-not-allowed text-white'}`}
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'search_check'}</span>
               <span>{isAnalyzing ? 'Procesando...' : 'Analizar e Identificar'}</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] xl:w-[480px] bg-background-dark flex flex-col shrink-0 border-t lg:border-t-0 overflow-y-auto">
        <div className="p-6 flex flex-col gap-6 h-full text-white">
          <h2 className="text-xl font-bold leading-tight flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">analytics</span>
            Diagnóstico de Visión
          </h2>

          {result ? (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="bg-border-dark/50 p-4 rounded-xl border border-white/5 space-y-4">
                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary block mb-1 tracking-widest">Fabricante / Marca</label>
                  <input 
                    type="text" 
                    value={result.manufacturer} 
                    onChange={(e) => updateResultField('manufacturer', e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded px-3 py-1.5 text-sm font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                  />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary block mb-1 tracking-widest">Modelo / Nombre de Reparación</label>
                  <input 
                    type="text" 
                    value={result.model} 
                    onChange={(e) => updateResultField('model', e.target.value)}
                    placeholder="Ej: Mac M1 - Corto en línea principal"
                    className="w-full bg-black/40 border border-white/10 rounded px-3 py-1.5 text-sm font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                  />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary block mb-1 tracking-widest">Número de Placa (Board Number)</label>
                  <input 
                    type="text" 
                    value={result.boardNumber} 
                    onChange={(e) => updateResultField('boardNumber', e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded px-3 py-1.5 text-xs font-mono text-primary outline-none"
                  />
                </div>
              </div>

              {similarCases.length > 0 && (
                 <div className="bg-primary/10 p-4 rounded-xl border border-primary/20">
                    <p className="text-[10px] uppercase font-bold text-primary mb-2 tracking-widest flex items-center gap-2">
                       <span className="material-symbols-outlined text-[14px]">history_edu</span>
                       {similarCases.length} Casos Similares
                    </p>
                    <div className="space-y-2">
                       {similarCases.slice(0, 2).map((c, i) => (
                         <div key={i} className="text-[10px] text-text-secondary border-b border-white/5 pb-2 last:border-0">
                            Fallo previo: {c.pcbResult?.detectedAnomalies?.[0] || "No especificado"}
                         </div>
                       ))}
                    </div>
                 </div>
              )}

              {result.detectedAnomalies?.length > 0 && (
                <div className="bg-red-500/10 p-4 rounded-xl border border-red-500/20">
                  <p className="text-[10px] uppercase font-bold text-red-500 mb-2 tracking-widest">Anomalías Detectadas</p>
                  <ul className="space-y-2">
                    {result.detectedAnomalies.map((a: string, i: number) => (
                      <li key={i} className="text-xs text-red-200/80 flex items-start gap-2">
                        <span className="material-symbols-outlined text-[14px] mt-0.5">warning</span>
                        {a}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="space-y-3">
                <p className="text-[10px] uppercase font-bold text-text-secondary tracking-widest">Componentes Identificados</p>
                <div className="flex flex-wrap gap-2">
                  {result.identifiedComponents?.map((c: string, i: number) => (
                    <span key={i} className="px-2 py-1 bg-surface-dark border border-white/5 rounded text-[10px] font-mono text-white/70">{c}</span>
                  ))}
                </div>
              </div>

              <Link to="/boardview" className="w-full flex items-center justify-center gap-2 rounded-xl bg-primary h-14 text-white font-bold text-sm tracking-wide shadow-xl shadow-primary/25 hover:bg-blue-600 transition-all">
                <span>Continuar a Esquemas</span>
                <span className="material-symbols-outlined text-lg">arrow_forward</span>
              </Link>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center py-20 text-center opacity-20">
              <span className="material-symbols-outlined text-7xl mb-4">memory</span>
              <p className="max-w-[200px]">Los resultados aparecerán tras subir una imagen y pulsar Analizar.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PCBIdentification;

const DB_NAME = 'GusrepartDB';
const DB_VERSION = 1;
const STORE_NAME = 'session';

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveSessionData = async (key: string, data: any) => {
  try {
    const db = await initDB();
    return new Promise<void>((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(data, key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    console.error(`Error guardando ${key}:`, e);
  }
};

export const getSessionData = async (key: string): Promise<any> => {
  try {
    const db = await initDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(key);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    return null;
  }
};

export const deleteSessionData = async (key: string) => {
  try {
    const db = await initDB();
    return new Promise<void>((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(key);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    console.error("Error al borrar dato de sesión", e);
  }
};

export const clearSessionStorage = async () => {
  await deleteSessionData('pcbImages');
  await deleteSessionData('pcbResult');
  await deleteSessionData('schematicInfo');
  await deleteSessionData('functionalAI');
  await deleteSessionData('measurements');
  await deleteSessionData('diagHistory');
  await deleteSessionData('currentRepairTimestamp');
};

export const saveRepairToHistory = async (repair: any) => {
  const history = (await getSessionData('history')) || [];

  // Buscar si ya existe para sobreescribir o añadir
  const existingIndex = history.findIndex((h: any) => h.timestamp === repair.timestamp);

  if (existingIndex >= 0) {
    history[existingIndex] = { ...repair, lastModified: Date.now() };
  } else {
    history.push({ 
      ...repair, 
      timestamp: repair.timestamp || Date.now(),
      lastModified: Date.now() 
    });
  }

  await saveSessionData('history', history);
  return repair.timestamp || Date.now();
};

export const deleteRepairFromHistory = async (timestamp: number) => {
  const history = (await getSessionData('history')) || [];
  const newHistory = history.filter((h: any) => h.timestamp !== timestamp);
  await saveSessionData('history', newHistory);
  return true;
};

export const findSimilarRepairs = async (model: string) => {
  const history = (await getSessionData('history')) || [];
  if (!model) return [];
  return history.filter((h: any) => 
    h.pcbResult?.model?.toLowerCase().includes(model.toLowerCase()) ||
    h.pcbResult?.boardNumber?.toLowerCase().includes(model.toLowerCase())
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getSessionData, deleteRepairFromHistory } from '../services/storage';

interface DatabaseScreenProps {
  onLoadRepair: (repair: any) => void;
}

const DatabaseScreen: React.FC<DatabaseScreenProps> = ({ onLoadRepair }) => {
  const [history, setHistory] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'history' | 'components' | 'schematics'>('history');
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const data = await getSessionData('history');
      if (data) {
        setHistory([...data].sort((a, b) => b.timestamp - a.timestamp));
      } else {
        setHistory([]);
      }
    } catch (e) {
      console.error("Error cargando historial", e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteItem = async (e: React.MouseEvent, timestamp: number, model: string) => {
    e.stopPropagation();
    if (window.confirm(`¿Seguro que quieres eliminar la reparación de "${model || 'Modelo desconocido'}"?`)) {
      setIsLoading(true);
      const success = await deleteRepairFromHistory(timestamp);
      if (success) {
        await loadData(); // Recarga completa para asegurar sincronía
      } else {
        alert("Error al intentar borrar el registro.");
        setIsLoading(false);
      }
    }
  };

  // Extraer todos los componentes únicos de la historia para la pestaña 'Librería'
  const allIdentifiedComponents = history.reduce((acc: string[], curr: any) => {
    const comps = curr.pcbResult?.identifiedComponents || [];
    comps.forEach((c: string) => {
       if (!acc.includes(c)) acc.push(c);
    });
    return acc;
  }, []);

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
      <div className="max-w-6xl mx-auto flex flex-col gap-8">
        <div className="flex justify-between items-end border-b border-border-dark pb-6">
          <div className="flex flex-col gap-2">
            <h1 className="text-4xl font-black text-white">Base de Datos Local</h1>
            <p className="text-text-secondary font-medium">Historial y Librería Técnica Persistente.</p>
          </div>
          <div className="flex bg-border-dark p-1 rounded-xl">
            {(['history', 'components', 'schematics'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === tab ? 'bg-primary text-white shadow-lg shadow-primary/20' : 'text-text-secondary hover:text-white'}`}
              >
                {tab === 'history' ? 'Historial' : tab === 'components' ? 'Librería ICs' : 'Esquemas'}
              </button>
            ))}
          </div>
        </div>

        {activeTab === 'history' && (
          <div className="flex flex-col gap-6">
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {isLoading ? (
                <div className="col-span-full py-20 text-center animate-pulse text-text-secondary font-mono">Accediendo a la base de datos...</div>
              ) : history.length === 0 ? (
                <div className="col-span-full py-24 text-center bg-surface-dark/30 rounded-3xl border-2 border-dashed border-border-dark">
                  <span className="material-symbols-outlined text-7xl text-primary/20 mb-4">database_off</span>
                  <p className="text-text-secondary font-bold">No hay registros de reparaciones.</p>
                </div>
              ) : (
                history.map((item) => (
                  <div key={item.timestamp} className="bg-surface-dark border border-border-dark rounded-2xl overflow-hidden group hover:border-primary/50 transition-all flex flex-col shadow-xl">
                    <div className="h-44 bg-black/40 relative">
                      {item.pcbImages?.[0] ? (
                        <img src={item.pcbImages[0]} className="w-full h-full object-cover opacity-60 group-hover:opacity-80 transition-opacity" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-slate-900/50">
                          <span className="material-symbols-outlined text-6xl text-white/5 font-light">memory</span>
                        </div>
                      )}
                      <button 
                        onClick={(e) => handleDeleteItem(e, item.timestamp, item.pcbResult?.model)}
                        className="absolute top-3 right-3 p-2 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity hover:scale-110 shadow-lg z-20"
                        title="Eliminar permanentemente"
                      >
                        <span className="material-symbols-outlined text-[18px]">delete</span>
                      </button>
                    </div>
                    <div className="p-5 flex-1 flex flex-col">
                      <div className="mb-4">
                        <h3 className="text-lg font-bold text-white truncate">{item.pcbResult?.model || "Nueva Reparación"}</h3>
                        <p className="text-xs text-primary font-mono">{item.pcbResult?.boardNumber || "Sin Serial"}</p>
                      </div>
                      <div className="flex flex-wrap gap-1 mb-4">
