  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const data = await getAllRepairs();
      setHistory(data.sort((a, b) => b.timestamp - a.timestamp));
    } catch (e) {
      console.error("Error cargando historial", e);
