import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import ComponentDetails from './screens/ComponentDetails';
import DatabaseScreen from './screens/DatabaseScreen';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const App: React.FC = () => {
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Estado de la sesión actual
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  // Carga inicial de datos persistidos de sesión
  useEffect(() => {
    const loadPersistedData = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);

        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) {
        console.error("Error al hidratar sesión inicial", e);
      } finally {
        setIsLoaded(true);
      }
    };
    loadPersistedData();
  }, []);

  // Sincronización automática de sesión con debouncing manual (solo cambios relevantes)
  useEffect(() => {
    if (isLoaded) {
      const timeout = setTimeout(() => {
        saveSessionData('pcbImages', pcbImages);
        saveSessionData('pcbResult', pcbResult);
        saveSessionData('schematicInfo', schematicInfo);
        saveSessionData('functionalAI', functionalAI);
        saveSessionData('measurements', measurements);
        saveSessionData('diagHistory', diagHistory);
        saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
      }, 500);
      return () => clearTimeout(timeout);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded]);

  // Guardado permanente en Historial
  const handleGlobalSave = useCallback(async () => {
    const hasImages = pcbImages.some(img => img && img.trim().length > 0);
    const hasData = hasImages || !!pcbResult || diagHistory.length > 0;

    if (!hasData) return;

    // Asegurar que el modelo tenga un nombre
    let modelName = pcbResult?.model || "";
    if (!modelName.trim()) {
      const name = prompt("Introduce un nombre o modelo para identificar este registro en la base de datos:");
      if (!name) return;
      modelName = name;
    }

    setIsSaving(true);
    setSaveSuccess(false);

    try {
      const timestampToUse = currentRepairTimestamp || Date.now();

      const updatedPcbResult = pcbResult ? { ...pcbResult, model: modelName } : { 
        manufacturer: "Genérico", 
        model: modelName, 
        boardNumber: "N/A", 
        confidence: 1, 
        identifiedComponents: [], 
        detectedAnomalies: [] 
      };

      const repairRecord = {
        timestamp: timestampToUse,
        pcbImages,
        pcbResult: updatedPcbResult,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };

      const savedTs = await saveRepairToHistory(repairRecord);
      setCurrentRepairTimestamp(savedTs);
      setPcbResult(updatedPcbResult); 

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (e) {
      console.error("Error crítico en handleGlobalSave:", e);
      alert("La base de datos local rechazó la operación. Por favor, reinicia la app.");
    } finally {
      setIsSaving(false);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp]);

  const clearSession = async () => {
    const hasData = pcbImages.some(img => img && img.length > 0) || !!pcbResult || diagHistory.length > 0;
    if (!hasData) {
       resetAppState();
       return;
    }

    if (window.confirm("¿Deseas vaciar la mesa de trabajo e iniciar una nueva reparación? (El historial no se borrará)")) {
      await clearSessionStorage();
      resetAppState();
    }
  };

  const resetAppState = () => {
    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    setMeasurements([]);
    setDiagHistory([]);
    setCurrentRepairTimestamp(null);
  };

  const loadRepairFromHistory = (repair: any) => {
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
  };

  const canSave = pcbImages.some(img => img && img.length > 0) || !!pcbResult || diagHistory.length > 0;

  if (!isLoaded) return (
    <div className="h-screen w-full bg-background-dark flex items-center justify-center">
      <div className="flex flex-col items-center gap-4">
        <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
        <p className="text-text-secondary font-bold tracking-widest uppercase text-xs">Cargando Taller Gusrepart...</p>
      </div>
    </div>
  );

  return (
    <HashRouter>
      <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display">
        <Sidebar onNewRepair={clearSession} />
        <div className="flex-1 flex flex-col min-w-0 relative">
          <Header onSave={canSave ? handleGlobalSave : undefined} isSaving={isSaving} isSuccess={saveSuccess} />
          <main className="flex-1 overflow-hidden relative">
            <Routes>
              <Route path="/" element={<Dashboard onStart={clearSession} />} />
              <Route path="/pcb-id" 
                element={
                  <PCBIdentification 
                    persistedImages={pcbImages} 
                    persistedResult={pcbResult}
                    onUpdate={(imgs, res, schematics, functional) => {
                      setPcbImages([...imgs]);
                      if (res !== undefined) setPcbResult(res);
                      if (schematics !== undefined) setSchematicInfo(schematics);
                      if (functional !== undefined) setFunctionalAI(functional);
                    }}
                  />
                } 
              />
              <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
              <Route path="/measure" 
                element={
                  <GuidedMeasurement 
                    pcbImages={pcbImages} 
                    pcbResult={pcbResult} 
                    functionalAI={functionalAI}
                    persistedPoints={measurements}
                    onUpdate={setMeasurements}
                  />
                } 
              />
              <Route path="/diagnostics" 
                element={
                  <DiagnosticDecisionTree 
                    persistedHistory={diagHistory}
                    pcbResult={pcbResult}
                    onUpdate={setDiagHistory}
                  />
                } 
              />
              <Route path="/component" element={<ComponentDetails />} />
              <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepairFromHistory} />} />
            </Routes>
          </main>

          <ChatBot />

          <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-50 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 transition-transform">
            <span className="material-symbols-outlined text-white">mic</span>
          </button>

          {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
        </div>
      </div>
    </HashRouter>
  );
};

export default App;

const DB_NAME = 'GusrepartDB_Final_v1';
const DB_VERSION = 1;
const SESSION_STORE = 'session';
const HISTORY_STORE = 'history';

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SESSION_STORE)) {
        db.createObjectStore(SESSION_STORE);
      }
      if (!db.objectStoreNames.contains(HISTORY_STORE)) {
        db.createObjectStore(HISTORY_STORE, { keyPath: 'timestamp' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

// Operaciones de Sesión (Estado volátil de la UI)
export const saveSessionData = async (key: string, data: any) => {
  const db = await initDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(SESSION_STORE, 'readwrite');
    const store = transaction.objectStore(SESSION_STORE);
    store.put(data, key);
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
  });
};

export const getSessionData = async (key: string): Promise<any> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(SESSION_STORE, 'readonly');
    const store = transaction.objectStore(SESSION_STORE);
    const request = store.get(key);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const clearSessionStorage = async () => {
  const db = await initDB();
  const transaction = db.transaction(SESSION_STORE, 'readwrite');
  const store = transaction.objectStore(SESSION_STORE);
  const keys = ['pcbImages', 'pcbResult', 'schematicInfo', 'functionalAI', 'measurements', 'diagHistory', 'currentRepairTimestamp'];
  keys.forEach(k => store.delete(k));
  return new Promise<void>((resolve) => {
    transaction.oncomplete = () => resolve();
  });
};

// Operaciones de Historial (Base de datos permanente)
export const saveRepairToHistory = async (repair: any): Promise<number> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readwrite');
    const store = transaction.objectStore(HISTORY_STORE);

    const timestamp = repair.timestamp || Date.now();
    const record = { ...repair, timestamp, lastModified: Date.now() };

    store.put(record);
    transaction.oncomplete = () => resolve(timestamp);
    transaction.onerror = () => reject(transaction.error);
  });
};

export const getAllRepairs = async (): Promise<any[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readonly');
    const store = transaction.objectStore(HISTORY_STORE);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

export const deleteRepairFromHistory = async (timestamp: number): Promise<boolean> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readwrite');
    const store = transaction.objectStore(HISTORY_STORE);
    store.delete(timestamp);
    transaction.oncomplete = () => resolve(true);
    transaction.onerror = () => resolve(false);
  });
};

export const findSimilarRepairs = async (model: string) => {
  try {
    const repairs = await getAllRepairs();
    if (!model) return [];
    return repairs.filter((h: any) => 
      h.pcbResult?.model?.toLowerCase().includes(model.toLowerCase()) ||
      h.pcbResult?.boardNumber?.toLowerCase().includes(model.toLowerCase())
    );
  } catch (e) {
    return [];
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import ComponentDetails from './screens/ComponentDetails';
import DatabaseScreen from './screens/DatabaseScreen';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const App: React.FC = () => {
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Estado de la sesión actual
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  // Carga inicial de datos
  useEffect(() => {
    const loadPersistedData = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);

        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) {
        console.warn("Sesión previa no encontrada o incompatible.");
      } finally {
        setIsLoaded(true);
      }
    };
    loadPersistedData();
  }, []);

  // Sincronización automática de sesión (Debounced)
  useEffect(() => {
    if (isLoaded) {
      const timeout = setTimeout(() => {
        saveSessionData('pcbImages', pcbImages);
        saveSessionData('pcbResult', pcbResult);
        saveSessionData('schematicInfo', schematicInfo);
        saveSessionData('functionalAI', functionalAI);
        saveSessionData('measurements', measurements);
        saveSessionData('diagHistory', diagHistory);
        saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
      }, 800);
      return () => clearTimeout(timeout);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded]);

  // Función de Guardado Permanente
  const handleGlobalSave = useCallback(async () => {
    const hasData = pcbImages.some(img => img && img.length > 0) || !!pcbResult || diagHistory.length > 0;
    if (!hasData) return;

    let modelName = pcbResult?.model || "";
    if (!modelName.trim()) {
      const name = prompt("Para guardar en el historial, introduce un nombre o modelo para esta reparación:");
      if (!name || !name.trim()) return;
      modelName = name.trim();
    }

    setIsSaving(true);
    setSaveSuccess(false);

    try {
      const timestampToUse = currentRepairTimestamp || Date.now();

      const updatedPcbResult = pcbResult ? { ...pcbResult, model: modelName } : { 
        manufacturer: "Genérico", 
        model: modelName, 
        boardNumber: "S/N", 
        confidence: 1, 
        identifiedComponents: [], 
        detectedAnomalies: [] 
      };

      const repairRecord = {
        timestamp: timestampToUse,
        pcbImages,
        pcbResult: updatedPcbResult,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };

      const savedTs = await saveRepairToHistory(repairRecord);
      setCurrentRepairTimestamp(savedTs);
      setPcbResult(updatedPcbResult); 

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
    } catch (e) {
      console.error("Error al guardar:", e);
      alert("Error de base de datos. Intente limpiar caché si el problema persiste.");
    } finally {
      setIsSaving(false);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp]);

  const clearSession = async () => {
    if (window.confirm("¿Deseas vaciar la mesa de trabajo actual? (El historial guardado no se verá afectado)")) {
      await clearSessionStorage();
      setPcbImages([]);
      setPcbResult(null);
      setSchematicInfo(null);
      setFunctionalAI("");
      setMeasurements([]);
      setDiagHistory([]);
      setCurrentRepairTimestamp(null);
    }
  };

  const loadRepairFromHistory = (repair: any) => {
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
  };

  if (!isLoaded) return null;

  return (
    <HashRouter>
      <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display">
        <Sidebar onNewRepair={clearSession} />
        <div className="flex-1 flex flex-col min-w-0 relative">
          <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
          <main className="flex-1 overflow-hidden relative">
            <Routes>
              <Route path="/" element={<Dashboard onStart={clearSession} />} />
              <Route path="/pcb-id" 
                element={
                  <PCBIdentification 
                    persistedImages={pcbImages} 
                    persistedResult={pcbResult}
                    onUpdate={(imgs, res, schematics, functional) => {
                      setPcbImages([...imgs]);
                      if (res !== undefined) setPcbResult(res);
                      if (schematics !== undefined) setSchematicInfo(schematics);
                      if (functional !== undefined) setFunctionalAI(functional);
                    }}
                  />
                } 
              />
              <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
              <Route path="/measure" 
                element={
                  <GuidedMeasurement 
                    pcbImages={pcbImages} 
                    pcbResult={pcbResult} 
                    functionalAI={functionalAI}
                    persistedPoints={measurements}
                    onUpdate={setMeasurements}
                  />
                } 
              />
              <Route path="/diagnostics" 
                element={
                  <DiagnosticDecisionTree 
                    persistedHistory={diagHistory}
                    pcbResult={pcbResult}
                    onUpdate={setDiagHistory}
                  />
                } 
              />
              <Route path="/component" element={<ComponentDetails />} />
              <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepairFromHistory} />} />
            </Routes>
          </main>

          <ChatBot />

          <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-50 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 transition-transform">
            <span className="material-symbols-outlined text-white">mic</span>
          </button>

          {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
        </div>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);
  const [images, setImages] = useState<string[]>(persistedImages?.length > 0 ? persistedImages : ["", ""]);
  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  useEffect(() => {
    if (persistedImages && persistedImages.length > 0 && JSON.stringify(persistedImages) !== JSON.stringify(images)) {
      setImages(persistedImages);
    }
    setResult(persistedResult);
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    }
  }, [result?.model]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot] || isEnhancing !== null) return;
    setIsEnhancing(slot);
    try {
      const enhanced = await enhancePCBImage(images[slot].split(',')[1]);
      const newImages = [...images];
      newImages[slot] = enhanced;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
    } catch (err) {
      alert("Error al mejorar imagen");
    } finally {
      setIsEnhancing(null);
    }
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  const runAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) return;
    setIsAnalyzing(true);
    setStatus("Analizando visualmente...");
    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);
      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error(error);
      setStatus("Fallo en análisis de IA.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    const newResult = result ? { ...result, [field]: value } : { 
      manufacturer: field === 'manufacturer' ? value : '', 
      model: field === 'model' ? value : '', 
      boardNumber: field === 'boardNumber' ? value : '', 
      confidence: 1, identifiedComponents: [], detectedAnomalies: [] 
    };
    setResult(newResult);
    onUpdate(images, newResult);
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setScale(prev => Math.min(Math.max(1, prev + (e.deltaY > 0 ? -0.2 : 0.2)), 5));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
          style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
        >
          <div className="absolute top-6 right-6 z-10">
            <button onClick={() => setZoomImage(null)} className="p-3 bg-red-500 rounded-full text-white shadow-xl">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <div style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` }}>
            <img src={zoomImage} className="max-w-none h-[85vh] object-contain select-none" draggable={false} />
          </div>
        </div>
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black text-white">Identificación de Hardware</h1>
            <p className="text-text-secondary">Sube fotos de la placa para análisis estructural y búsqueda de esquemas.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 min-h-[400px]">
            {[0, 1].map((slot) => (
              <div key={slot} className={`relative flex items-center justify-center rounded-2xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-border-dark'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden shadow-lg`}>
                {images[slot] ? (
                  <>
                    <img src={images[slot]} className="absolute inset-0 w-full h-full object-cover opacity-60" />
                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                      <button onClick={() => setZoomImage(images[slot])} className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform">
                        <span className="material-symbols-outlined text-3xl">zoom_in</span>
                      </button>
                      <button onClick={(e) => handleEnhance(e, slot)} className={`p-3 bg-surface-dark rounded-xl text-white border border-white/10 ${isEnhancing === slot ? 'animate-spin' : ''}`}>
                        <span className="material-symbols-outlined">auto_fix</span>
                      </button>
                      <button onClick={(e) => handleRemoveImage(e, slot)} className="p-3 bg-red-500/20 text-red-500 rounded-xl border border-red-500/30">
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <button onClick={() => { setActiveSlot(slot); fileInputRef.current?.click(); }} className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center group">
                    <div className="size-16 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform border border-primary/20">
                      <span className="material-symbols-outlined text-4xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-text-secondary">{slot === 0 ? 'Subir Frente' : 'Subir Reverso'}</p>
                  </button>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col items-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse">{status}</p>}
             <button 
               onClick={runAnalysis} 
               disabled={images.filter(img => img && img.length > 0).length === 0 || isAnalyzing} 
               className="px-12 py-4 rounded-xl font-bold text-lg bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 transition-all text-white disabled:opacity-30 flex items-center gap-3"
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'search_check'}</span>
               <span>{isAnalyzing ? 'Analizando...' : 'Analizar Placa'}</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] bg-background-dark flex flex-col border-t lg:border-t-0 overflow-y-auto p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-6">
          <span className="material-symbols-outlined text-primary">analytics</span>
          Ficha de Reparación
        </h2>

        {result || images.some(i => i) ? (
          <div className="space-y-6">
            <div className="bg-surface-dark p-5 rounded-2xl border border-white/5 space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Fabricante</label>
                <input 
                  type="text" 
                  value={result?.manufacturer || ''} 
                  onChange={(e) => updateResultField('manufacturer', e.target.value)}
                  placeholder="Ej: Apple, Dell, Asus"
                  className="w-full bg-black/30 border border-white/5 rounded-xl px-4 py-2.5 text-sm font-bold text-white focus:ring-2 focus:ring-primary outline-none transition-all"
                />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Modelo / Nombre</label>
                <input 
                  type="text" 
                  value={result?.model || ''} 
                  onChange={(e) => updateResultField('model', e.target.value)}
                  placeholder="Nombre de la reparación"
                  className="w-full bg-black/30 border border-white/5 rounded-xl px-4 py-2.5 text-sm font-bold text-white focus:ring-2 focus:ring-primary outline-none transition-all"
                />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Board Number</label>
                <input 
                  type="text" 
                  value={result?.boardNumber || ''} 
                  onChange={(e) => updateResultField('boardNumber', e.target.value)}
                  className="w-full bg-black/30 border border-white/5 rounded-xl px-4 py-2 text-xs font-mono text-primary outline-none"
                />
              </div>
            </div>

            {result && (
              <div className="space-y-4 animate-in fade-in slide-in-from-right-2">
                <div className="space-y-3">
                  <p className="text-[10px] uppercase font-bold text-text-secondary tracking-widest">Componentes</p>
                  <div className="flex flex-wrap gap-2">
                    {result.identifiedComponents?.map((c, i) => (
                      <span key={i} className="px-3 py-1.5 bg-surface-dark border border-white/5 rounded-lg text-[10px] font-mono text-white/60">{c}</span>
                    ))}
                  </div>
                </div>
                <Link to="/boardview" className="w-full flex items-center justify-center gap-3 rounded-2xl bg-primary h-14 text-white font-bold text-sm tracking-wide shadow-xl shadow-primary/20 hover:bg-blue-600 transition-all">
                  <span>Siguiente Paso</span>
                  <span className="material-symbols-outlined">arrow_forward</span>
                </Link>
              </div>
            )}
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-20 text-center">
            <span className="material-symbols-outlined text-8xl mb-4">memory</span>
            <p className="text-sm">Sube una imagen para comenzar.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PCBIdentification;

const DB_NAME = 'GusrepartDB_Final_v2'; // Versión 2 para forzar re-indexación
const DB_VERSION = 1;
const SESSION_STORE = 'session';
const HISTORY_STORE = 'history';

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SESSION_STORE)) {
        db.createObjectStore(SESSION_STORE);
      }
      if (!db.objectStoreNames.contains(HISTORY_STORE)) {
        // Clave primaria explícita como número
        db.createObjectStore(HISTORY_STORE, { keyPath: 'timestamp' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

// Operaciones de Sesión
export const saveSessionData = async (key: string, data: any) => {
  try {
    const db = await initDB();
    return new Promise<void>((resolve, reject) => {
      const transaction = db.transaction(SESSION_STORE, 'readwrite');
      const store = transaction.objectStore(SESSION_STORE);
      store.put(data, key);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  } catch (e) {
    console.error("Error saving session data", e);
  }
};

export const getSessionData = async (key: string): Promise<any> => {
  try {
    const db = await initDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(SESSION_STORE, 'readonly');
      const store = transaction.objectStore(SESSION_STORE);
      const request = store.get(key);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    return null;
  }
};

export const clearSessionStorage = async () => {
  const db = await initDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(SESSION_STORE, 'readwrite');
    const store = transaction.objectStore(SESSION_STORE);
    const keys = ['pcbImages', 'pcbResult', 'schematicInfo', 'functionalAI', 'measurements', 'diagHistory', 'currentRepairTimestamp'];
    keys.forEach(k => store.delete(k));
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject();
  });
};

// Operaciones de Historial
export const saveRepairToHistory = async (repair: any): Promise<number> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readwrite');
    const store = transaction.objectStore(HISTORY_STORE);

    // Asegurar que el timestamp es un número
    const timestamp = Number(repair.timestamp || Date.now());
    const record = { ...repair, timestamp, lastModified: Date.now() };

    store.put(record);
    transaction.oncomplete = () => resolve(timestamp);
    transaction.onerror = () => reject(transaction.error);
  });
};

export const getAllRepairs = async (): Promise<any[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readonly');
    const store = transaction.objectStore(HISTORY_STORE);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

export const deleteRepairFromHistory = async (timestamp: number): Promise<boolean> => {
  const db = await initDB();
  return new Promise((resolve) => {
    const transaction = db.transaction(HISTORY_STORE, 'readwrite');
    const store = transaction.objectStore(HISTORY_STORE);

    // El borrado debe usar el tipo exacto de la clave (número)
    const request = store.delete(Number(timestamp));

    transaction.oncomplete = () => {
      console.log(`Registro ${timestamp} borrado con éxito.`);
      resolve(true);
    };
    transaction.onerror = (e) => {
      console.error("Error al borrar registro:", e);
      resolve(false);
    };
  });
};

export const findSimilarRepairs = async (model: string) => {
  try {
    const repairs = await getAllRepairs();
    if (!model) return [];
    const search = model.toLowerCase();
    return repairs.filter((h: any) => 
      h.pcbResult?.model?.toLowerCase().includes(search) ||
      h.pcbResult?.boardNumber?.toLowerCase().includes(search)
    );
  } catch (e) {
    return [];
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import ComponentDetails from './screens/ComponentDetails';
import DatabaseScreen from './screens/DatabaseScreen';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const App: React.FC = () => {
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Referencia para evitar guardados automáticos durante la limpieza
  const isClearingRef = useRef(false);

  // Estado de la sesión actual
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  // Carga inicial de datos
  useEffect(() => {
    const loadPersistedData = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);

        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) {
        console.warn("Sesión previa no encontrada.");
      } finally {
        setIsLoaded(true);
      }
    };
    loadPersistedData();
  }, []);

  // Sincronización automática de sesión (Debounced)
  useEffect(() => {
    if (isLoaded && !isClearingRef.current) {
      const timeout = setTimeout(() => {
        if (!isClearingRef.current) {
          saveSessionData('pcbImages', pcbImages);
          saveSessionData('pcbResult', pcbResult);
          saveSessionData('schematicInfo', schematicInfo);
          saveSessionData('functionalAI', functionalAI);
          saveSessionData('measurements', measurements);
          saveSessionData('diagHistory', diagHistory);
          saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
        }
      }, 1000);
      return () => clearTimeout(timeout);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded]);

  // Función de Guardado Permanente
  const handleGlobalSave = useCallback(async () => {
    const hasData = pcbImages.some(img => img && img.length > 0) || !!pcbResult || diagHistory.length > 0;
    if (!hasData) return;

    let modelName = pcbResult?.model || "";
    if (!modelName.trim()) {
      const name = prompt("Para guardar en el historial, introduce un nombre o modelo para esta reparación:");
      if (!name || !name.trim()) return;
      modelName = name.trim();
    }

    setIsSaving(true);
    setSaveSuccess(false);

    try {
      const timestampToUse = currentRepairTimestamp || Date.now();

      const updatedPcbResult = pcbResult ? { ...pcbResult, model: modelName } : { 
        manufacturer: "Genérico", 
        model: modelName, 
        boardNumber: "S/N", 
        confidence: 1, 
        identifiedComponents: [], 
        detectedAnomalies: [] 
      };

      const repairRecord = {
        timestamp: timestampToUse,
        pcbImages,
        pcbResult: updatedPcbResult,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };

      const savedTs = await saveRepairToHistory(repairRecord);
      setCurrentRepairTimestamp(savedTs);
      setPcbResult(updatedPcbResult); 

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
    } catch (e) {
      console.error("Error al guardar:", e);
      alert("Error de base de datos.");
    } finally {
      setIsSaving(false);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp]);

  const clearSession = async () => {
    if (window.confirm("¿Deseas vaciar la mesa de trabajo actual? (El historial guardado no se verá afectado)")) {
      isClearingRef.current = true;

      try {
        // 1. Limpiar IndexedDB primero
        await clearSessionStorage();

        // 2. Limpiar estados de React inmediatamente
        setPcbImages([]);
        setPcbResult(null);
        setSchematicInfo(null);
        setFunctionalAI("");
        setMeasurements([]);
        setDiagHistory([]);
        setCurrentRepairTimestamp(null);

        // 3. Pequeño retardo para asegurar que los efectos no re-guarden
        setTimeout(() => {
          isClearingRef.current = false;
        }, 1200);
      } catch (e) {
        console.error("Error clearing session", e);
        isClearingRef.current = false;
      }
    }
  };

  const loadRepairFromHistory = (repair: any) => {
    isClearingRef.current = true; // Pausar sync para evitar bucles
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);

    setTimeout(() => {
      isClearingRef.current = false;
    }, 500);
  };

  if (!isLoaded) return null;

  return (
    <HashRouter>
      <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display">
        <Sidebar onNewRepair={clearSession} />
        <div className="flex-1 flex flex-col min-w-0 relative">
          <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
          <main className="flex-1 overflow-hidden relative">
            <Routes>
              <Route path="/" element={<Dashboard onStart={clearSession} />} />
              <Route path="/pcb-id" 
                element={
                  <PCBIdentification 
                    persistedImages={pcbImages} 
                    persistedResult={pcbResult}
                    onUpdate={(imgs, res, schematics, functional) => {
                      if (!isClearingRef.current) {
                        setPcbImages([...imgs]);
                        if (res !== undefined) setPcbResult(res);
                        if (schematics !== undefined) setSchematicInfo(schematics);
                        if (functional !== undefined) setFunctionalAI(functional);
                      }
                    }}
                  />
                } 
              />
              <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
              <Route path="/measure" 
                element={
                  <GuidedMeasurement 
                    pcbImages={pcbImages} 
                    pcbResult={pcbResult} 
                    functionalAI={functionalAI}
                    persistedPoints={measurements}
                    onUpdate={setMeasurements}
                  />
                } 
              />
              <Route path="/diagnostics" 
                element={
                  <DiagnosticDecisionTree 
                    persistedHistory={diagHistory}
                    pcbResult={pcbResult}
                    onUpdate={setDiagHistory}
                  />
                } 
              />
              <Route path="/component" element={<ComponentDetails />} />
              <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepairFromHistory} />} />
            </Routes>
          </main>

          <ChatBot />

          <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-50 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 transition-transform">
            <span className="material-symbols-outlined text-white">mic</span>
          </button>

          {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
        </div>
      </div>
    </HashRouter>
  );
};

export default App;

