const DB_NAME = 'GusrepartAI_v4_Stable'; 
const DB_VERSION = 1;
const SESSION_STORE = 'session';
const HISTORY_STORE = 'history';

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SESSION_STORE)) {
        db.createObjectStore(SESSION_STORE);
      }
      if (!db.objectStoreNames.contains(HISTORY_STORE)) {
        db.createObjectStore(HISTORY_STORE, { keyPath: 'timestamp' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveSessionData = async (key: string, data: any) => {
  try {
    const db = await initDB();
    const transaction = db.transaction(SESSION_STORE, 'readwrite');
    const store = transaction.objectStore(SESSION_STORE);
    store.put(data, key);
  } catch (e) {
    console.error("Storage Error:", e);
  }
};

export const getSessionData = async (key: string): Promise<any> => {
  try {
    const db = await initDB();
    const transaction = db.transaction(SESSION_STORE, 'readonly');
    const store = transaction.objectStore(SESSION_STORE);
    return new Promise((resolve) => {
      const request = store.get(key);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => resolve(null);
    });
  } catch (e) {
    return null;
  }
};

export const clearSessionStorage = async () => {
  const db = await initDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(SESSION_STORE, 'readwrite');
    const store = transaction.objectStore(SESSION_STORE);
    const request = store.clear(); 
    transaction.oncomplete = () => {
      console.log("Session cleared from DB");
      resolve();
    };
    transaction.onerror = () => reject();
  });
};

export const saveRepairToHistory = async (repair: any): Promise<number> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readwrite');
    const store = transaction.objectStore(HISTORY_STORE);
    const timestamp = Number(repair.timestamp || Date.now());
    const record = { ...repair, timestamp, lastModified: Date.now() };
    store.put(record);
    transaction.oncomplete = () => resolve(timestamp);
    transaction.onerror = () => reject(transaction.error);
  });
};

export const getAllRepairs = async (): Promise<any[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(HISTORY_STORE, 'readonly');
    const store = transaction.objectStore(HISTORY_STORE);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

export const deleteRepairFromHistory = async (timestamp: number): Promise<boolean> => {
  try {
    const db = await initDB();
    return new Promise((resolve) => {
      const transaction = db.transaction(HISTORY_STORE, 'readwrite');
      const store = transaction.objectStore(HISTORY_STORE);
      // Forzar conversión a Number para evitar problemas de tipos en IDB
      const request = store.delete(Number(timestamp));
      transaction.oncomplete = () => {
        console.log("Deleted item:", timestamp);
        resolve(true);
      };
      transaction.onerror = () => resolve(false);
    });
  } catch (e) {
    return false;
  }
};

export const findSimilarRepairs = async (model: string) => {
  try {
    const repairs = await getAllRepairs();
    if (!model) return [];
    const search = model.toLowerCase();
    return repairs.filter((h: any) => 
      h.pcbResult?.model?.toLowerCase().includes(search) ||
      h.pcbResult?.boardNumber?.toLowerCase().includes(search)
    );
  } catch (e) {
    return [];
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import ComponentDetails from './screens/ComponentDetails';
import DatabaseScreen from './screens/DatabaseScreen';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [showSaveModal, setShowSaveModal] = useState(false);

  // SEMÁFORO DE BLOQUEO: Evita que el auto-guardado escriba mientras limpiamos
  const syncLock = useRef(false);

  // Estados
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  const [tempModel, setTempModel] = useState({ manufacturer: '', model: '', boardNumber: '' });

  // Carga inicial desde DB
  useEffect(() => {
    const loadPersistedData = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);

        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) { console.warn("Load failed"); } 
      finally { setIsLoaded(true); }
    };
    loadPersistedData();
  }, []);

  // Lógica de Auto-guardado con comprobación de cierre
  useEffect(() => {
    if (isLoaded && !syncLock.current) {
      const timeout = setTimeout(() => {
        if (!syncLock.current) {
          saveSessionData('pcbImages', pcbImages);
          saveSessionData('pcbResult', pcbResult);
          saveSessionData('schematicInfo', schematicInfo);
          saveSessionData('functionalAI', functionalAI);
          saveSessionData('measurements', measurements);
          saveSessionData('diagHistory', diagHistory);
          saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
        }
      }, 1000);
      return () => clearTimeout(timeout);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded]);

  const executeSave = async (metadata?: { manufacturer: string, model: string, boardNumber: string }) => {
    setIsSaving(true);
    try {
      const timestampToUse = currentRepairTimestamp || Date.now();
      const finalResult: PCBAnalysisResult = metadata ? {
        ...(pcbResult || { confidence: 1, identifiedComponents: [], detectedAnomalies: [] }),
        manufacturer: metadata.manufacturer,
        model: metadata.model,
        boardNumber: metadata.boardNumber
      } : pcbResult!;

      const repairRecord = {
        timestamp: timestampToUse,
        pcbImages,
        pcbResult: finalResult,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };

      const savedTs = await saveRepairToHistory(repairRecord);
      setCurrentRepairTimestamp(savedTs);
      setPcbResult(finalResult);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      setShowSaveModal(false);
    } catch (e) {
      alert("Error en DB.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleGlobalSave = () => {
    if (currentRepairTimestamp && pcbResult?.model) {
      executeSave();
    } else {
      setTempModel({ 
        manufacturer: pcbResult?.manufacturer || '', 
        model: pcbResult?.model || '', 
        boardNumber: pcbResult?.boardNumber || '' 
      });
      setShowSaveModal(true);
    }
  };

  const clearSession = async () => {
    if (window.confirm("¿Seguro que quieres iniciar una nueva reparación? Se borrarán los datos actuales de la pantalla.")) {
      syncLock.current = true; // BLOQUEO TOTAL DE ESCRITURA

      try {
        await clearSessionStorage(); // Limpia la DB

        // Reset manual e inmediato de estados de React
        setPcbImages([]);
        setPcbResult(null);
        setSchematicInfo(null);
        setFunctionalAI("");
        setMeasurements([]);
        setDiagHistory([]);
        setCurrentRepairTimestamp(null);

        navigate('/pcb-id'); 

        // Mantener bloqueo 2 segundos para dar tiempo a React a renderizar los estados vacíos
        // y evitar que el auto-guardado detecte "cambios" y escriba basura
        setTimeout(() => {
          syncLock.current = false;
        }, 2000);
      } catch (e) {
        console.error("Clear error", e);
        syncLock.current = false;
      }
    }
  };

  const loadRepairFromHistory = (repair: any) => {
    syncLock.current = true;
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
    setTimeout(() => { syncLock.current = false; }, 1000);
  };

  if (!isLoaded) return null;

  return (
    <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display relative">
      <Sidebar onNewRepair={clearSession} />
      <div className="flex-1 flex flex-col min-w-0 relative">
        <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
        <main className="flex-1 overflow-hidden relative">
          <Routes>
            <Route path="/" element={<Dashboard onStart={clearSession} />} />
            <Route path="/pcb-id" element={<PCBIdentification persistedImages={pcbImages} persistedResult={pcbResult} onUpdate={(imgs, res, schem, func) => { 
              if (!syncLock.current) {
                setPcbImages([...imgs]); 
                if (res !== undefined) setPcbResult(res); 
                if (schem !== undefined) setSchematicInfo(schem); 
                if (func !== undefined) setFunctionalAI(func);
              }
            }} />} />
            <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
            <Route path="/measure" element={<GuidedMeasurement pcbImages={pcbImages} pcbResult={pcbResult} functionalAI={functionalAI} persistedPoints={measurements} onUpdate={(p) => !syncLock.current && setMeasurements(p)} />} />
            <Route path="/diagnostics" element={<DiagnosticDecisionTree persistedHistory={diagHistory} pcbResult={pcbResult} onUpdate={(h) => !syncLock.current && setDiagHistory(h)} />} />
            <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepairFromHistory} />} />
          </Routes>
        </main>
        <ChatBot />
        <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-40 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 transition-transform">
          <span className="material-symbols-outlined text-white">mic</span>
        </button>
        {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
      </div>

      {showSaveModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
          <div className="bg-surface-dark w-full max-w-md rounded-2xl border border-border-dark p-8 shadow-2xl">
            <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
              <span className="material-symbols-outlined text-primary">save_as</span>
              Guardar Reparación
            </h2>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-text-secondary uppercase mb-1 block">Marca</label>
                <input type="text" value={tempModel.manufacturer} onChange={e => setTempModel({...tempModel, manufacturer: e.target.value})} className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2 text-sm focus:ring-1 focus:ring-primary outline-none" />
              </div>
              <div>
                <label className="text-[10px] font-bold text-text-secondary uppercase mb-1 block">Modelo</label>
                <input type="text" value={tempModel.model} onChange={e => setTempModel({...tempModel, model: e.target.value})} className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2 text-sm focus:ring-1 focus:ring-primary outline-none" />
              </div>
