        {/* Mantenemos las otras pestañas con su lógica actual pero aseguramos UI limpia */}
        {activeTab === 'components' && (
           <div className="bg-surface-dark border border-border-dark rounded-3xl p-8">
              <h2 className="text-xl font-bold mb-6">Componentes en Historial</h2>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
                 {allIdentifiedComponents.map((c, i) => (
