import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAllRepairs, deleteRepairFromHistory } from '../services/storage';

interface DatabaseScreenProps {
  onLoadRepair: (repair: any) => void;
}

const DatabaseScreen: React.FC<DatabaseScreenProps> = ({ onLoadRepair }) => {
  const [history, setHistory] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'history' | 'components' | 'schematics'>('history');
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const data = await getAllRepairs();
      setHistory(data.sort((a, b) => Number(b.timestamp) - Number(a.timestamp)));
    } catch (e) {
      console.error("Load failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteItem = async (e: React.MouseEvent, timestamp: number) => {
    e.preventDefault();
    e.stopPropagation();

    if (window.confirm("¿Estás 100% seguro de eliminar este registro? No se puede recuperar.")) {
      const ts = Number(timestamp);
      setDeletingId(ts);
      try {
        const success = await deleteRepairFromHistory(ts);
        if (success) {
          setHistory(prev => prev.filter(item => Number(item.timestamp) !== ts));
        } else {
          alert("Error en la base de datos al intentar borrar.");
        }
      } catch (err) {
        alert("Fallo crítico de conexión con IndexedDB.");
      } finally {
        setDeletingId(null);
      }
    }
  };

  const allIdentifiedComponents = history.reduce((acc: string[], curr: any) => {
    const comps = curr.pcbResult?.identifiedComponents || [];
    comps.forEach((c: string) => {
       if (!acc.includes(c)) acc.push(c);
    });
    return acc;
  }, []);

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
      <div className="max-w-6xl mx-auto flex flex-col gap-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end border-b border-border-dark pb-6 gap-4">
          <div className="flex flex-col gap-2">
            <h1 className="text-4xl font-black text-white">Base de Datos v6</h1>
            <p className="text-text-secondary font-medium">Gestión local de registros de taller.</p>
          </div>
          <div className="flex bg-border-dark p-1 rounded-xl w-full md:w-auto">
            {(['history', 'components', 'schematics'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
