// NOMBRE ESTABLE - No cambiará en futuras actualizaciones para mantener datos
const DB_NAME = 'Gusrepart_Master_DB'; 
const DB_VERSION = 1;
const SESSION_STORE = 'session';
const HISTORY_STORE = 'history';

// Helper para abrir la DB de forma robusta
const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SESSION_STORE)) {
        db.createObjectStore(SESSION_STORE);
      }
      if (!db.objectStoreNames.contains(HISTORY_STORE)) {
        // keyPath 'timestamp' es crucial para que el borrado funcione por ID
        db.createObjectStore(HISTORY_STORE, { keyPath: 'timestamp' });
      }
    };

    request.onsuccess = () => resolve(request.result);

    request.onerror = (event) => {
      console.error("IndexedDB error:", request.error);
      reject(request.error);
    };
  });
};

export const saveSessionData = async (key: string, data: any) => {
  try {
    const db = await openDB();
    const tx = db.transaction(SESSION_STORE, 'readwrite');
    tx.objectStore(SESSION_STORE).put(data, key);
  } catch (e) {
    console.error("Error guardando sesión:", e);
  }
};

export const getSessionData = async (key: string): Promise<any> => {
  try {
    const db = await openDB();
    return new Promise((resolve) => {
      const tx = db.transaction(SESSION_STORE, 'readonly');
      const store = tx.objectStore(SESSION_STORE);
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    });
  } catch (e) {
    return null;
  }
};

export const clearSessionStorage = async () => {
  try {
    const db = await openDB();
    return new Promise<void>((resolve) => {
      const tx = db.transaction(SESSION_STORE, 'readwrite');
      const store = tx.objectStore(SESSION_STORE);
      const req = store.clear();

      // Resolvemos cuando la petición de borrado tiene éxito, no esperamos a toda la transacción
      req.onsuccess = () => resolve();
      req.onerror = () => {
        console.error("Error limpiando sesión");
        resolve(); // Resolvemos igual para no bloquear la UI
      };
    });
  } catch (e) {
    console.error("Error crítico limpiando DB", e);
    return Promise.resolve();
  }
};

export const saveRepairToHistory = async (repair: any): Promise<number> => {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(HISTORY_STORE, 'readwrite');
    const store = tx.objectStore(HISTORY_STORE);

    // Aseguramos que el timestamp sea un número
    const timestamp = Number(repair.timestamp || Date.now());
    const record = { ...repair, timestamp, lastModified: Date.now() };

    const req = store.put(record);

    req.onsuccess = () => resolve(timestamp);
    req.onerror = () => reject(req.error);
  });
};

export const getAllRepairs = async (): Promise<any[]> => {
  try {
    const db = await openDB();
    return new Promise((resolve) => {
      const tx = db.transaction(HISTORY_STORE, 'readonly');
      const store = tx.objectStore(HISTORY_STORE);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) {
    console.error("Error leyendo historial:", e);
    return [];
  }
};

export const deleteRepairFromHistory = async (timestamp: number): Promise<boolean> => {
  try {
    const db = await openDB();
    return new Promise((resolve) => {
      const tx = db.transaction(HISTORY_STORE, 'readwrite');
      const store = tx.objectStore(HISTORY_STORE);

      // Borramos por la key exacta
      const req = store.delete(Number(timestamp));

      req.onsuccess = () => resolve(true);
      req.onerror = (e) => {
        console.error("Error borrando registro:", e);
        resolve(false);
      };
    });
  } catch (e) {
    console.error("Error conexión DB al borrar:", e);
    return false;
  }
};

export const findSimilarRepairs = async (model: string) => {
  try {
    const repairs = await getAllRepairs();
    if (!model) return [];
    const search = model.toLowerCase();
    return repairs.filter((h: any) => 
      h.pcbResult?.model?.toLowerCase().includes(search) ||
      h.pcbResult?.boardNumber?.toLowerCase().includes(search)
    );
  } catch (e) {
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import DatabaseScreen from './screens/DatabaseScreen';
import ComponentDetails from './screens/ComponentDetails';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isClearing, setIsClearing] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [showSaveModal, setShowSaveModal] = useState(false);

  // Estados de sesión
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  const [tempModel, setTempModel] = useState({ manufacturer: '', model: '', boardNumber: '' });

  // Carga inicial
  useEffect(() => {
    const load = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);
        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) { console.error("Initial load skipped/failed"); }
      finally { setIsLoaded(true); }
    };
    load();
  }, []); 

  // Auto-guardado
  useEffect(() => {
    if (isLoaded && !isClearing) {
      const timer = setTimeout(() => {
        saveSessionData('pcbImages', pcbImages);
        saveSessionData('pcbResult', pcbResult);
        saveSessionData('schematicInfo', schematicInfo);
        saveSessionData('functionalAI', functionalAI);
        saveSessionData('measurements', measurements);
        saveSessionData('diagHistory', diagHistory);
        saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded, isClearing]);

  const startNewRepair = async () => {
    if (window.confirm("¿INICIAR NUEVA REPARACIÓN?\n\nEsto limpiará la mesa de trabajo para empezar desde cero.")) {
      setIsClearing(true); 

      // FAIL-SAFE: Si clearSessionStorage se cuelga, forzamos recarga en 500ms de todos modos
      setTimeout(() => {
        window.location.hash = "#/pcb-id";
        window.location.reload();
      }, 500);

      // Intentamos borrar limpiamente
      await clearSessionStorage();

      // Si llegamos aquí antes del timeout, recargamos inmediatamente
      window.location.hash = "#/pcb-id"; 
      window.location.reload(); 
    }
  };

  const executeSave = async (metadata?: any) => {
    setIsSaving(true);
    try {
      const ts = currentRepairTimestamp || Date.now();
      const finalRes = metadata ? { ...pcbResult, ...metadata } : pcbResult;
      const record = {
        timestamp: ts,
        pcbImages,
        pcbResult: finalRes,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };
      await saveRepairToHistory(record);
      setCurrentRepairTimestamp(ts);
      setPcbResult(finalRes as PCBAnalysisResult);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      setShowSaveModal(false);
    } catch (e) {
      alert("Error guardando en base de datos. Intente de nuevo.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleGlobalSave = () => {
    if (currentRepairTimestamp && pcbResult?.model) {
      executeSave();
    } else {
      setTempModel({ 
        manufacturer: pcbResult?.manufacturer || '', 
        model: pcbResult?.model || '', 
        boardNumber: pcbResult?.boardNumber || '' 
      });
      setShowSaveModal(true);
    }
  };

  const loadRepair = (repair: any) => {
    setIsClearing(true); // Pausar auto-guardado
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);

    // Reactivar auto-guardado
    setTimeout(() => setIsClearing(false), 500);
  };

  if (!isLoaded) return null;

  return (
    <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display relative">
      <Sidebar onNewRepair={startNewRepair} />
      <div className="flex-1 flex flex-col min-w-0 relative">
        <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
        <main className="flex-1 overflow-hidden relative">
          <Routes>
            <Route path="/" element={<Dashboard onStart={startNewRepair} />} />
            <Route path="/pcb-id" element={<PCBIdentification persistedImages={pcbImages} persistedResult={pcbResult} onUpdate={(imgs, res, schem, func) => { 
                if (!isClearing) {
                  setPcbImages([...imgs]);
                  if (res !== undefined) setPcbResult(res);
                  if (schem !== undefined) setSchematicInfo(schem);
                  if (func !== undefined) setFunctionalAI(func);
                }
            }} />} />
            <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
            <Route path="/measure" element={<GuidedMeasurement pcbImages={pcbImages} pcbResult={pcbResult} functionalAI={functionalAI} persistedPoints={measurements} onUpdate={(p) => !isClearing && setMeasurements(p)} />} />
            <Route path="/diagnostics" element={<DiagnosticDecisionTree persistedHistory={diagHistory} pcbResult={pcbResult} onUpdate={(h) => !isClearing && setDiagHistory(h)} />} />
            <Route path="/component" element={<ComponentDetails />} />
            <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepair} />} />
          </Routes>
        </main>
        <ChatBot />
        <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-40 p-4 bg-primary rounded-full shadow-2xl hover:scale-110">
          <span className="material-symbols-outlined text-white">mic</span>
        </button>
        {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
      </div>

      {showSaveModal && (
        <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4">
          <div className="bg-surface-dark w-full max-w-md rounded-2xl p-8 border border-border-dark shadow-2xl animate-in zoom-in-95">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">save</span>
              Guardar en Base de Datos
            </h2>
            <div className="space-y-4">
              <input placeholder="Marca" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.manufacturer} onChange={e => setTempModel({...tempModel, manufacturer: e.target.value})} />
              <input placeholder="Modelo / Nombre" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.model} onChange={e => setTempModel({...tempModel, model: e.target.value})} />
              <input placeholder="Board Number" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2 font-mono" value={tempModel.boardNumber} onChange={e => setTempModel({...tempModel, boardNumber: e.target.value})} />
            </div>
            <div className="flex gap-4 mt-8">
              <button onClick={() => setShowSaveModal(false)} className="flex-1 py-3 border border-border-dark rounded-xl hover:bg-white/5 font-bold">Cerrar</button>
              <button onClick={() => executeSave(tempModel)} className="flex-1 py-3 bg-primary rounded-xl font-bold shadow-lg shadow-primary/20">Guardar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => (
  <HashRouter>
    <AppContent />
  </HashRouter>
);

export default App;

