// Helper con Timeout para evitar bloqueos eternos
const performOperation = (
  storeName: string, 
  mode: IDBTransactionMode, 
  callback: (store: IDBObjectStore) => IDBRequest | void
): Promise<any> => {
  return new Promise((resolve, reject) => {
    // 1. Timeout de seguridad: Si IDB tarda más de 2s, rechazamos para no colgar la UI
    const timeoutId = setTimeout(() => {
        reject(new Error("Database operation timed out - Database might be locked"));
    }, 2000);

    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
        clearTimeout(timeoutId);
        reject(request.error);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SESSION_STORE)) {
        db.createObjectStore(SESSION_STORE);
      }
      if (!db.objectStoreNames.contains(HISTORY_STORE)) {
        db.createObjectStore(HISTORY_STORE, { keyPath: 'timestamp' });
      }
    };

    request.onsuccess = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;

      db.onerror = (e) => {
        console.error("Database generic error:", e);
      };

      try {
        const transaction = db.transaction(storeName, mode);
        const store = transaction.objectStore(storeName);

        let req: IDBRequest | void;
        try {
            req = callback(store);
        } catch(err) {
            db.close();
            clearTimeout(timeoutId);
            reject(err);
            return;
        }

        transaction.oncomplete = () => {
          db.close(); 
          clearTimeout(timeoutId); // Operación exitosa, limpiamos timeout
          if (req && 'result' in req) {
              resolve(req.result);
          } else {
              resolve(undefined);
          }
        };

        transaction.onerror = () => {
          db.close();
          clearTimeout(timeoutId);
          reject(transaction.error);
        };
      } catch (e) {
        db.close();
        clearTimeout(timeoutId);
        reject(e);
      }
    };
  });
};

