import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAllRepairs, deleteRepairFromHistory } from '../services/storage';
import ConfirmDialog from '../components/ConfirmDialog';

interface DatabaseScreenProps {
  onLoadRepair: (repair: any) => void;
}

const DatabaseScreen: React.FC<DatabaseScreenProps> = ({ onLoadRepair }) => {
  const [history, setHistory] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'history' | 'components' | 'schematics'>('history');
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<number | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const data = await getAllRepairs();
      setHistory(data.sort((a, b) => Number(b.timestamp) - Number(a.timestamp)));
    } catch (e) {
      console.error("Load failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRequestDelete = (e: React.MouseEvent, timestamp: number) => {
    e.stopPropagation();
    setConfirmDeleteId(timestamp);
  };

  const handleConfirmDelete = async () => {
    if (confirmDeleteId === null) return;
    const ts = Number(confirmDeleteId);
    setConfirmDeleteId(null);
    setDeletingId(ts);

    try {
      const success = await deleteRepairFromHistory(ts);
      if (success) {
        setHistory(prev => prev.filter(item => Number(item.timestamp) !== ts));
      } else {
        alert("Error al eliminar.");
      }
    } catch (err) {
      console.error(err);
    } finally {
      setDeletingId(null);
    }
  };

  const allIdentifiedComponents = history.reduce((acc: string[], curr: any) => {
    const comps = curr.pcbResult?.identifiedComponents || [];
    comps.forEach((c: string) => {
       if (!acc.includes(c)) acc.push(c);
    });
    return acc;
  }, []);

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
      <div className="max-w-6xl mx-auto flex flex-col gap-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end border-b border-border-dark pb-6 gap-4">
          <div className="flex flex-col gap-2">
            <h1 className="text-4xl font-black text-white">Base de Datos</h1>
            <p className="text-text-secondary font-medium">Registro Maestro (v1.0-STABLE)</p>
          </div>
          <div className="flex bg-border-dark p-1 rounded-xl w-full md:w-auto">
            {(['history', 'components', 'schematics'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`flex-1 md:flex-none px-6 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'text-text-secondary hover:text-white'}`}
              >
                {tab === 'history' ? 'Historial' : tab === 'components' ? 'Componentes' : 'Esquemas'}
              </button>
            ))}
          </div>
        </div>

        {activeTab === 'history' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {isLoading ? (
              <div className="col-span-full py-40 text-center">
                <span className="material-symbols-outlined text-4xl text-primary animate-spin mb-4">progress_activity</span>
                <p className="text-text-secondary font-mono">Accediendo a la base de datos...</p>
              </div>
            ) : history.length === 0 ? (
              <div className="col-span-full py-24 text-center border-2 border-dashed border-border-dark rounded-3xl opacity-20">
                <span className="material-symbols-outlined text-8xl mb-4">folder_off</span>
                <p className="text-lg font-bold">Base de datos vacía</p>
              </div>
            ) : (
              history.map((item) => (
                <div 
                  key={item.timestamp} 
                  className={`bg-surface-dark border border-border-dark rounded-2xl overflow-hidden group hover:border-primary/40 transition-all flex flex-col shadow-xl ${deletingId === Number(item.timestamp) ? 'opacity-30 pointer-events-none scale-95' : ''}`}
                >
                  <div className="h-40 bg-black/50 relative cursor-pointer" onClick={() => { onLoadRepair(item); navigate('/pcb-id'); }}>
                    {item.pcbImages?.[0] ? (
                      <img src={item.pcbImages[0]} className="w-full h-full object-cover opacity-60 group-hover:opacity-80 transition-opacity" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center opacity-10">
                        <span className="material-symbols-outlined text-6xl">memory</span>
                      </div>
                    )}
                    <button 
                      onClick={(e) => handleRequestDelete(e, item.timestamp)}
                      disabled={deletingId !== null}
                      className="absolute top-3 right-3 p-2 bg-red-500/20 hover:bg-red-600 text-white rounded-xl transition-all border border-red-500/30 z-20 hover:scale-110 active:scale-90"
                      title="Eliminar Registro"
                    >
                      <span className="material-symbols-outlined text-[18px]">delete_forever</span>
                    </button>
                    <div className="absolute bottom-3 left-3 bg-primary/80 px-2 py-1 rounded text-[9px] font-bold text-white shadow-lg">
                      {new Date(item.timestamp).toLocaleDateString()}
                    </div>
                  </div>
                  <div className="p-5 flex-1 flex flex-col">
                    <h3 className="text-base font-bold text-white truncate">{item.pcbResult?.model || "Sin Nombre"}</h3>
                    <p className="text-[10px] text-text-secondary font-mono mt-1 mb-4 uppercase tracking-tighter">{item.pcbResult?.boardNumber || "Serial N/A"}</p>
                    <button 
                      onClick={() => { onLoadRepair(item); navigate('/pcb-id'); }}
                      className="mt-auto w-full py-3 bg-[#111722] hover:bg-primary border border-white/5 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm active:scale-95"
                    >
                      Recuperar Sesión
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'components' && (
           <div className="bg-surface-dark border border-border-dark rounded-3xl p-8 shadow-2xl">
              <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                 <span className="material-symbols-outlined text-primary">microchip</span>
                 Inventario Detectado
              </h2>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
                 {allIdentifiedComponents.map((c, i) => (
                   <div key={i} className="p-4 bg-background-dark border border-white/5 rounded-2xl text-center shadow-lg">
                      <p className="text-[10px] font-mono text-primary font-black uppercase">{c}</p>
                   </div>
                 ))}
                 {allIdentifiedComponents.length === 0 && <p className="col-span-full py-10 text-center opacity-30 text-sm italic">Sin datos registrados.</p>}
              </div>
           </div>
        )}
      </div>

      <ConfirmDialog 
        isOpen={confirmDeleteId !== null}
        title="Eliminar Registro"
        message="¿Estás seguro de que quieres eliminar esta reparación del historial permanentemente? Esta acción no se puede deshacer."
        confirmText="Sí, Eliminar"
        cancelText="No, Mantener"
        isDestructive={true}
        onConfirm={handleConfirmDelete}
        onCancel={() => setConfirmDeleteId(null)}
      />
    </div>
  );
};

export default DatabaseScreen;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import ConfirmDialog from './components/ConfirmDialog';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import DatabaseScreen from './screens/DatabaseScreen';
import ComponentDetails from './screens/ComponentDetails';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const [isLiveOpen, setIsLiveOpen] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isClearing, setIsClearing] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Modals
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [showNewRepairModal, setShowNewRepairModal] = useState(false);

  // Estados de sesión
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  const [tempModel, setTempModel] = useState({ manufacturer: '', model: '', boardNumber: '' });

  // Carga inicial
  useEffect(() => {
    const initSystem = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);
        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) { console.error("Load failed", e); }
      finally { setIsLoaded(true); }
    };
    initSystem();
  }, []); 

  // Auto-guardado
  useEffect(() => {
    if (isLoaded && !isClearing) {
      const timer = setTimeout(() => {
        if (pcbImages.length > 0 || pcbResult || diagHistory.length > 0) {
            saveSessionData('pcbImages', pcbImages);
            saveSessionData('pcbResult', pcbResult);
            saveSessionData('schematicInfo', schematicInfo);
            saveSessionData('functionalAI', functionalAI);
            saveSessionData('measurements', measurements);
            saveSessionData('diagHistory', diagHistory);
            saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
        }
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded, isClearing]);

  const handleNewRepairConfirm = async () => {
    // 1. Detener auto-guardado
    setIsClearing(true); 

    // 2. Limpiar persistencia
    try {
        await clearSessionStorage();
    } catch(e) { console.error(e); }

    // 3. Resetear todos los estados visuales (Soft Reset)
    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    setMeasurements([]);
    setDiagHistory([]);
    setCurrentRepairTimestamp(null);
    setTempModel({ manufacturer: '', model: '', boardNumber: '' });

    // 4. Navegar y cerrar modal
    setShowNewRepairModal(false);
    navigate('/pcb-id');

    // 5. Reactivar auto-guardado tras breve pausa
    setTimeout(() => {
        setIsClearing(false);
    }, 500);
  };

  const executeSave = async (metadata?: any) => {
    setIsSaving(true);
    try {
      const ts = currentRepairTimestamp || Date.now();
      const finalRes = metadata ? { ...pcbResult, ...metadata } : pcbResult;
      const record = {
        timestamp: ts,
        pcbImages,
        pcbResult: finalRes,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };
      await saveRepairToHistory(record);
      setCurrentRepairTimestamp(ts);
      setPcbResult(finalRes as PCBAnalysisResult);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      setShowSaveModal(false);
    } catch (e) {
      alert("Error guardando.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleGlobalSave = () => {
    if (currentRepairTimestamp && pcbResult?.model) {
      executeSave();
    } else {
      setTempModel({ 
        manufacturer: pcbResult?.manufacturer || '', 
        model: pcbResult?.model || '', 
        boardNumber: pcbResult?.boardNumber || '' 
      });
      setShowSaveModal(true);
    }
  };

  const loadRepair = (repair: any) => {
    setIsClearing(true);
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
    setTimeout(() => setIsClearing(false), 500);
  };

  if (!isLoaded) return null;

  return (
    <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display relative">
      <Sidebar onNewRepair={() => setShowNewRepairModal(true)} />
      <div className="flex-1 flex flex-col min-w-0 relative">
        <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
        <main className="flex-1 overflow-hidden relative">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/pcb-id" element={<PCBIdentification persistedImages={pcbImages} persistedResult={pcbResult} onUpdate={(imgs, res, schem, func) => { 
                if (!isClearing) {
                  setPcbImages([...imgs]);
                  if (res !== undefined) setPcbResult(res);
                  if (schem !== undefined) setSchematicInfo(schem);
                  if (func !== undefined) setFunctionalAI(func);
                }
            }} />} />
            <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
            <Route path="/measure" element={<GuidedMeasurement pcbImages={pcbImages} pcbResult={pcbResult} functionalAI={functionalAI} persistedPoints={measurements} onUpdate={(p) => !isClearing && setMeasurements(p)} />} />
            <Route path="/diagnostics" element={<DiagnosticDecisionTree persistedHistory={diagHistory} pcbResult={pcbResult} onUpdate={(h) => !isClearing && setDiagHistory(h)} />} />
            <Route path="/component" element={<ComponentDetails />} />
            <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepair} />} />
          </Routes>
        </main>
        <ChatBot />
        <button onClick={() => setIsLiveOpen(true)} className="fixed bottom-6 right-20 z-40 p-4 bg-primary rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-transform">
          <span className="material-symbols-outlined text-white">mic</span>
        </button>
        {isLiveOpen && <LiveAssistant onClose={() => setIsLiveOpen(false)} />}
      </div>

      <ConfirmDialog 
        isOpen={showNewRepairModal}
        title="Iniciar Nueva Reparación"
        message="Se limpiará la mesa de trabajo actual para comenzar un nuevo diagnóstico. Asegúrate de haber guardado cambios importantes."
        confirmText="Sí, Limpiar Todo"
        onConfirm={handleNewRepairConfirm}
        onCancel={() => setShowNewRepairModal(false)}
      />

      {showSaveModal && (
        <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4">
          <div className="bg-surface-dark w-full max-w-md rounded-2xl p-8 border border-border-dark shadow-2xl animate-in zoom-in-95">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">save</span>
              Guardar en Base de Datos
            </h2>
            <div className="space-y-4">
              <input placeholder="Marca" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.manufacturer} onChange={e => setTempModel({...tempModel, manufacturer: e.target.value})} />
              <input placeholder="Modelo / Nombre" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.model} onChange={e => setTempModel({...tempModel, model: e.target.value})} />
              <input placeholder="Board Number" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2 font-mono" value={tempModel.boardNumber} onChange={e => setTempModel({...tempModel, boardNumber: e.target.value})} />
            </div>
            <div className="flex gap-4 mt-8">
              <button onClick={() => setShowSaveModal(false)} className="flex-1 py-3 border border-border-dark rounded-xl hover:bg-white/5 font-bold transition-colors">Cerrar</button>
              <button onClick={() => executeSave(tempModel)} className="flex-1 py-3 bg-primary rounded-xl font-bold shadow-lg shadow-primary/20 hover:bg-primary-hover active:scale-95 transition-all">Guardar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => (
  <HashRouter>
    <AppContent />
  </HashRouter>
);

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);

  // ESTADO INICIAL: Si hay imágenes persistidas las usa, si no, inicializa con dos slots vacíos
  const [images, setImages] = useState<string[]>(
    (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""]
  );

  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  // CORRECCIÓN CRÍTICA: Sincronización robusta con el estado padre (App.tsx)
  useEffect(() => {
    // 1. Determinar qué imágenes deberíamos tener según el padre
    const targetImages = (persistedImages && persistedImages.length > 0) 
      ? persistedImages 
      : ["", ""]; // Si viene vacío (reset), forzamos slots vacíos

    // 2. Solo actualizamos si hay diferencia real (evita bucles infinitos)
    if (JSON.stringify(targetImages) !== JSON.stringify(images)) {
      setImages(targetImages);
    }

    // 3. Sincronizar resultado de análisis
    // Si persistedResult es null (reset), result debe ser null.
    if (JSON.stringify(persistedResult) !== JSON.stringify(result)) {
      setResult(persistedResult);
    }
  }, [persistedImages, persistedResult]); // Dependencias: se ejecuta cuando el padre cambia estas props

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]); // Limpiar casos similares si no hay modelo
    }
  }, [result?.model]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      // Notificamos al padre INMEDIATAMENTE para que guarde el estado
      onUpdate(newImages, result || undefined);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot] || isEnhancing !== null) return;
    setIsEnhancing(slot);
    try {
      const enhanced = await enhancePCBImage(images[slot].split(',')[1]);
      const newImages = [...images];
      newImages[slot] = enhanced;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
    } catch (err) {
      alert("Error al mejorar imagen");
    } finally {
      setIsEnhancing(null);
    }
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  const runAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) return;
    setIsAnalyzing(true);
    setStatus("Analizando visualmente...");
    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);
      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error(error);
      setStatus("Fallo en análisis de IA.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    const newResult = result ? { ...result, [field]: value } : { 
      manufacturer: field === 'manufacturer' ? value : '', 
      model: field === 'model' ? value : '', 
      boardNumber: field === 'boardNumber' ? value : '', 
      confidence: 1, identifiedComponents: [], detectedAnomalies: [] 
    };
    setResult(newResult);
    onUpdate(images, newResult);
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setScale(prev => Math.min(Math.max(1, prev + (e.deltaY > 0 ? -0.2 : 0.2)), 5));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
          style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
        >
          <div className="absolute top-6 right-6 z-10">
            <button onClick={() => setZoomImage(null)} className="p-3 bg-red-500 rounded-full text-white shadow-xl">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <div style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` }}>
            <img src={zoomImage} className="max-w-none h-[85vh] object-contain select-none" draggable={false} />
          </div>
        </div>
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black text-white">Identificación de Hardware</h1>
            <p className="text-text-secondary">Sube fotos de la placa para análisis estructural y búsqueda de esquemas.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 min-h-[400px]">
            {[0, 1].map((slot) => (
              <div key={slot} className={`relative flex items-center justify-center rounded-2xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-border-dark'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden shadow-lg`}>
                {images[slot] ? (
                  <>
                    <img src={images[slot]} className="absolute inset-0 w-full h-full object-cover opacity-60" />
                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                      <button onClick={() => setZoomImage(images[slot])} className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform">
                        <span className="material-symbols-outlined text-3xl">zoom_in</span>
                      </button>
                      <button onClick={(e) => handleEnhance(e, slot)} className={`p-3 bg-surface-dark rounded-xl text-white border border-white/10 ${isEnhancing === slot ? 'animate-spin' : ''}`}>
                        <span className="material-symbols-outlined">auto_fix</span>
                      </button>
                      <button onClick={(e) => handleRemoveImage(e, slot)} className="p-3 bg-red-500/20 text-red-500 rounded-xl border border-red-500/30">
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <button onClick={() => { setActiveSlot(slot); fileInputRef.current?.click(); }} className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center group">
                    <div className="size-16 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform border border-primary/20">
                      <span className="material-symbols-outlined text-4xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-text-secondary">{slot === 0 ? 'Subir Frente' : 'Subir Reverso'}</p>
                  </button>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col items-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse">{status}</p>}
             <button 
               onClick={runAnalysis} 
               disabled={images.filter(img => img && img.length > 0).length === 0 || isAnalyzing} 
               className="px-12 py-4 rounded-xl font-bold text-lg bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 transition-all text-white disabled:opacity-30 flex items-center gap-3"
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'search_check'}</span>
               <span>{isAnalyzing ? 'Analizando...' : 'Analizar Placa'}</span>
             </button>
          </div>
        </div>
      </div>

