export default PCBIdentification;

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);

  // Estado de edición manual de la ficha
  const [isEditing, setIsEditing] = useState(false);

  // ESTADO INICIAL
  const [images, setImages] = useState<string[]>(
    (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""]
  );

  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  // Sincronización robusta con el estado padre (App.tsx)
  useEffect(() => {
    const targetImages = (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""];
    if (JSON.stringify(targetImages) !== JSON.stringify(images)) {
      setImages(targetImages);
    }
    if (JSON.stringify(persistedResult) !== JSON.stringify(result)) {
      setResult(persistedResult);
    }
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result?.model]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot] || isEnhancing !== null) return;
    setIsEnhancing(slot);
    try {
      const enhanced = await enhancePCBImage(images[slot].split(',')[1]);
      const newImages = [...images];
      newImages[slot] = enhanced;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
    } catch (err) {
      alert("Error al mejorar imagen");
    } finally {
      setIsEnhancing(null);
    }
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  const runAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) return;
    setIsAnalyzing(true);
    setStatus("Analizando visualmente...");
    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);
      const schematics = await searchSchematics(`${analysis.manufacturer} ${analysis.model} ${analysis.boardNumber}`);
      const functional = await getFunctionalAnalysis(analysis.identifiedComponents, analysis.boardNumber);
      onUpdate(images, analysis, schematics, functional);
    } catch (error) {
      console.error(error);
      setStatus("Fallo en análisis de IA.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    const newResult = result ? { ...result, [field]: value } : { 
      manufacturer: field === 'manufacturer' ? value : '', 
      model: field === 'model' ? value : '', 
      boardNumber: field === 'boardNumber' ? value : '', 
      confidence: 1, identifiedComponents: [], detectedAnomalies: [] 
    };
    setResult(newResult);
    onUpdate(images, newResult);
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setScale(prev => Math.min(Math.max(1, prev + (e.deltaY > 0 ? -0.2 : 0.2)), 5));
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
