                    <span className="material-symbols-outlined text-sm">{isEditing ? 'check' : 'edit'}</span>
                </button>
            )}
        </div>

        {result || images.some(i => i) ? (
          <div className="space-y-6">
            <div className="bg-surface-dark p-6 rounded-2xl border border-white/5 space-y-5 relative overflow-hidden">
                {/* Visual Reference Card Look */}
                {!isEditing && (
                    <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                         <span className="material-symbols-outlined text-6xl">qr_code_2</span>
