export default PCBIdentification;

const DB_NAME = 'Gusrepart_Master_DB'; 
const DB_VERSION = 1;
const SESSION_STORE = 'session';
const HISTORY_STORE = 'history';
const LS_PREFIX = 'GUSREPART_SESSION_';

// IndexedDB Helper (Solo para imágenes e historial)
const performOperation = (
  storeName: string, 
  mode: IDBTransactionMode, 
  callback: (store: IDBObjectStore) => IDBRequest | void
): Promise<any> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SESSION_STORE)) db.createObjectStore(SESSION_STORE);
      if (!db.objectStoreNames.contains(HISTORY_STORE)) db.createObjectStore(HISTORY_STORE, { keyPath: 'timestamp' });
    };

    request.onsuccess = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      try {
        const transaction = db.transaction(storeName, mode);
        const store = transaction.objectStore(storeName);

        let req: IDBRequest | void;
        try { req = callback(store); } catch(err) { db.close(); reject(err); return; }

        transaction.oncomplete = () => {
          db.close(); 
          if (req && 'result' in req) resolve(req.result);
          else resolve(undefined);
        };
        transaction.onerror = () => { db.close(); reject(transaction.error); };
      } catch (e) { db.close(); reject(e); }
    };
  });
};

// Guardado Híbrido: Imágenes -> DB, Texto -> LocalStorage
export const saveSessionData = async (key: string, data: any) => {
  if (key === 'pcbImages') {
    return performOperation(SESSION_STORE, 'readwrite', (store) => store.put(data, key));
  } else {
    try {
      localStorage.setItem(LS_PREFIX + key, JSON.stringify(data));
      return Promise.resolve();
    } catch (e) {
      console.warn("LocalStorage full or error", e);
      return Promise.resolve();
    }
  }
};

export const getSessionData = async (key: string): Promise<any> => {
  if (key === 'pcbImages') {
    try {
      return await performOperation(SESSION_STORE, 'readonly', (store) => store.get(key));
    } catch { return null; }
  } else {
    const item = localStorage.getItem(LS_PREFIX + key);
    return item ? JSON.parse(item) : null;
  }
};

export const clearSessionStorage = async () => {
  // Limpiar LocalStorage
  Object.keys(localStorage).forEach(k => {
    if (k.startsWith(LS_PREFIX)) localStorage.removeItem(k);
  });

  // Limpiar Imágenes de DB
  try {
    await performOperation(SESSION_STORE, 'readwrite', (store) => store.clear());
  } catch (e) { console.error("Error clearing DB images", e); }
};

// Historial siempre va completo a DB
export const saveRepairToHistory = async (repair: any): Promise<number> => {
  const timestamp = Number(repair.timestamp || Date.now());
  const record = { ...repair, timestamp, lastModified: Date.now() };
  await performOperation(HISTORY_STORE, 'readwrite', (store) => store.put(record));
  return timestamp;
};

export const getAllRepairs = async (): Promise<any[]> => {
  try {
    const result = await performOperation(HISTORY_STORE, 'readonly', (store) => store.getAll());
    return result || [];
  } catch (e) { return []; }
};

export const deleteRepairFromHistory = async (timestamp: number): Promise<boolean> => {
  try {
    await performOperation(HISTORY_STORE, 'readwrite', (store) => store.delete(Number(timestamp)));
    return true;
  } catch (e) { return false; }
};

export const findSimilarRepairs = async (model: string) => {
  try {
    const repairs = await getAllRepairs();
    if (!model) return [];
    const search = model.toLowerCase();
    return repairs.filter((h: any) => 
      h.pcbResult?.model?.toLowerCase().includes(search) ||
      h.pcbResult?.boardNumber?.toLowerCase().includes(search)
    );
  } catch (e) { return []; }
};

// --- BACKUP SYSTEM ---

export const exportDatabase = async (): Promise<string> => {
  const allData = await getAllRepairs();
  return JSON.stringify(allData, null, 2);
};

export const importDatabase = async (jsonContent: string): Promise<boolean> => {
  try {
    const data = JSON.parse(jsonContent);
    if (!Array.isArray(data)) throw new Error("Formato de archivo inválido");

    // Usamos una transacción para importar todo
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onsuccess = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            const transaction = db.transaction(HISTORY_STORE, 'readwrite');
            const store = transaction.objectStore(HISTORY_STORE);

            // Limpiar antes de importar? O mezclar? 
            // Para seguridad, vamos a mezclar (upsert). Si existe lo sobreescribe, si no lo crea.
            data.forEach(item => {
                if (item.timestamp) {
                    store.put(item);
                }
            });

            transaction.oncomplete = () => {
                db.close();
                resolve(true);
            };
            transaction.onerror = () => {
                db.close();
                reject(false);
            };
        };
        request.onerror = () => reject(false);
    });
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAllRepairs, deleteRepairFromHistory, exportDatabase, importDatabase } from '../services/storage';
import ConfirmDialog from '../components/ConfirmDialog';

interface DatabaseScreenProps {
  onLoadRepair: (repair: any) => void;
}

const DatabaseScreen: React.FC<DatabaseScreenProps> = ({ onLoadRepair }) => {
  const [history, setHistory] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'history' | 'components' | 'schematics'>('history');
  const [isLoading, setIsLoading] = useState(true);
  const [deletingId, setDeletingId] = useState<number | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<number | null>(null);
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setIsLoading(true);
    try {
      const data = await getAllRepairs();
      setHistory(data.sort((a, b) => Number(b.timestamp) - Number(a.timestamp)));
    } catch (e) {
      console.error("Load failed", e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRequestDelete = (e: React.MouseEvent, timestamp: number) => {
    e.stopPropagation();
    setConfirmDeleteId(timestamp);
  };

  const handleConfirmDelete = async () => {
    if (confirmDeleteId === null) return;
    const ts = Number(confirmDeleteId);
    setConfirmDeleteId(null);
    setDeletingId(ts);

    try {
      const success = await deleteRepairFromHistory(ts);
      if (success) {
        setHistory(prev => prev.filter(item => Number(item.timestamp) !== ts));
      } else {
        alert("Error al eliminar.");
      }
    } catch (err) {
      console.error(err);
    } finally {
      setDeletingId(null);
    }
  };

  const handleExport = async () => {
    try {
        const json = await exportDatabase();
        const blob = new Blob([json], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        const date = new Date().toISOString().split('T')[0];
        a.download = `gusrepart_backup_${date}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    } catch (e) {
        alert("Error al generar la copia de seguridad.");
    }
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          setIsLoading(true);
          try {
              const success = await importDatabase(content);
              if (success) {
                  alert("Base de datos restaurada con éxito.");
                  await loadData();
              } else {
                  alert("Error: El archivo no es válido o está corrupto.");
              }
          } catch(err) {
              alert("Error crítico durante la importación.");
          } finally {
              setIsLoading(false);
              if (fileInputRef.current) fileInputRef.current.value = "";
          }
      };
      reader.readAsText(file);
  };

  const allIdentifiedComponents = history.reduce((acc: string[], curr: any) => {
    const comps = curr.pcbResult?.identifiedComponents || [];
    comps.forEach((c: string) => {
       if (!acc.includes(c)) acc.push(c);
    });
    return acc;
  }, []);

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
      <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileChange} />

      <div className="max-w-6xl mx-auto flex flex-col gap-8">
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end border-b border-border-dark pb-6 gap-6">
          <div className="flex flex-col gap-2">
            <h1 className="text-4xl font-black text-white">Base de Datos</h1>
            <p className="text-text-secondary font-medium">Registro Maestro (v1.0-STABLE)</p>
          </div>

          <div className="flex flex-wrap gap-3 items-center w-full lg:w-auto">
             <div className="flex bg-border-dark p-1 rounded-xl w-full sm:w-auto">
                {(['history', 'components', 'schematics'] as const).map((tab) => (
                <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`flex-1 sm:flex-none px-4 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'text-text-secondary hover:text-white'}`}
                >
                    {tab === 'history' ? 'Historial' : tab === 'components' ? 'Comp.' : 'Esq.'}
                </button>
                ))}
            </div>

            <div className="h-8 w-px bg-border-dark hidden lg:block mx-2"></div>

            <button onClick={handleExport} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-[#161b26] border border-white/10 hover:bg-white/5 rounded-xl text-white text-xs font-bold transition-all">
                <span className="material-symbols-outlined text-emerald-400">cloud_download</span>
                <span>Backup</span>
            </button>
            <button onClick={handleImportClick} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-[#161b26] border border-white/10 hover:bg-white/5 rounded-xl text-white text-xs font-bold transition-all">
                <span className="material-symbols-outlined text-blue-400">cloud_upload</span>
                <span>Restaurar</span>
            </button>
          </div>
        </div>

        {activeTab === 'history' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {isLoading ? (
              <div className="col-span-full py-40 text-center">
                <span className="material-symbols-outlined text-4xl text-primary animate-spin mb-4">progress_activity</span>
                <p className="text-text-secondary font-mono">Accediendo a la base de datos...</p>
              </div>
            ) : history.length === 0 ? (
              <div className="col-span-full py-24 text-center border-2 border-dashed border-border-dark rounded-3xl opacity-20">
                <span className="material-symbols-outlined text-8xl mb-4">folder_off</span>
                <p className="text-lg font-bold">Base de datos vacía</p>
                <p className="text-sm mt-2">Usa "Restaurar" si tienes una copia de seguridad.</p>
              </div>
            ) : (
              history.map((item) => (
                <div 
                  key={item.timestamp} 
                  className={`bg-surface-dark border border-border-dark rounded-2xl overflow-hidden group hover:border-primary/40 transition-all flex flex-col shadow-xl ${deletingId === Number(item.timestamp) ? 'opacity-30 pointer-events-none scale-95' : ''}`}
                >
                  <div className="h-40 bg-black/50 relative cursor-pointer" onClick={() => { onLoadRepair(item); navigate('/pcb-id'); }}>
                    {item.pcbImages?.[0] ? (
                      <img src={item.pcbImages[0]} className="w-full h-full object-cover opacity-60 group-hover:opacity-80 transition-opacity" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center opacity-10">
                        <span className="material-symbols-outlined text-6xl">memory</span>
                      </div>
                    )}
                    <button 
                      onClick={(e) => handleRequestDelete(e, item.timestamp)}
                      disabled={deletingId !== null}
                      className="absolute top-3 right-3 p-2 bg-red-500/20 hover:bg-red-600 text-white rounded-xl transition-all border border-red-500/30 z-20 hover:scale-110 active:scale-90"
                      title="Eliminar Registro"
                    >
                      <span className="material-symbols-outlined text-[18px]">delete_forever</span>
                    </button>
                    <div className="absolute bottom-3 left-3 bg-primary/80 px-2 py-1 rounded text-[9px] font-bold text-white shadow-lg">
                      {new Date(item.timestamp).toLocaleDateString()}
                    </div>
                  </div>
                  <div className="p-5 flex-1 flex flex-col">
                    <h3 className="text-base font-bold text-white truncate">{item.pcbResult?.model || "Sin Nombre"}</h3>
                    <p className="text-[10px] text-text-secondary font-mono mt-1 mb-4 uppercase tracking-tighter">{item.pcbResult?.boardNumber || "Serial N/A"}</p>
                    <button 
                      onClick={() => { onLoadRepair(item); navigate('/pcb-id'); }}
                      className="mt-auto w-full py-3 bg-[#111722] hover:bg-primary border border-white/5 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm active:scale-95"
                    >
                      Recuperar Sesión
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'components' && (
           <div className="bg-surface-dark border border-border-dark rounded-3xl p-8 shadow-2xl">
              <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
                 <span className="material-symbols-outlined text-primary">microchip</span>
                 Inventario Detectado
              </h2>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
                 {allIdentifiedComponents.map((c, i) => (
                   <div key={i} className="p-4 bg-background-dark border border-white/5 rounded-2xl text-center shadow-lg">
                      <p className="text-[10px] font-mono text-primary font-black uppercase">{c}</p>
                   </div>
                 ))}
                 {allIdentifiedComponents.length === 0 && <p className="col-span-full py-10 text-center opacity-30 text-sm italic">Sin datos registrados.</p>}
              </div>
           </div>
        )}
      </div>

      <ConfirmDialog 
        isOpen={confirmDeleteId !== null}
        title="Eliminar Registro"
        message="¿Estás seguro de que quieres eliminar esta reparación del historial permanentemente? Esta acción no se puede deshacer."
        confirmText="Sí, Eliminar"
        cancelText="No, Mantener"
        isDestructive={true}
        onConfirm={handleConfirmDelete}
        onCancel={() => setConfirmDeleteId(null)}
      />
    </div>
  );
};

export default DatabaseScreen;

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSearchingData, setIsSearchingData] = useState(false); // Nuevo estado para la búsqueda secundaria
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);
  const [isEditing, setIsEditing] = useState(false);

  // ESTADO INICIAL
  const [images, setImages] = useState<string[]>(
    (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""]
  );

  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [dataSearchStatus, setDataSearchStatus] = useState<string>(""); // Estado búsqueda esquemas
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  useEffect(() => {
    const targetImages = (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""];
    if (JSON.stringify(targetImages) !== JSON.stringify(images)) {
      setImages(targetImages);
    }
    if (JSON.stringify(persistedResult) !== JSON.stringify(result)) {
      setResult(persistedResult);
    }
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result?.model]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot] || isEnhancing !== null) return;
    setIsEnhancing(slot);
    try {
      const enhanced = await enhancePCBImage(images[slot].split(',')[1]);
      const newImages = [...images];
      newImages[slot] = enhanced;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
    } catch (err) {
      alert("Error al mejorar imagen");
    } finally {
      setIsEnhancing(null);
    }
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  // PASO 1: Análisis Visual SOLAMENTE (OCR + Detección de Componentes)
  const runVisualAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) return;
    setIsAnalyzing(true);
    setStatus("Analizando estructura visual...");
    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);
      const analysis = await analyzePCBImage(pureBase64s);
      setResult(analysis);
      // Solo actualizamos imágenes y resultado visual, NO buscamos esquemas aún
      onUpdate(images, analysis);
      setIsEditing(true); // Abrimos modo edición para que el usuario verifique
    } catch (error) {
      console.error(error);
      setStatus("Fallo en análisis de IA.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  // PASO 2: Confirmación y Búsqueda de Datos (Esquemas + Funcionalidad)
  const confirmAndSearchData = async () => {
    if (!result) return;
    setIsSearchingData(true);
    setDataSearchStatus("Buscando esquemas y manuales...");
    setIsEditing(false); // Cerramos edición

    try {
      const query = `${result.manufacturer} ${result.model} ${result.boardNumber}`;

      // Ejecutamos búsquedas en paralelo con los datos CONFIRMADOS por el usuario
      const [schematics, functional] = await Promise.all([
        searchSchematics(query),
        getFunctionalAnalysis(result.identifiedComponents, result.boardNumber || result.model)
      ]);

      // Guardamos todo
      onUpdate(images, result, schematics, functional);
      setDataSearchStatus("Datos sincronizados.");
    } catch (error) {
      console.error(error);
      setDataSearchStatus("Error buscando datos externos.");
    } finally {
      setIsSearchingData(false);
      setTimeout(() => setDataSearchStatus(""), 3000);
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    const newResult = result ? { ...result, [field]: value } : { 
      manufacturer: field === 'manufacturer' ? value : '', 
      model: field === 'model' ? value : '', 
      boardNumber: field === 'boardNumber' ? value : '', 
      confidence: 1, identifiedComponents: [], detectedAnomalies: [] 
    };
    setResult(newResult);
    onUpdate(images, newResult);
  };

  // Modo Manual Puro
  const enableManualMode = () => {
      if(!result) {
          setResult({
              manufacturer: '',
              model: '',
              boardNumber: '',
              confidence: 1,
              identifiedComponents: [],
              detectedAnomalies: []
          });
      }
      setIsEditing(true);
  };

  // Handlers de UI (Zoom, etc)
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setScale(prev => Math.min(Math.max(1, prev + (e.deltaY > 0 ? -0.2 : 0.2)), 5));
  };
  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
          style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
        >
          <div className="absolute top-6 right-6 z-10">
            <button onClick={() => setZoomImage(null)} className="p-3 bg-red-500 rounded-full text-white shadow-xl">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <div style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` }}>
            <img src={zoomImage} className="max-w-none h-[85vh] object-contain select-none" draggable={false} />
          </div>
        </div>
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black text-white">Identificación de Hardware</h1>
            <p className="text-text-secondary">Sube fotos o introduce los datos manualmente para iniciar la búsqueda.</p>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 min-h-[350px]">
            {[0, 1].map((slot) => (
              <div key={slot} className={`relative flex items-center justify-center rounded-2xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-border-dark'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden shadow-lg`}>
                {images[slot] ? (
                  <>
                    <img src={images[slot]} className="absolute inset-0 w-full h-full object-cover opacity-60" />
                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                      <button onClick={() => setZoomImage(images[slot])} className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform">
                        <span className="material-symbols-outlined text-3xl">zoom_in</span>
                      </button>
                      <button onClick={(e) => handleEnhance(e, slot)} className={`p-3 bg-surface-dark rounded-xl text-white border border-white/10 ${isEnhancing === slot ? 'animate-spin' : ''}`}>
                        <span className="material-symbols-outlined">auto_fix</span>
                      </button>
                      <button onClick={(e) => handleRemoveImage(e, slot)} className="p-3 bg-red-500/20 text-red-500 rounded-xl border border-red-500/30">
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <button onClick={() => { setActiveSlot(slot); fileInputRef.current?.click(); }} className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center group">
                    <div className="size-16 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform border border-primary/20">
                      <span className="material-symbols-outlined text-4xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-text-secondary">{slot === 0 ? 'Subir Frente' : 'Subir Reverso'}</p>
                  </button>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col md:flex-row items-center justify-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse w-full text-center md:hidden">{status}</p>}

             <button 
               onClick={runVisualAnalysis} 
               disabled={images.filter(img => img && img.length > 0).length === 0 || isAnalyzing || isSearchingData} 
               className="w-full md:w-auto px-8 py-4 rounded-xl font-bold text-lg bg-[#1a2332] border border-primary/30 hover:bg-primary/10 transition-all text-white disabled:opacity-30 flex items-center justify-center gap-3"
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'visibility'}</span>
               <span>{isAnalyzing ? 'Leyendo...' : 'Analizar Imagen'}</span>
             </button>

             <span className="text-text-secondary text-sm font-bold uppercase">- O -</span>

             <button 
                onClick={enableManualMode}
                className="w-full md:w-auto px-6 py-4 rounded-xl font-bold text-sm bg-[#161b26] border border-border-dark hover:bg-white/5 transition-all text-text-secondary hover:text-white flex items-center justify-center gap-2"
             >
                <span className="material-symbols-outlined">keyboard</span>
                Entrada Manual
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] bg-background-dark flex flex-col border-t lg:border-t-0 overflow-y-auto p-6 shadow-2xl z-10">
        <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">analytics</span>
            Ficha Técnica
            </h2>
            {result && (
                <button 
                    onClick={() => setIsEditing(!isEditing)}
                    className={`p-2 rounded-lg transition-colors ${isEditing ? 'bg-primary text-white' : 'text-text-secondary hover:text-white'}`}
                    title={isEditing ? "Ver visualización" : "Editar datos"}
                >
                    <span className="material-symbols-outlined text-sm">{isEditing ? 'visibility' : 'edit'}</span>
                </button>
            )}
        </div>

        {result || images.some(i => i) ? (
          <div className="space-y-6">
            <div className={`p-6 rounded-2xl border transition-all relative overflow-hidden ${isEditing ? 'bg-[#111722] border-primary/50 ring-1 ring-primary/20' : 'bg-surface-dark border-white/5'}`}>

              {!isEditing && (
                  <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                       <span className="material-symbols-outlined text-6xl">qr_code_2</span>
                  </div>
              )}

              <div className="space-y-4">
                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Fabricante</label>
                  {isEditing ? (
                      <input 
                      type="text" 
                      value={result?.manufacturer || ''} 
                      onChange={(e) => updateResultField('manufacturer', e.target.value)}
                      placeholder="Ej: Dell, HP, Apple"
                      className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                      />
                  ) : (
                      <p className="text-lg font-bold text-white">{result?.manufacturer || <span className="text-white/20 italic">---</span>}</p>
                  )}
                </div>

                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Modelo de Equipo</label>
                   {isEditing ? (
                      <input 
                      type="text" 
                      value={result?.model || ''} 
                      onChange={(e) => updateResultField('model', e.target.value)}
                      placeholder="Ej: MacBook Pro A1708"
                      className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                      />
                  ) : (
                      <p className="text-lg font-bold text-white">{result?.model || <span className="text-white/20 italic">---</span>}</p>
                  )}
                </div>

                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Board Number / Referencia PCB</label>
                   {isEditing ? (
                      <input 
                      type="text" 
                      value={result?.boardNumber || ''} 
                      onChange={(e) => updateResultField('boardNumber', e.target.value)}
                      placeholder="Ej: 820-00840-A"
                      className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-xs font-mono text-primary outline-none"
                      />
                  ) : (
                      <p className="text-sm font-mono text-primary tracking-wide">{result?.boardNumber || <span className="text-white/20 italic">---</span>}</p>
                  )}
                </div>
              </div>

              {isEditing && (
                  <div className="pt-4 mt-4 border-t border-white/5">
                      <p className="text-[10px] text-text-secondary italic flex items-center gap-1">
                          <span className="material-symbols-outlined text-sm">info</span>
                          Verifica estos datos antes de continuar.
                      </p>
                  </div>
              )}
            </div>

            <div className="space-y-4 animate-in fade-in slide-in-from-right-2">
              <button 
                onClick={confirmAndSearchData}
                disabled={!result?.model && !result?.boardNumber || isSearchingData}
                className={`w-full py-4 rounded-xl font-bold text-sm tracking-wide shadow-xl transition-all flex items-center justify-center gap-2
                  ${isSearchingData 
                    ? 'bg-surface-dark text-text-secondary cursor-wait' 
                    : 'bg-primary hover:bg-primary-hover text-white shadow-primary/20'}`}
              >
