import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import ConfirmDialog from './components/ConfirmDialog';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import DatabaseScreen from './screens/DatabaseScreen';
import ComponentDetails from './screens/ComponentDetails';
import ChatBot from './components/ChatBot';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isClearing, setIsClearing] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Modals
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [showNewRepairModal, setShowNewRepairModal] = useState(false);

  // Estados de sesión
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  const [tempModel, setTempModel] = useState({ manufacturer: '', model: '', boardNumber: '' });

  // Carga inicial
  useEffect(() => {
    const initSystem = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);
        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) { console.error("Load failed", e); }
      finally { setIsLoaded(true); }
    };
    initSystem();
  }, []); 

  // Auto-guardado
  useEffect(() => {
    if (isLoaded && !isClearing) {
      const timer = setTimeout(() => {
        if (pcbImages.length > 0 || pcbResult || diagHistory.length > 0) {
            saveSessionData('pcbImages', pcbImages);
            saveSessionData('pcbResult', pcbResult);
            saveSessionData('schematicInfo', schematicInfo);
            saveSessionData('functionalAI', functionalAI);
            saveSessionData('measurements', measurements);
            saveSessionData('diagHistory', diagHistory);
            saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
        }
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded, isClearing]);

  const handleNewRepairConfirm = async () => {
    // 1. Detener auto-guardado
    setIsClearing(true); 

    // 2. Limpiar persistencia
    try {
        await clearSessionStorage();
    } catch(e) { console.error(e); }

    // 3. Resetear todos los estados visuales (Soft Reset)
    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    setMeasurements([]);
    setDiagHistory([]);
    setCurrentRepairTimestamp(null);
    setTempModel({ manufacturer: '', model: '', boardNumber: '' });

    // 4. Navegar y cerrar modal
    setShowNewRepairModal(false);
    navigate('/pcb-id');

    // 5. Reactivar auto-guardado tras breve pausa
    setTimeout(() => {
        setIsClearing(false);
    }, 500);
  };

  const executeSave = async (metadata?: any) => {
    setIsSaving(true);
    try {
      const ts = currentRepairTimestamp || Date.now();
      const finalRes = metadata ? { ...pcbResult, ...metadata } : pcbResult;
      const record = {
        timestamp: ts,
        pcbImages,
        pcbResult: finalRes,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };
      await saveRepairToHistory(record);
      setCurrentRepairTimestamp(ts);
      setPcbResult(finalRes as PCBAnalysisResult);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      setShowSaveModal(false);
    } catch (e) {
      alert("Error guardando.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleGlobalSave = () => {
    if (currentRepairTimestamp && pcbResult?.model) {
      executeSave();
    } else {
      setTempModel({ 
        manufacturer: pcbResult?.manufacturer || '', 
        model: pcbResult?.model || '', 
        boardNumber: pcbResult?.boardNumber || '' 
      });
      setShowSaveModal(true);
    }
  };

  const loadRepair = (repair: any) => {
    setIsClearing(true);
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
    setTimeout(() => setIsClearing(false), 500);
  };

  if (!isLoaded) return null;

  return (
    <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display relative">
      <Sidebar onNewRepair={() => setShowNewRepairModal(true)} />
      <div className="flex-1 flex flex-col min-w-0 relative">
        <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
        <main className="flex-1 overflow-hidden relative">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/pcb-id" element={<PCBIdentification persistedImages={pcbImages} persistedResult={pcbResult} onUpdate={(imgs, res, schem, func) => { 
                if (!isClearing) {
                  setPcbImages([...imgs]);
                  if (res !== undefined) setPcbResult(res);
                  if (schem !== undefined) setSchematicInfo(schem);
                  if (func !== undefined) setFunctionalAI(func);
                }
            }} />} />
            <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
            <Route path="/measure" element={<GuidedMeasurement pcbImages={pcbImages} pcbResult={pcbResult} functionalAI={functionalAI} persistedPoints={measurements} onUpdate={(p) => !isClearing && setMeasurements(p)} />} />
            <Route path="/diagnostics" element={<DiagnosticDecisionTree persistedHistory={diagHistory} pcbResult={pcbResult} onUpdate={(h) => !isClearing && setDiagHistory(h)} />} />
            <Route path="/component" element={<ComponentDetails />} />
            <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepair} />} />
          </Routes>
        </main>
        <ChatBot />
      </div>

      <ConfirmDialog 
        isOpen={showNewRepairModal}
        title="Iniciar Nueva Reparación"
        message="Se limpiará la mesa de trabajo actual para comenzar un nuevo diagnóstico. Asegúrate de haber guardado cambios importantes."
        confirmText="Sí, Limpiar Todo"
        onConfirm={handleNewRepairConfirm}
        onCancel={() => setShowNewRepairModal(false)}
      />

      {showSaveModal && (
        <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4">
          <div className="bg-surface-dark w-full max-w-md rounded-2xl p-8 border border-border-dark shadow-2xl animate-in zoom-in-95">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">save</span>
              Guardar en Base de Datos
            </h2>
            <div className="space-y-4">
              <input placeholder="Marca" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.manufacturer} onChange={e => setTempModel({...tempModel, manufacturer: e.target.value})} />
              <input placeholder="Modelo / Nombre" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.model} onChange={e => setTempModel({...tempModel, model: e.target.value})} />
              <input placeholder="Board Number" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2 font-mono" value={tempModel.boardNumber} onChange={e => setTempModel({...tempModel, boardNumber: e.target.value})} />
            </div>
            <div className="flex gap-4 mt-8">
              <button onClick={() => setShowSaveModal(false)} className="flex-1 py-3 border border-border-dark rounded-xl hover:bg-white/5 font-bold transition-colors">Cerrar</button>
              <button onClick={() => executeSave(tempModel)} className="flex-1 py-3 bg-primary rounded-xl font-bold shadow-lg shadow-primary/20 hover:bg-primary-hover active:scale-95 transition-all">Guardar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => (
  <HashRouter>
    <AppContent />
  </HashRouter>
);

export default App;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { generateMeasurementPlan, getFinalVerdict } from '../services/gemini';
import { MeasurementPoint } from '../types';

interface GuidedMeasurementProps {
  pcbImages: string[];
  pcbResult: any;
  functionalAI: string;
  persistedPoints: MeasurementPoint[];
  onUpdate: (points: MeasurementPoint[]) => void;
}

const GuidedMeasurement: React.FC<GuidedMeasurementProps> = ({ pcbImages, pcbResult, functionalAI, persistedPoints, onUpdate }) => {
  const [points, setPoints] = useState<MeasurementPoint[]>(persistedPoints || []);
  const [activeIdx, setActiveIdx] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [isVerdictLoading, setIsVerdictLoading] = useState(false);
  const [verdict, setVerdict] = useState<string | null>(null);

  // Sincronizar con props
  useEffect(() => {
    setPoints(persistedPoints || []);
  }, [persistedPoints]);

  useEffect(() => {
    const initPlan = async () => {
      if (pcbResult && functionalAI && points.length === 0) {
        setIsLoading(true);
        try {
          const plan = await generateMeasurementPlan(pcbResult, functionalAI);
          const formatted: MeasurementPoint[] = plan.map(p => ({ ...p, status: 'pending' }));
          setPoints(formatted);
          onUpdate(formatted);
        } catch (e) {
          console.error("Failed to generate plan", e);
        } finally {
          setIsLoading(false);
        }
      }
    };
    initPlan();
  }, [pcbResult, functionalAI]);

  const handleValueChange = (val: string) => {
    const newPoints = [...points];
    newPoints[activeIdx].measuredValue = val;

    const expected = parseFloat(newPoints[activeIdx].expectedValue);
    const measured = parseFloat(val);

    if (!isNaN(measured)) {
      if (measured < 0.01 && expected > 0.1) newPoints[activeIdx].status = 'fail';
      else newPoints[activeIdx].status = 'ok';
    } else {
      newPoints[activeIdx].status = 'pending';
    }

    setPoints(newPoints);
    onUpdate(newPoints);
  };

  const generateVerdict = async () => {
    setIsVerdictLoading(true);
    try {
      const res = await getFinalVerdict(pcbResult, points);
      setVerdict(res);
    } catch (e) {
      alert("Error al generar veredicto");
    } finally {
      setIsVerdictLoading(false);
    }
  };

  if (!pcbResult) return (
    <div className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-30">
      <span className="material-symbols-outlined text-8xl mb-4">analytics</span>
      <h2 className="text-2xl font-bold">Primero Analice una Placa</h2>
      <Link to="/pcb-id" className="mt-6 px-6 py-3 bg-primary rounded-xl text-white font-bold">Ir al Analizador</Link>
    </div>
  );

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-[#0f1219]">
      <div className="flex-1 relative overflow-hidden flex flex-col bg-black">
        <div className="w-full h-full relative overflow-hidden flex items-center justify-center">
          {pcbImages.length > 0 ? (
            <div className="relative w-full h-full">
              <img src={pcbImages[0]} alt="PCB View" className="w-full h-full object-contain opacity-70" />
              <div className="absolute inset-0 grid-bg opacity-20 pointer-events-none"></div>
              {points[activeIdx] && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                  <div className="relative">
                    <div className="size-20 border-2 border-primary rounded-full animate-ping opacity-50"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 size-4 bg-primary rounded-full shadow-[0_0_20px_#135bec]"></div>
                    <div className="absolute top-12 left-1/2 -translate-x-1/2 bg-primary px-3 py-1 rounded text-[10px] font-bold whitespace-nowrap uppercase tracking-wider">
                       Test: {points[activeIdx].component}
                    </div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="text-text-secondary italic">Imagen de referencia no disponible</div>
          )}
        </div>
      </div>

      <div className="w-full lg:w-[450px] bg-[#111722] border-l border-[#232f48] flex flex-col h-full z-20 shadow-2xl overflow-y-auto">
        <div className="p-6 border-b border-[#232f48] bg-surface-dark/50">
          <span className="text-[10px] uppercase tracking-[0.2em] font-bold text-primary">Diagnóstico Sistemático</span>
          <h2 className="text-xl font-bold text-white mt-1">Guía de Medición</h2>
        </div>

        <div className="flex-1 p-6 space-y-6">
          {isLoading ? (
            <div className="space-y-4 animate-pulse">
              {[1, 2, 3].map(i => <div key={i} className="h-24 bg-border-dark rounded-xl"></div>)}
            </div>
          ) : (
            <div className="space-y-4">
              {points.map((p, idx) => (
                <div 
                  key={p.id}
                  onClick={() => setActiveIdx(idx)}
                  className={`p-4 rounded-xl border transition-all cursor-pointer ${activeIdx === idx ? 'bg-primary/10 border-primary shadow-[0_0_15px_rgba(19,91,236,0.1)]' : 'bg-surface-dark border-border-dark hover:border-white/10'}`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex gap-3">
                      <div className={`size-8 rounded flex items-center justify-center font-bold text-xs ${p.status === 'ok' ? 'bg-green-500/20 text-green-500' : p.status === 'fail' ? 'bg-red-500/20 text-red-500' : 'bg-white/5 text-white/40'}`}>
                        {idx + 1}
                      </div>
                      <div>
                        <h4 className="text-sm font-bold text-white uppercase">{p.component}</h4>
                        <p className="text-[10px] text-text-secondary mt-0.5">{p.testPoint} | Modo {p.mode}</p>
                      </div>
                    </div>
                    <span className="text-[10px] font-mono text-primary font-bold">{p.expectedValue} Exp.</span>
                  </div>

                  {activeIdx === idx && (
                    <div className="mt-4 space-y-3">
                       <p className="text-[11px] text-text-secondary leading-relaxed italic border-l-2 border-primary/40 pl-3">{p.description}</p>
                       <div className="relative">
                          <input 
                            value={p.measuredValue || ''}
                            onChange={(e) => handleValueChange(e.target.value)}
                            placeholder="0.000"
                            autoFocus
                            className={`w-full bg-black/40 border ${p.status === 'fail' ? 'border-red-500/50' : 'border-border-dark'} rounded-lg p-3 text-xl font-mono font-bold text-white focus:ring-1 focus:ring-primary outline-none`}
                          />
                          <span className="absolute right-3 top-1/2 -translate-y-1/2 font-bold text-primary text-sm">{p.mode}</span>
                       </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

          {verdict && (
            <div className="bg-primary/10 border border-primary/30 p-5 rounded-2xl animate-in zoom-in-95">
               <h3 className="font-bold flex items-center gap-2 mb-2 text-primary">
                 <span className="material-symbols-outlined">gavel</span>
                 Diagnóstico Final AI
               </h3>
               <div className="text-xs text-text-secondary leading-relaxed whitespace-pre-wrap font-medium">
                 {verdict}
               </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-[#232f48] bg-surface-dark/80 backdrop-blur-md sticky bottom-0">
          {points.length > 0 && points.every(p => p.measuredValue) ? (
            <button 
              onClick={generateVerdict}
              disabled={isVerdictLoading}
              className="w-full bg-primary hover:bg-primary-hover text-white py-4 rounded-xl font-bold shadow-xl shadow-primary/20 transition-all flex items-center justify-center gap-2 group text-lg disabled:opacity-50"
            >
              <span className="material-symbols-outlined">{isVerdictLoading ? 'sync' : 'verified'}</span>
              <span>{isVerdictLoading ? 'Procesando...' : 'Obtener Veredicto'}</span>
            </button>
          ) : (
             <div className="text-center py-2">
                <p className="text-[10px] text-text-secondary font-bold uppercase tracking-widest mb-2">Faltan Mediciones</p>
                <div className="flex gap-1.5 justify-center">
                  {points.map((p, i) => (
                    <div key={i} className={`size-1.5 rounded-full transition-colors ${p.measuredValue ? 'bg-primary' : 'bg-border-dark'}`}></div>
                  ))}
                </div>
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default GuidedMeasurement;

{
  "name": "Gusrepart AI Expert",
  "description": "A sophisticated AI-driven expert system for electronic repair, diagnostic guidance, and PCB analysis using the latest Gemini models.",
  "requestFramePermissions": [
    "camera"
  ]
}

import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs } from "./storage";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const ai = getAI();

  // BUSQUEDA DE MEMORIA LOCAL
  let localContext = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) {
      localContext = `HISTORIAL DEL TALLER: Se han encontrado ${similar.length} reparaciones similares de este modelo. Resultados previos: ${similar.map(s => s.pcbResult.detectedAnomalies.join(", ")).join("; ")}.`;
    }
  }

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [
      ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
      { role: 'user', parts: [{ text: currentIssue }] }
    ],
    config: {
      systemInstruction: `Eres Gusrepart AI, experto en microelectrónica. ${localContext} Usa estos datos históricos para ser más preciso. Si el historial indica fallos comunes, menciónalos.`,
      thinkingConfig: { thinkingBudget: 32768 }
    }
  });
  return response.text;
};

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string): Promise<MeasurementPoint[]> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Basado en este análisis de hardware: ${JSON.stringify(pcbResult)} y este análisis funcional: ${functionalAnalysis}, genera un plan de 4 a 6 puntos de medición críticos para diagnosticar la placa. Devuelve un JSON array de objetos con: id, component, testPoint, mode (V, Diode, Ohm), expectedValue (ej: "0.450V", "12V"), description (por qué medir esto).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            component: { type: Type.STRING },
            testPoint: { type: Type.STRING },
            mode: { type: Type.STRING },
            expectedValue: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["id", "component", "testPoint", "mode", "expectedValue", "description"]
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

export const getFinalVerdict = async (pcbResult: any, measurements: MeasurementPoint[]): Promise<string> => {
  const ai = getAI();
  const data = {
    board: pcbResult,
    measurements: measurements.map(m => ({
      ponto: m.component,
      esperado: m.expectedValue,
      medido: m.measuredValue,
      descripcion: m.description
    }))
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analiza estos resultados de laboratorio: ${JSON.stringify(data)}. Da un veredicto final de reparación: 1. Causa probable. 2. Componente defectuoso. 3. Pasos para la solución. Sé muy técnico y preciso.`,
    config: { thinkingConfig: { thinkingBudget: 10000 } }
  });

  return response.text || "No se pudo generar un veredicto.";
};

export const enhancePCBImage = async (base64Image: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image,
            mimeType: 'image/jpeg',
          },
        },
        {
          text: 'Actúa como un sistema de mejora de imágenes para microelectrónica. Procesa esta imagen de PCB para: 1. Aumentar la nitidez de los bordes de los componentes. 2. Reducir el ruido del sensor. 3. Resaltar los números de serie y marcas en los integrados. Devuelve únicamente la imagen mejorada.',
        },
      ],
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No se pudo generar la imagen mejorada");
};

export const analyzePCBImage = async (base64Images: string[], userContext?: { model?: string, serial?: string, symptoms?: string }): Promise<any> => {
  const ai = getAI();

  const imageParts = base64Images.map(base64 => ({
    inlineData: { data: base64, mimeType: 'image/jpeg' }
  }));

  let prompt = "Analiza estas imágenes de una PCB.";

  if (userContext) {
    prompt += `\nIMPORTANTE - Contexto del Técnico:
    - Modelo Reportado: ${userContext.model || "Desconocido"}
    - Serial/ID: ${userContext.serial || "N/A"}
    - SÍNTOMAS DE AVERÍA: ${userContext.symptoms || "Sin especificar"}

    Instrucciones Adicionales:
    1. Si el usuario proveyó un modelo, verifícalo visualmente pero úsalo como base.
    2. Usa los SÍNTOMAS para buscar fallos específicos en la imagen. Ejemplo: Si dice "no carga", busca el IC de carga o puerto USB dañado. Si dice "sin video", revisa zona GPU/LVDS.
    3. En 'detectedAnomalies', incluye tanto lo que ves físicamente como sospechas lógicas basadas en los síntomas (ej: "Posible fallo en PMIC debido a síntoma de no encendido").`;
  } else {
    prompt += `\n1. Identifica fabricante, modelo y board number. 2. Identifica componentes críticos. 3. Busca visualmente posibles fallos (corrosión, componentes quemados).`;
  }

  prompt += `\n4. Devuelve un JSON con: manufacturer, model, boardNumber, confidence, identifiedComponents, detectedAnomalies (array de strings).`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [
      {
        role: 'user',
        parts: [
          ...imageParts,
          { text: prompt }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { type: Type.ARRAY, items: { type: Type.STRING } },
          detectedAnomalies: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents", "detectedAnomalies"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

