import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import ConfirmDialog from './components/ConfirmDialog';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import DatabaseScreen from './screens/DatabaseScreen';
import ComponentDetails from './screens/ComponentDetails';
import KnowledgeBase from './screens/KnowledgeBase';
import ChatBot from './components/ChatBot';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory } from './services/storage';

const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isClearing, setIsClearing] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Modals
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [showNewRepairModal, setShowNewRepairModal] = useState(false);

  // Estados de sesión
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);
  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  const [tempModel, setTempModel] = useState({ manufacturer: '', model: '', boardNumber: '' });

  // Carga inicial
  useEffect(() => {
    const initSystem = async () => {
      try {
        const [imgs, res, schem, func, meas, diag, ts] = await Promise.all([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp')
        ]);
        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
      } catch (e) { console.error("Load failed", e); }
      finally { setIsLoaded(true); }
    };
    initSystem();
  }, []); 

  // Auto-guardado
  useEffect(() => {
    if (isLoaded && !isClearing) {
      const timer = setTimeout(() => {
        if (pcbImages.length > 0 || pcbResult || diagHistory.length > 0) {
            saveSessionData('pcbImages', pcbImages);
            saveSessionData('pcbResult', pcbResult);
            saveSessionData('schematicInfo', schematicInfo);
            saveSessionData('functionalAI', functionalAI);
            saveSessionData('measurements', measurements);
            saveSessionData('diagHistory', diagHistory);
            saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
        }
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, isLoaded, isClearing]);

  const handleNewRepairConfirm = async () => {
    setIsClearing(true); 
    try {
        await clearSessionStorage();
    } catch(e) { console.error(e); }

    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    setMeasurements([]);
    setDiagHistory([]);
    setCurrentRepairTimestamp(null);
    setTempModel({ manufacturer: '', model: '', boardNumber: '' });

    setShowNewRepairModal(false);
    navigate('/pcb-id');

    setTimeout(() => {
        setIsClearing(false);
    }, 500);
  };

  const executeSave = async (metadata?: any) => {
    setIsSaving(true);
    try {
      const ts = currentRepairTimestamp || Date.now();
      const finalRes = metadata ? { ...pcbResult, ...metadata } : pcbResult;
      const record = {
        timestamp: ts,
        pcbImages,
        pcbResult: finalRes,
        schematicInfo,
        functionalAI,
        measurements,
        diagHistory
      };
      await saveRepairToHistory(record);
      setCurrentRepairTimestamp(ts);
      setPcbResult(finalRes as PCBAnalysisResult);
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      setShowSaveModal(false);
    } catch (e) {
      alert("Error guardando.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleGlobalSave = () => {
    if (currentRepairTimestamp && pcbResult?.model) {
      executeSave();
    } else {
      setTempModel({ 
        manufacturer: pcbResult?.manufacturer || '', 
        model: pcbResult?.model || '', 
        boardNumber: pcbResult?.boardNumber || '' 
      });
      setShowSaveModal(true);
    }
  };

  const loadRepair = (repair: any) => {
    setIsClearing(true);
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []);
    setDiagHistory(repair.diagHistory || []);
    setCurrentRepairTimestamp(repair.timestamp || null);
    setTimeout(() => setIsClearing(false), 500);
  };

  if (!isLoaded) return null;

  return (
    <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display relative">
      <Sidebar onNewRepair={() => setShowNewRepairModal(true)} />
      <div className="flex-1 flex flex-col min-w-0 relative">
        <Header onSave={handleGlobalSave} isSaving={isSaving} isSuccess={saveSuccess} />
        <main className="flex-1 overflow-hidden relative">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/pcb-id" element={<PCBIdentification persistedImages={pcbImages} persistedResult={pcbResult} onUpdate={(imgs, res, schem, func) => { 
                if (!isClearing) {
                  setPcbImages([...imgs]);
                  if (res !== undefined) setPcbResult(res);
                  if (schem !== undefined) setSchematicInfo(schem);
                  if (func !== undefined) setFunctionalAI(func);
                }
            }} />} />
            <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
            <Route path="/measure" element={<GuidedMeasurement pcbImages={pcbImages} pcbResult={pcbResult} functionalAI={functionalAI} persistedPoints={measurements} onUpdate={(p) => !isClearing && setMeasurements(p)} />} />
            <Route path="/diagnostics" element={<DiagnosticDecisionTree persistedHistory={diagHistory} pcbResult={pcbResult} onUpdate={(h) => !isClearing && setDiagHistory(h)} />} />
            <Route path="/component" element={<ComponentDetails />} />
            <Route path="/knowledge" element={<KnowledgeBase />} />
            <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepair} />} />
          </Routes>
        </main>
        <ChatBot />
      </div>

      <ConfirmDialog 
        isOpen={showNewRepairModal}
        title="Iniciar Nueva Reparación"
        message="Se limpiará la mesa de trabajo actual para comenzar un nuevo diagnóstico. Asegúrate de haber guardado cambios importantes."
        confirmText="Sí, Limpiar Todo"
        onConfirm={handleNewRepairConfirm}
        onCancel={() => setShowNewRepairModal(false)}
      />

      {showSaveModal && (
        <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4">
          <div className="bg-surface-dark w-full max-w-md rounded-2xl p-8 border border-border-dark shadow-2xl animate-in zoom-in-95">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
              <span className="material-symbols-outlined text-primary">save</span>
              Guardar en Base de Datos
            </h2>
            <div className="space-y-4">
              <input placeholder="Marca" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.manufacturer} onChange={e => setTempModel({...tempModel, manufacturer: e.target.value})} />
              <input placeholder="Modelo / Nombre" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2" value={tempModel.model} onChange={e => setTempModel({...tempModel, model: e.target.value})} />
              <input placeholder="Board Number" className="w-full bg-black/40 border border-border-dark rounded-xl px-4 py-2 font-mono" value={tempModel.boardNumber} onChange={e => setTempModel({...tempModel, boardNumber: e.target.value})} />
            </div>
            <div className="flex gap-4 mt-8">
              <button onClick={() => setShowSaveModal(false)} className="flex-1 py-3 border border-border-dark rounded-xl hover:bg-white/5 font-bold transition-colors">Cerrar</button>
              <button onClick={() => executeSave(tempModel)} className="flex-1 py-3 bg-primary rounded-xl font-bold shadow-lg shadow-primary/20 hover:bg-primary-hover active:scale-95 transition-all">Guardar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => (
  <HashRouter>
    <AppContent />
  </HashRouter>
);

export default App;

import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext } from "./storage";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

// 1. Función para destilar conocimiento desde input del usuario (RAG Ingestion)
export const distillKnowledge = async (text: string, source: string) => {
  const ai = getAI();

  // Optimizamos el prompt para velocidad y manejo de YouTube
  const isYoutube = text.toLowerCase().includes('youtube.com') || text.toLowerCase().includes('youtu.be');
  const sourceContext = isYoutube ? 'VIDEO DE YOUTUBE (TÉCNICO EN REPARACIÓN)' : source;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview', // Usamos Flash para mayor velocidad
    contents: `
    TAREA URGENTE: Analizar y extraer conocimiento técnico de reparación.
    FUENTE: ${sourceContext}
    URL/TEXTO: ${text}

    OBJETIVO:
    1. Si es un link de YouTube, USA 'googleSearch' para buscar el título, descripción y comentarios relevantes que expliquen la solución o el diagnóstico.
    2. Ignora intros, publicidad o saludos. Ve al grano: Síntoma -> Solución.
    3. Si es texto, resume los puntos clave.

    Genera un JSON estricto:
    - title: Título corto descriptivo (Ej: "Reparación Codec Audio iPhone 7").
    - tags: Lista de 3-5 palabras clave (Modelos, ICs, Fallas).
    - content: Resumen técnico denso. Máximo 1 párrafo con la solución directa.
    `,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
            title: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            content: { type: Type.STRING }
        }
      }
    }
  });

  // Fallback por si la respuesta viene vacía o mal formada
  try {
      return JSON.parse(response.text || '{}');
  } catch (e) {
      return {
          title: "Error de Análisis",
          tags: ["Error"],
          content: "La IA no pudo estructurar la información. Intenta copiar y pegar el resumen del video manualmente."
      };
  }
};

// 2. Diagnóstico enriquecido con conocimiento local
export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const ai = getAI();

  // A. Historial de Reparaciones (Memoria Episódica)
  let repairHistoryContext = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) {
      repairHistoryContext = `HISTORIAL DEL TALLER: Se encontraron ${similar.length} casos previos. Anomalías: ${similar.map(s => s.pcbResult.detectedAnomalies.join(", ")).join("; ")}.`;
    }
  }

  // B. Base de Conocimientos (Memoria Semántica / Expert Knowledge)
  // Buscamos conocimiento relevante basado en el modelo y el problema actual
  const query = `${pcbModel || ''} ${currentIssue}`;
  const knowledgeBaseContext = await searchKnowledgeContext(query);

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [
      ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
      { role: 'user', parts: [{ text: currentIssue }] }
    ],
    config: {
      systemInstruction: `Eres Gusrepart AI, experto senior en microelectrónica.

      CONTEXTO DE APRENDIZAJE:
      ${repairHistoryContext}
      ${knowledgeBaseContext}

      Instrucciones:
      1. Si la 'Base de Conocimientos Expertos' tiene información sobre esta falla específica (ej: tips de YouTube guardados), ÚSALA como fuente principal y menciónalo ("Según tus notas guardadas...").
      2. Razona paso a paso como un ingeniero.
      `,
      thinkingConfig: { thinkingBudget: 32768 }
    }
  });
  return response.text;
};

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string): Promise<MeasurementPoint[]> => {
  const ai = getAI();

  // Inyectamos conocimiento también en el plan de medición
  const knowledgeContext = await searchKnowledgeContext(`${pcbResult.model} ${pcbResult.identifiedComponents.join(' ')}`);

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Análisis HW: ${JSON.stringify(pcbResult)}. Funcional: ${functionalAnalysis}.
    ${knowledgeContext ? `NOTA IMPORTANTE: El usuario tiene este conocimiento guardado sobre esta placa: ${knowledgeContext}. Si menciona voltajes o puntos específicos, inclúyelos.` : ''}
    Genera plan de medición JSON (4-6 puntos).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            component: { type: Type.STRING },
            testPoint: { type: Type.STRING },
            mode: { type: Type.STRING },
            expectedValue: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["id", "component", "testPoint", "mode", "expectedValue", "description"]
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

export const getFinalVerdict = async (pcbResult: any, measurements: MeasurementPoint[]): Promise<string> => {
  const ai = getAI();
  const data = {
    board: pcbResult,
    measurements: measurements.map(m => ({
      ponto: m.component,
      esperado: m.expectedValue,
      medido: m.measuredValue,
      descripcion: m.description
    }))
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Resultados lab: ${JSON.stringify(data)}. Veredicto técnico preciso.`,
    config: { thinkingConfig: { thinkingBudget: 10000 } }
  });

  return response.text || "No se pudo generar un veredicto.";
};

export const enhancePCBImage = async (base64Image: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: 'Mejorar imagen PCB: nitidez, reducir ruido, resaltar texto ICs.' },
      ],
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No se pudo generar la imagen mejorada");
};

export const analyzePCBImage = async (base64Images: string[], userContext?: { model?: string, serial?: string, symptoms?: string }): Promise<any> => {
  const ai = getAI();

  const imageParts = base64Images.map(base64 => ({
    inlineData: { data: base64, mimeType: 'image/jpeg' }
  }));

  let prompt = "Analiza estas imágenes de una PCB.";
  let expertKnowledge = "";

  if (userContext) {
    // Buscamos si tenemos conocimientos previos sobre este modelo
    if (userContext.model) {
        expertKnowledge = await searchKnowledgeContext(userContext.model + " " + (userContext.symptoms || ""));
    }

    prompt += `\nIMPORTANTE - Contexto del Técnico:
    - Modelo: ${userContext.model || "Desconocido"}
    - Síntomas: ${userContext.symptoms || "N/A"}

    ${expertKnowledge}

    Instrucciones:
    1. Si la 'Base de Conocimientos Expertos' menciona componentes específicos que fallan en este modelo (ej: "Revisar capacitor C123"), búscalos prioritariamente en la imagen.
    2. Identifica anomalías visuales relacionadas con los síntomas.`;
  }

  prompt += `\nDevuelve JSON con: manufacturer, model, boardNumber, confidence, identifiedComponents, detectedAnomalies.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [...imageParts, { text: prompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { type: Type.ARRAY, items: { type: Type.STRING } },
          detectedAnomalies: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents", "detectedAnomalies"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const searchSchematics = async (boardInfo: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Busca esquemas/boardview para: ${boardInfo}. Prioriza badcaps, vlab.`,
    config: { tools: [{ googleSearch: {} }] }
  });

  return {
    summary: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.searchEntryPoint?.renderedContent || ""
  };
};

export const analyzeExternalResource = async (url: string, boardInfo: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Analiza recurso: ${url} para placa ${boardInfo}. Resume info técnica valiosa.`,
    config: { tools: [{ googleSearch: {} }] }
