export const getFunctionalAnalysis = async (components: string[], boardModel: string) => {
  const ai = getAI();
  // Inyectamos conocimiento aquí también
  const knowledge = await searchKnowledgeContext(boardModel);

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Placa: ${boardModel}. Componentes: [${components.join(', ')}].
    ${knowledge}
    Genera guía de funcionamiento y voltajes críticos.`,
  });
  return response.text;
};

export const searchComponentInfo = async (query: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: query,
    config: { tools: [{ googleSearch: {} }] }
  });
  return {
    text: response.text,
    sources: response.candidates?.[0]?.groundingMetadata?.searchEntryPoint?.renderedContent
  };
};

export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (base64Audio) {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioData = decodeBase64(base64Audio);
    const buffer = await decodeRawPCM(audioData, ctx, 24000, 1);
    onAudioReady(buffer);
  }
};

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPCM(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / channels;
  const buffer = ctx.createBuffer(channels, frameCount, sampleRate);
  for (let channel = 0; channel < channels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * channels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { distillKnowledge } from '../services/gemini';
import { addKnowledgeEntry, getAllKnowledge, deleteKnowledgeEntry } from '../services/storage';
import { KnowledgeEntry } from '../types';

// Variable global (fuera del componente) para rastrear tareas activas aunque cambie la pantalla
let activeTasksCount = 0;

const KnowledgeBase: React.FC = () => {
  const [entries, setEntries] = useState<KnowledgeEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);

  // Referencia para saber si el componente sigue montado
  const isMounted = useRef(true);

  // Form states
  const [inputContent, setInputContent] = useState("");
  const [inputType, setInputType] = useState<'url' | 'text'>('url');

  useEffect(() => {
    isMounted.current = true;
    loadKnowledge();

    // Auto-refresco suave: Si hay tareas activas o el usuario vuelve a la pestaña, 
    // verificamos si hay nuevos datos en la DB cada 3 segundos.
    const interval = setInterval(() => {
        if (activeTasksCount > 0 || !document.hidden) {
            loadKnowledge(true); // true = silent load
        }
    }, 3000);

    // Sync initial processing state
    if (activeTasksCount > 0) setProcessing(true);

    return () => { isMounted.current = false; clearInterval(interval); };
  }, []);

  const loadKnowledge = async (silent = false) => {
    if (!silent) setLoading(true);
    const data = await getAllKnowledge();
    // Ordenar por más reciente
    const sorted = data.sort((a, b) => b.timestamp - a.timestamp);

    if (isMounted.current) {
        // Solo actualizamos si hay cambios reales para evitar re-renders innecesarios
        setEntries(prev => {
            if (prev.length !== sorted.length || (prev[0]?.id !== sorted[0]?.id)) {
                return sorted;
            }
            return prev;
        });
        if (!silent) setLoading(false);

        // Si no hay tareas globales activas, apagamos el spinner local
        if (activeTasksCount === 0) setProcessing(false);
    }
  };

  const handleLearn = async () => {
    if (!inputContent.trim()) return;

    // Indicamos proceso visualmente
    setProcessing(true);
    activeTasksCount++;

    const contentToProcess = inputContent;
    const typeToProcess = inputType;

    // Limpiamos el input INMEDIATAMENTE para que el usuario sienta que la orden fue recibida
    setInputContent("");

    // Ejecutamos la lógica en una función asíncrona separada para no bloquear la UI
    // y asegurarnos de que termine aunque el componente se desmonte.
    (async () => {
        try {
            // 1. La IA "lee" y resume el conocimiento (Puede tardar 10-20s)
            const distilled = await distillKnowledge(
                contentToProcess, 
                typeToProcess === 'url' ? 'Link Externo (YouTube/Foro)' : 'Nota del Técnico'
            );

            const newEntry: KnowledgeEntry = {
                id: crypto.randomUUID(),
                title: distilled.title || "Conocimiento Sin Título",
                tags: distilled.tags || [],
                content: distilled.content || "Sin contenido procesado",
                source: typeToProcess === 'url' ? contentToProcess : 'Nota Manual',
                timestamp: Date.now()
            };

            // 2. Guardamos en DB Local (PERSISTENTE)
            await addKnowledgeEntry(newEntry);
            console.log("Conocimiento guardado en background:", newEntry.title);

        } catch (e) {
            console.error("Error en background task:", e);
            if (isMounted.current) alert("Hubo un error analizando el contenido.");
        } finally {
            activeTasksCount--;
            // Solo actualizamos estado visual si el usuario sigue en esta pantalla
            if (isMounted.current) {
                if (activeTasksCount === 0) setProcessing(false);
                loadKnowledge(true); // Recarga forzosa
            }
        }
    })();
  };

  const handleDelete = async (id: string) => {
    if (confirm("¿Olvidar este conocimiento?")) {
      await deleteKnowledgeEntry(id);
      await loadKnowledge();
    }
  };

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
      <div className="max-w-6xl mx-auto flex flex-col gap-8">

        <div className="flex flex-col gap-2 border-b border-border-dark pb-6">
          <h1 className="text-4xl font-black text-white flex items-center gap-3">
             <span className="material-symbols-outlined text-purple-400 text-4xl">school</span>
             Entrenamiento de IA
          </h1>
          <p className="text-text-secondary text-lg">Enseña a Gusrepart AI con videos de YouTube, foros y tu propia experiencia.</p>
        </div>

        {/* INPUT AREA */}
        <div className="bg-[#1a2332] border border-border-dark rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-top-4 relative overflow-hidden">
           {processing && (
               <div className="absolute top-0 left-0 w-full h-1 bg-purple-900/50">
                   <div className="h-full bg-purple-500 animate-shimmer w-1/2"></div>
               </div>
           )}

           <div className="flex gap-4 mb-4">
              <button 
                onClick={() => setInputType('url')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${inputType === 'url' ? 'bg-purple-600 text-white' : 'bg-background-dark text-text-secondary hover:text-white'}`}
              >
                <span className="material-symbols-outlined">link</span> Link (YouTube/Web)
              </button>
              <button 
                onClick={() => setInputType('text')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${inputType === 'text' ? 'bg-purple-600 text-white' : 'bg-background-dark text-text-secondary hover:text-white'}`}
              >
                <span className="material-symbols-outlined">edit_note</span> Nota Rápida
              </button>
           </div>

           <div className="flex flex-col md:flex-row gap-4">
              <input 
                value={inputContent}
                onChange={e => setInputContent(e.target.value)}
                placeholder={inputType === 'url' ? "Pega aquí el enlace de YouTube o Foro..." : "Escribe tu tip de reparación (Ej: En iPhone X el error 4013 suele ser..."}
                className="flex-1 bg-black/40 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-purple-500 outline-none transition-colors"
              />
              <button 
                onClick={handleLearn}
                disabled={processing && inputContent === ""} // Permitir encolar si hay texto, bloquear si está vacío
                className="px-8 py-3 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold transition-all shadow-lg shadow-purple-500/20 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
              >
                {processing ? <span className="material-symbols-outlined animate-spin">sync</span> : <span className="material-symbols-outlined">auto_awesome</span>}
                <span>{processing ? 'Analizando...' : 'Analizar y Guardar'}</span>
              </button>
           </div>

           <div className="flex justify-between items-center mt-3">
                <p className="text-xs text-text-secondary flex items-center gap-1">
                    <span className="material-symbols-outlined text-sm">info</span>
                    {inputType === 'url' ? 'La IA buscará el resumen técnico del video. Puede tardar unos segundos.' : 'Se guardará en la base de datos permanente.'}
                </p>
                {processing && (
                    <p className="text-xs text-purple-400 font-bold animate-pulse">
                        Procesando en segundo plano... Puedes cambiar de pestaña.
                    </p>
                )}
           </div>
        </div>

        {/* LISTA DE CONOCIMIENTOS */}
        <div>
           <div className="flex items-center justify-between mb-6">
               <h2 className="text-xl font-bold text-white flex items-center gap-2">
                 <span className="material-symbols-outlined text-purple-400">library_books</span>
                 Base de Conocimiento ({entries.length})
               </h2>
               <button onClick={() => loadKnowledge()} className="p-2 hover:bg-white/5 rounded-lg text-text-secondary hover:text-white transition-colors" title="Refrescar lista">
                   <span className="material-symbols-outlined">refresh</span>
               </button>
           </div>

           {loading && entries.length === 0 ? (
             <div className="py-20 text-center text-text-secondary animate-pulse">Cargando cerebro...</div>
           ) : entries.length === 0 ? (
             <div className="py-20 text-center border-2 border-dashed border-border-dark rounded-3xl opacity-30">
               <span className="material-symbols-outlined text-6xl mb-4">psychology_alt</span>
               <p className="text-lg font-bold">La IA aún no ha aprendido trucos específicos.</p>
               <p className="text-sm">¡Pega un link de tu técnico favorito para empezar!</p>
             </div>
           ) : (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {entries.map(entry => (
                 <div key={entry.id} className="bg-surface-dark border border-border-dark rounded-xl p-5 hover:border-purple-500/50 transition-all group relative animate-in fade-in slide-in-from-bottom-2">
                    <button 
                      onClick={() => handleDelete(entry.id)}
                      className="absolute top-3 right-3 p-1.5 text-text-secondary hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <span className="material-symbols-outlined text-lg">delete</span>
                    </button>

                    {/* Indicador de Nuevo (si es muy reciente) */}
                    {Date.now() - entry.timestamp < 10000 && (
                        <span className="absolute -top-1 -left-1 px-2 py-0.5 bg-green-500 text-black text-[9px] font-bold rounded-full animate-bounce">NUEVO</span>
                    )}

                    <div className="flex flex-wrap gap-2 mb-3">
                       {entry.tags.map((tag, i) => (
                         <span key={i} className="px-2 py-0.5 bg-purple-500/10 text-purple-300 rounded text-[10px] font-bold uppercase border border-purple-500/20">
                           {tag}
                         </span>
                       ))}
                    </div>

                    <h3 className="text-white font-bold text-lg mb-2 leading-tight pr-6">{entry.title}</h3>
                    <p className="text-text-secondary text-sm leading-relaxed line-clamp-3 mb-4">
                      {entry.content}
                    </p>

                    <div className="flex items-center gap-2 text-[10px] text-gray-500 font-mono uppercase border-t border-white/5 pt-3">
                       <span className="material-symbols-outlined text-sm">{entry.source.startsWith('http') ? 'public' : 'edit_note'}</span>
                       <span className="truncate max-w-[200px]">{entry.source}</span>
                       <span className="ml-auto flex items-center gap-1">
                           <span className="material-symbols-outlined text-[10px]">database</span>
                           Guardado
                       </span>
                    </div>
                 </div>
               ))}
             </div>
           )}
        </div>

      </div>
    </div>
  );
};

export default KnowledgeBase;

import { GoogleGenAI, Type, GenerateContentResponse, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext } from "./storage";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

// 1. Función para destilar conocimiento desde input del usuario (RAG Ingestion)
export const distillKnowledge = async (text: string, source: string) => {
  const ai = getAI();

  // Optimizamos el prompt para velocidad y manejo de YouTube
  const isYoutube = text.toLowerCase().includes('youtube.com') || text.toLowerCase().includes('youtu.be');
  const sourceContext = isYoutube ? 'VIDEO O CANAL DE YOUTUBE (TÉCNICO EN REPARACIÓN)' : source;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview', // Usamos Flash para mayor velocidad
    contents: `
    ERES UN ANALISTA DE CONOCIMIENTO TÉCNICO.
    FUENTE: ${sourceContext}
    URL/TEXTO: ${text}

    OBJETIVO: Extraer conocimientos fundamentales o casos específicos para una Base de Datos de Reparación.

    INSTRUCCIONES CLAVE:
    1. SI ES UN VIDEO ESPECÍFICO: Usa Google Search para encontrar el título y el problema resuelto. Resume: Síntoma -> Causa -> Solución.
    2. SI ES UN CANAL O PÁGINA GENERAL (Ej: "Canal de InfoSquad", "Curso de Electrónica"): NO intentes ver todos los videos. Describe la ESPECIALIDAD del técnico (ej: "Experto en Reballing", "Diagnóstico de Líneas Apple") y los FUNDAMENTOS que enseña (ej: "Uso de osciloscopio", "Secuencia de encendido").
    3. Si la información es densa, prioriza: Valores de referencia (Voltajes, Impedancias), Nombres de ICs problemáticos y Lógica de diagnóstico.

    SI NO PUEDES ACCEDER AL CONTENIDO:
    - No devuelvas un error fatal.
    - Genera un título basado en la URL.
    - En 'content', pon: "REVISIÓN MANUAL NECESARIA: No se pudo extraer el detalle técnico automáticamente. Edita esta tarjeta y pega el resumen clave."
    - En 'tags', pon: ["Pendiente de Revisión"].

    Genera un JSON estricto:
    - title: Título corto descriptivo.
    - tags: Lista de 3-5 palabras clave.
    - content: Resumen técnico denso (Máx 400 caracteres).
    `,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
            title: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            content: { type: Type.STRING }
        }
      }
    }
  });

  // Fallback por si la respuesta viene vacía o mal formada
  try {
      return JSON.parse(response.text || '{}');
  } catch (e) {
      return {
          title: "Error de Formato AI",
          tags: ["Error"],
          content: "La IA respondió pero no en formato JSON válido. Edita esta entrada manualmente."
      };
  }
};

// 2. Diagnóstico enriquecido con conocimiento local
export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const ai = getAI();

  // A. Historial de Reparaciones (Memoria Episódica)
  let repairHistoryContext = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) {
      repairHistoryContext = `HISTORIAL DEL TALLER: Se encontraron ${similar.length} casos previos. Anomalías: ${similar.map(s => s.pcbResult.detectedAnomalies.join(", ")).join("; ")}.`;
    }
  }

  // B. Base de Conocimientos (Memoria Semántica / Expert Knowledge)
  // Buscamos conocimiento relevante basado en el modelo y el problema actual
  const query = `${pcbModel || ''} ${currentIssue}`;
  const knowledgeBaseContext = await searchKnowledgeContext(query);

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [
      ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
      { role: 'user', parts: [{ text: currentIssue }] }
    ],
    config: {
      systemInstruction: `Eres Gusrepart AI, experto senior en microelectrónica.

      CONTEXTO DE APRENDIZAJE:
      ${repairHistoryContext}
      ${knowledgeBaseContext}

      Instrucciones:
      1. Si la 'Base de Conocimientos Expertos' tiene información sobre esta falla específica (ej: tips de YouTube guardados), ÚSALA como fuente principal y menciónalo ("Según tus notas guardadas...").
      2. Razona paso a paso como un ingeniero.
      `,
      thinkingConfig: { thinkingBudget: 32768 }
    }
  });
  return response.text;
};

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string): Promise<MeasurementPoint[]> => {
  const ai = getAI();

  // Inyectamos conocimiento también en el plan de medición
  const knowledgeContext = await searchKnowledgeContext(`${pcbResult.model} ${pcbResult.identifiedComponents.join(' ')}`);

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Análisis HW: ${JSON.stringify(pcbResult)}. Funcional: ${functionalAnalysis}.
    ${knowledgeContext ? `NOTA IMPORTANTE: El usuario tiene este conocimiento guardado sobre esta placa: ${knowledgeContext}. Si menciona voltajes o puntos específicos, inclúyelos.` : ''}
    Genera plan de medición JSON (4-6 puntos).`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            component: { type: Type.STRING },
            testPoint: { type: Type.STRING },
            mode: { type: Type.STRING },
            expectedValue: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["id", "component", "testPoint", "mode", "expectedValue", "description"]
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

export const getFinalVerdict = async (pcbResult: any, measurements: MeasurementPoint[]): Promise<string> => {
  const ai = getAI();
  const data = {
    board: pcbResult,
    measurements: measurements.map(m => ({
      ponto: m.component,
      esperado: m.expectedValue,
      medido: m.measuredValue,
      descripcion: m.description
    }))
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Resultados lab: ${JSON.stringify(data)}. Veredicto técnico preciso.`,
    config: { thinkingConfig: { thinkingBudget: 10000 } }
  });

  return response.text || "No se pudo generar un veredicto.";
};

export const enhancePCBImage = async (base64Image: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: 'Mejorar imagen PCB: nitidez, reducir ruido, resaltar texto ICs.' },
      ],
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No se pudo generar la imagen mejorada");
};

export const analyzePCBImage = async (base64Images: string[], userContext?: { model?: string, serial?: string, symptoms?: string }): Promise<any> => {
  const ai = getAI();

  const imageParts = base64Images.map(base64 => ({
    inlineData: { data: base64, mimeType: 'image/jpeg' }
  }));

  let prompt = "Analiza estas imágenes de una PCB.";
  let expertKnowledge = "";

  if (userContext) {
    // Buscamos si tenemos conocimientos previos sobre este modelo
    if (userContext.model) {
        expertKnowledge = await searchKnowledgeContext(userContext.model + " " + (userContext.symptoms || ""));
    }

    prompt += `\nIMPORTANTE - Contexto del Técnico:
    - Modelo: ${userContext.model || "Desconocido"}
    - Síntomas: ${userContext.symptoms || "N/A"}

    ${expertKnowledge}

    Instrucciones:
    1. Si la 'Base de Conocimientos Expertos' menciona componentes específicos que fallan en este modelo (ej: "Revisar capacitor C123"), búscalos prioritariamente en la imagen.
    2. Identifica anomalías visuales relacionadas con los síntomas.`;
  }

  prompt += `\nDevuelve JSON con: manufacturer, model, boardNumber, confidence, identifiedComponents, detectedAnomalies.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: [{ role: 'user', parts: [...imageParts, { text: prompt }] }],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          manufacturer: { type: Type.STRING },
          model: { type: Type.STRING },
          boardNumber: { type: Type.STRING },
          confidence: { type: Type.NUMBER },
          identifiedComponents: { type: Type.ARRAY, items: { type: Type.STRING } },
          detectedAnomalies: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["manufacturer", "model", "boardNumber", "confidence", "identifiedComponents", "detectedAnomalies"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

