export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (base64Audio) {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioData = decodeBase64(base64Audio);
    const buffer = await decodeRawPCM(audioData, ctx, 24000, 1);
    onAudioReady(buffer);
  }
};

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPCM(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / channels;
  const buffer = ctx.createBuffer(channels, frameCount, sampleRate);
  for (let channel = 0; channel < channels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * channels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { distillKnowledge } from '../services/gemini';
import { addKnowledgeEntry, getAllKnowledge, deleteKnowledgeEntry } from '../services/storage';
import { KnowledgeEntry } from '../types';

// Variable global (fuera del componente) para rastrear tareas activas aunque cambie la pantalla
let activeTasksCount = 0;

const KnowledgeBase: React.FC = () => {
  const [entries, setEntries] = useState<KnowledgeEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);

  // Estado para edición
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<{title: string, content: string, tags: string}>({ title: '', content: '', tags: '' });

  // Referencia para saber si el componente sigue montado
  const isMounted = useRef(true);

  // Form states
  const [inputContent, setInputContent] = useState("");
  const [inputType, setInputType] = useState<'url' | 'text'>('url');

  useEffect(() => {
    isMounted.current = true;
    loadKnowledge();

    // Auto-refresco suave
    const interval = setInterval(() => {
        if (activeTasksCount > 0 || !document.hidden) {
            // Solo si NO estamos editando para no sobrescribir el estado de edición
            if (!editingId) {
                loadKnowledge(true);
            }
        }
    }, 3000);

    if (activeTasksCount > 0) setProcessing(true);

    return () => { isMounted.current = false; clearInterval(interval); };
  }, [editingId]);

  const loadKnowledge = async (silent = false) => {
    if (!silent) setLoading(true);
    const data = await getAllKnowledge();
    const sorted = data.sort((a, b) => b.timestamp - a.timestamp);

    if (isMounted.current) {
        setEntries(prev => {
            if (prev.length !== sorted.length || (prev[0]?.id !== sorted[0]?.id)) {
                return sorted;
            }
            return prev;
        });
        if (!silent) setLoading(false);
        if (activeTasksCount === 0) setProcessing(false);
    }
  };

  const handleLearn = async () => {
    if (!inputContent.trim()) return;

    setProcessing(true);
    activeTasksCount++;

    const contentToProcess = inputContent;
    const typeToProcess = inputType;

    setInputContent("");

    (async () => {
        try {
            // IA intentará extraer fundamentos generales si es un canal
            const distilled = await distillKnowledge(
                contentToProcess, 
                typeToProcess === 'url' ? 'Link Externo' : 'Nota del Técnico'
            );

            const newEntry: KnowledgeEntry = {
                id: crypto.randomUUID(),
                title: distilled.title || "Procesando...",
                tags: distilled.tags || [],
                content: distilled.content || "Esperando datos...",
                source: typeToProcess === 'url' ? contentToProcess : 'Nota Manual',
                timestamp: Date.now()
            };

            await addKnowledgeEntry(newEntry);
            console.log("Conocimiento guardado en background:", newEntry.title);

        } catch (e) {
            console.error("Error en background task:", e);
        } finally {
            activeTasksCount--;
            if (isMounted.current) {
                if (activeTasksCount === 0) setProcessing(false);
                loadKnowledge(true);
            }
        }
    })();
  };

  const handleDelete = async (id: string) => {
    if (confirm("¿Olvidar este conocimiento?")) {
      await deleteKnowledgeEntry(id);
      await loadKnowledge();
    }
  };

  const startEditing = (entry: KnowledgeEntry) => {
      setEditingId(entry.id);
      setEditForm({
          title: entry.title,
          content: entry.content,
          tags: entry.tags.join(', ')
      });
  };

  const saveEditing = async (originalEntry: KnowledgeEntry) => {
      const updatedEntry: KnowledgeEntry = {
          ...originalEntry,
          title: editForm.title,
          content: editForm.content,
          tags: editForm.tags.split(',').map(t => t.trim()).filter(t => t.length > 0)
      };
      await addKnowledgeEntry(updatedEntry);
      setEditingId(null);
      await loadKnowledge(true);
  };

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark">
