export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (base64Audio) {
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const audioData = decodeBase64(base64Audio);
    const buffer = await decodeRawPCM(audioData, ctx, 24000, 1);
    onAudioReady(buffer);
  }
};

function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPCM(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / channels;
  const buffer = ctx.createBuffer(channels, frameCount, sampleRate);
  for (let channel = 0; channel < channels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * channels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { distillKnowledge } from '../services/gemini';
import { addKnowledgeEntry, getAllKnowledge, deleteKnowledgeEntry } from '../services/storage';
import { KnowledgeEntry } from '../types';
import ConfirmDialog from '../components/ConfirmDialog';

// Variable global para rastrear tareas activas
let activeTasksCount = 0;

const KnowledgeBase: React.FC = () => {
  const [entries, setEntries] = useState<KnowledgeEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [processing, setProcessing] = useState(false);

  // Estado para eliminación
  const [deleteId, setDeleteId] = useState<string | null>(null);

  // Estado para edición
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<{title: string, content: string, tags: string}>({ title: '', content: '', tags: '' });

  const isMounted = useRef(true);

  // Form states
  const [inputContent, setInputContent] = useState("");
  const [inputType, setInputType] = useState<'url' | 'text'>('url');

  useEffect(() => {
    isMounted.current = true;
    loadKnowledge();

    const interval = setInterval(() => {
        if (activeTasksCount > 0 || !document.hidden) {
            if (!editingId) {
                loadKnowledge(true);
            }
        }
    }, 3000);

    if (activeTasksCount > 0) setProcessing(true);

    return () => { isMounted.current = false; clearInterval(interval); };
  }, [editingId]);

  const loadKnowledge = async (silent = false) => {
    if (!silent) setLoading(true);
    const data = await getAllKnowledge();
    const sorted = data.sort((a, b) => b.timestamp - a.timestamp);

    if (isMounted.current) {
        setEntries(prev => {
            if (prev.length !== sorted.length || (prev[0]?.id !== sorted[0]?.id)) {
                return sorted;
            }
            return prev;
        });
        if (!silent) setLoading(false);
        if (activeTasksCount === 0) setProcessing(false);
    }
  };

  const handleLearn = async () => {
    if (!inputContent.trim()) return;

    setProcessing(true);
    activeTasksCount++;

    const contentToProcess = inputContent;
    const typeToProcess = inputType;

    setInputContent("");

    (async () => {
        try {
            const distilled = await distillKnowledge(
                contentToProcess, 
                typeToProcess === 'url' ? 'Link Externo' : 'Nota del Técnico'
            );

            const newEntry: KnowledgeEntry = {
                id: crypto.randomUUID(),
                title: distilled.title || "Procesando...",
                tags: distilled.tags || [],
                content: distilled.content || "Esperando datos...",
                source: typeToProcess === 'url' ? contentToProcess : 'Nota Manual',
                timestamp: Date.now()
            };

            await addKnowledgeEntry(newEntry);
        } catch (e) {
            console.error("Error en background task:", e);
        } finally {
            activeTasksCount--;
            if (isMounted.current) {
                if (activeTasksCount === 0) setProcessing(false);
                loadKnowledge(true);
            }
        }
    })();
  };

  const requestDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setDeleteId(id);
  };

  const confirmDelete = async () => {
    if (!deleteId) return;

    const idToDel = deleteId;
    setDeleteId(null); // Cerrar modal inmediatamente

    // Optimistic update
    setEntries(prev => prev.filter(entry => entry.id !== idToDel));

    try {
        await deleteKnowledgeEntry(idToDel);
        loadKnowledge(true);
    } catch (error) {
        alert("Error al eliminar");
        loadKnowledge(); 
    }
  };

  const startEditing = (entry: KnowledgeEntry) => {
      setEditingId(entry.id);
      setEditForm({
          title: entry.title,
          content: entry.content,
          tags: entry.tags.join(', ')
      });
  };

  const saveEditing = async (originalEntry: KnowledgeEntry) => {
      const updatedEntry: KnowledgeEntry = {
          ...originalEntry,
          title: editForm.title,
          content: editForm.content,
          tags: editForm.tags.split(',').map(t => t.trim()).filter(t => t.length > 0)
      };
      await addKnowledgeEntry(updatedEntry);
      setEditingId(null);
      await loadKnowledge(true);
  };

  return (
    <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-background-dark relative">
      <div className="max-w-6xl mx-auto flex flex-col gap-8">

        <div className="flex flex-col gap-2 border-b border-border-dark pb-6">
          <h1 className="text-4xl font-black text-white flex items-center gap-3">
             <span className="material-symbols-outlined text-purple-400 text-4xl">school</span>
             Entrenamiento de IA
          </h1>
          <p className="text-text-secondary text-lg">Alimenta la base de datos con canales de YouTube, foros y tus propios apuntes.</p>
        </div>

        {/* INPUT AREA */}
        <div className="bg-[#1a2332] border border-border-dark rounded-2xl p-6 shadow-xl animate-in fade-in slide-in-from-top-4 relative overflow-hidden">
           {processing && (
               <div className="absolute top-0 left-0 w-full h-1 bg-purple-900/50">
                   <div className="h-full bg-purple-500 animate-shimmer w-1/2"></div>
               </div>
           )}

           <div className="flex gap-4 mb-4">
              <button 
                onClick={() => setInputType('url')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${inputType === 'url' ? 'bg-purple-600 text-white' : 'bg-background-dark text-text-secondary hover:text-white'}`}
              >
                <span className="material-symbols-outlined">link</span> Video / Canal / Web
              </button>
              <button 
                onClick={() => setInputType('text')}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${inputType === 'text' ? 'bg-purple-600 text-white' : 'bg-background-dark text-text-secondary hover:text-white'}`}
              >
                <span className="material-symbols-outlined">edit_note</span> Nota Rápida
              </button>
           </div>

           <div className="flex flex-col md:flex-row gap-4">
              <input 
                value={inputContent}
                onChange={e => setInputContent(e.target.value)}
                placeholder={inputType === 'url' ? "Ej: youtube.com/watch?v=..." : "Ej: Tip: Corto en línea principal..."}
                className="flex-1 bg-black/40 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-purple-500 outline-none transition-colors"
              />
              <button 
                onClick={handleLearn}
                disabled={processing && inputContent === ""} 
                className="px-8 py-3 bg-purple-600 hover:bg-purple-700 text-white rounded-xl font-bold transition-all shadow-lg shadow-purple-500/20 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
              >
                {processing ? <span className="material-symbols-outlined animate-spin">sync</span> : <span className="material-symbols-outlined">auto_awesome</span>}
                <span>{processing ? 'Encolar' : 'Procesar'}</span>
              </button>
           </div>

           <div className="flex justify-between items-center mt-3">
                <p className="text-xs text-text-secondary flex items-center gap-1">
                    <span className="material-symbols-outlined text-sm">info</span>
                    {inputType === 'url' ? 'Extrae fundamentos de videos o artículos técnicos.' : 'Guarda tus propias experiencias.'}
                </p>
                {processing && (
                    <p className="text-xs text-purple-400 font-bold animate-pulse">
                        Analizando en segundo plano...
                    </p>
                )}
           </div>
        </div>

        {/* LISTA DE CONOCIMIENTOS */}
        <div>
           <div className="flex items-center justify-between mb-6">
               <h2 className="text-xl font-bold text-white flex items-center gap-2">
                 <span className="material-symbols-outlined text-purple-400">library_books</span>
                 Conocimientos ({entries.length})
               </h2>
               <button onClick={() => loadKnowledge()} className="p-2 hover:bg-white/5 rounded-lg text-text-secondary hover:text-white transition-colors" title="Refrescar lista">
                   <span className="material-symbols-outlined">refresh</span>
               </button>
           </div>

           {loading && entries.length === 0 ? (
             <div className="py-20 text-center text-text-secondary animate-pulse">Cargando datos...</div>
           ) : entries.length === 0 ? (
             <div className="py-20 text-center border-2 border-dashed border-border-dark rounded-3xl opacity-30">
               <span className="material-symbols-outlined text-6xl mb-4">psychology_alt</span>
               <p className="text-lg font-bold">Base de datos vacía.</p>
               <p className="text-sm">La IA necesita aprender los fundamentos primero.</p>
             </div>
           ) : (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {entries.map(entry => (
                 <div key={entry.id} className={`bg-surface-dark border ${editingId === entry.id ? 'border-primary ring-1 ring-primary' : 'border-border-dark'} rounded-xl p-5 hover:border-purple-500/50 transition-all group relative animate-in fade-in slide-in-from-bottom-2`}>

                    {editingId === entry.id ? (
                        <div className="flex flex-col gap-3">
                            <input 
                                value={editForm.title}
                                onChange={e => setEditForm({...editForm, title: e.target.value})}
                                className="bg-black/40 border border-border-dark rounded px-2 py-1 text-white font-bold"
                                placeholder="Título"
                            />
                            <textarea 
                                value={editForm.content}
                                onChange={e => setEditForm({...editForm, content: e.target.value})}
                                className="bg-black/40 border border-border-dark rounded px-2 py-1 text-white text-sm min-h-[100px]"
                                placeholder="Contenido técnico..."
                            />
                            <input 
                                value={editForm.tags}
                                onChange={e => setEditForm({...editForm, tags: e.target.value})}
                                className="bg-black/40 border border-border-dark rounded px-2 py-1 text-text-secondary text-xs"
                                placeholder="Tags separados por coma"
                            />
                            <div className="flex gap-2 justify-end mt-2">
                                <button onClick={() => setEditingId(null)} className="px-3 py-1 bg-gray-700 rounded text-xs">Cancelar</button>
                                <button onClick={() => saveEditing(entry)} className="px-3 py-1 bg-primary text-white rounded text-xs font-bold">Guardar Cambios</button>
                            </div>
                        </div>
                    ) : (
                        <>
                            {/* BOTONES DE ACCIÓN FLOTANTES CON Z-INDEX ALTO */}
                            <div className="absolute top-3 right-3 flex gap-1 z-20">
                                <button 
                                onClick={() => startEditing(entry)}
                                className="p-1.5 text-text-secondary bg-[#1a2332] hover:text-white hover:bg-white/10 rounded-lg transition-colors opacity-0 group-hover:opacity-100 shadow-sm border border-transparent hover:border-white/10"
                                title="Corregir o Editar"
                                >
                                <span className="material-symbols-outlined text-lg">edit</span>
                                </button>
                                <button 
                                onClick={(e) => requestDelete(e, entry.id)}
                                className="p-1.5 text-text-secondary bg-[#1a2332] hover:text-red-500 hover:bg-red-500/10 rounded-lg transition-colors opacity-0 group-hover:opacity-100 shadow-sm border border-transparent hover:border-red-500/20"
                                title="Eliminar Definitivamente"
                                >
                                <span className="material-symbols-outlined text-lg">delete</span>
                                </button>
                            </div>

                            <div className="flex flex-wrap gap-2 mb-3 pr-16">
                            {entry.tags.map((tag, i) => (
                                <span key={i} className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${tag.includes('Revisión') || tag.includes('Error') ? 'bg-red-500/10 text-red-400 border-red-500/20' : 'bg-purple-500/10 text-purple-300 border-purple-500/20'}`}>
                                {tag}
                                </span>
                            ))}
                            </div>

                            <h3 className="text-white font-bold text-lg mb-2 leading-tight pr-8">{entry.title}</h3>
                            <p className="text-text-secondary text-sm leading-relaxed line-clamp-4 mb-4 whitespace-pre-wrap">
                            {entry.content}
                            </p>

                            <div className="flex items-center gap-2 text-[10px] text-gray-500 font-mono uppercase border-t border-white/5 pt-3">
                            <span className="material-symbols-outlined text-sm">{entry.source.startsWith('http') ? 'public' : 'edit_note'}</span>
                            <span className="truncate max-w-[200px]">{entry.source}</span>
                            </div>
                        </>
                    )}
                 </div>
               ))}
             </div>
           )}
        </div>

      </div>

      <ConfirmDialog 
        isOpen={deleteId !== null}
        title="Eliminar Conocimiento"
        message="Esta información se perderá permanentemente y no podrá ser usada para futuros diagnósticos. ¿Estás seguro?"
        confirmText="Sí, Eliminar"
        isDestructive={true}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteId(null)}
      />
    </div>
  );
};

export default KnowledgeBase;

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis, enhancePCBImage } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);
  const [isEditing, setIsEditing] = useState(false);

  // Datos de recepción manuales (Input del técnico)
  const [receptionData, setReceptionData] = useState({
      model: '',
      serial: '',
      symptoms: ''
  });

  // ESTADO INICIAL
  const [images, setImages] = useState<string[]>(
    (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""]
  );

  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  useEffect(() => {
    const targetImages = (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""];
    if (JSON.stringify(targetImages) !== JSON.stringify(images)) {
      setImages(targetImages);
    }
    // Sincronizar RESULT y DATOS DE RECEPCIÓN cuando carga una reparación guardada
    if (persistedResult && JSON.stringify(persistedResult) !== JSON.stringify(result)) {
      setResult(persistedResult);
      // Pre-rellenar los inputs con lo que ya sabemos de la reparación guardada
      setReceptionData(prev => ({
          ...prev,
          model: persistedResult.model || prev.model,
          serial: persistedResult.boardNumber || prev.serial, // Asumimos boardNumber como serial si no hay serial
      }));
    }
  }, [persistedImages, persistedResult]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result?.model]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot] || isEnhancing !== null) return;
    setIsEnhancing(slot);
    try {
      const enhanced = await enhancePCBImage(images[slot].split(',')[1]);
      const newImages = [...images];
      newImages[slot] = enhanced;
      setImages(newImages);
      onUpdate(newImages, result || undefined);
    } catch (err) {
      alert("Error al mejorar imagen");
    } finally {
      setIsEnhancing(null);
    }
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);
    onUpdate(newImages, result || undefined);
  };

  // FLUJO COMPLETO: Análisis Visual -> Búsqueda Datos -> Análisis Funcional
  const runVisualAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) {
        alert("Por favor, sube al menos una imagen de la placa para confirmar visualmente el diagnóstico.");
        return;
    }

    setIsAnalyzing(true);
    setStatus("Integrando síntomas y analizando placa...");

    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);

      // PREPARAR CONTEXTO:
      // Si el usuario no ha escrito nada nuevo, pero ya tenemos un resultado guardado, usamos ese resultado como contexto.
      const contextModel = receptionData.model || result?.model || "";
      const contextSerial = receptionData.serial || result?.boardNumber || "";
      const contextSymptoms = receptionData.symptoms || "";

      // 1. ANÁLISIS VISUAL CON CONTEXTO INTELIGENTE
      const analysis = await analyzePCBImage(pureBase64s, {
          model: contextModel,
          serial: contextSerial,
          symptoms: contextSymptoms
      });

      setResult(analysis);

      // 2. AUTOMATIZACIÓN DE BÚSQUEDA Y FUNCIONALIDAD
      if (analysis.model || analysis.boardNumber) {
          setStatus("Localizando esquemas y generando análisis funcional...");
          const query = `${analysis.manufacturer || ''} ${analysis.model || ''} ${analysis.boardNumber || ''}`;

          const [schematics, functional] = await Promise.all([
            searchSchematics(query),
            getFunctionalAnalysis(analysis.identifiedComponents || [], analysis.boardNumber || analysis.model || '')
          ]);

          // Guardamos todo de una vez
          onUpdate(images, analysis, schematics, functional);
      } else {
          // Si no detectó modelo, guardamos solo lo visual
          onUpdate(images, analysis);
      }

    } catch (error) {
      console.error(error);
      setStatus("Hubo un error en el proceso de análisis.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    const newResult = result ? { ...result, [field]: value } : { 
      manufacturer: field === 'manufacturer' ? value : '', 
      model: field === 'model' ? value : '', 
      boardNumber: field === 'boardNumber' ? value : '', 
      confidence: 1, identifiedComponents: [], detectedAnomalies: [] 
    };
    setResult(newResult);
    // Nota: Al editar manualmente no relanzamos la búsqueda automática para no sobreescribir,
    // se asume que la edición es cosmética o corrección menor.
    onUpdate(images, newResult);
  };

  // Handlers UI
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setScale(prev => Math.min(Math.max(1, prev + (e.deltaY > 0 ? -0.2 : 0.2)), 5));
  };
  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
          style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
        >
          <div className="absolute top-6 right-6 z-10">
            <button onClick={() => setZoomImage(null)} className="p-3 bg-red-500 rounded-full text-white shadow-xl">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <div style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` }}>
            <img src={zoomImage} className="max-w-none h-[85vh] object-contain select-none" draggable={false} />
          </div>
        </div>
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black text-white">Recepción y Análisis</h1>
            <p className="text-text-secondary">Paso 1: Introduce los datos del equipo y sube imágenes. La IA realizará el diagnóstico completo.</p>
          </div>

          {/* PANEL DE DATOS DE RECEPCIÓN */}
          <div className="bg-[#111722] border border-border-dark rounded-2xl p-6 mb-8 shadow-lg">
              <h2 className="text-white font-bold text-lg mb-4 flex items-center gap-2">
                  <span className="material-symbols-outlined text-primary">assignment</span>
                  Datos de Entrada
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                      <label className="text-xs text-text-secondary uppercase font-bold mb-1 block">Modelo del Equipo</label>
                      <input 
                        value={receptionData.model}
                        onChange={(e) => setReceptionData({...receptionData, model: e.target.value})}
                        placeholder="Ej: HP Pavilion 15-cw" 
                        className="w-full bg-black/30 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                      />
                  </div>
                  <div>
                      <label className="text-xs text-text-secondary uppercase font-bold mb-1 block">Número de Serie / ID</label>
                      <input 
                        value={receptionData.serial}
                        onChange={(e) => setReceptionData({...receptionData, serial: e.target.value})}
                        placeholder="Ej: 5CD84..." 
                        className="w-full bg-black/30 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-primary outline-none font-mono"
                      />
                  </div>
                  <div className="md:col-span-2">
                      <label className="text-xs text-text-secondary uppercase font-bold mb-1 block">Síntomas de Avería / Notas del Cliente</label>
                      <textarea 
                        value={receptionData.symptoms}
                        onChange={(e) => setReceptionData({...receptionData, symptoms: e.target.value})}
                        placeholder="Ej: No enciende, LED de carga parpadea, se mojó hace una semana..." 
                        className="w-full bg-black/30 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-primary outline-none h-20 resize-none"
                      />
                  </div>
              </div>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 min-h-[300px]">
            {[0, 1].map((slot) => (
