const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

// --- NUEVO: Procesamiento de PDFs (Esquemas/Datasheets) ---
export const processTechnicalPDF = async (base64Pdf: string) => {
  const ai = getAI();

  // Enviamos el PDF directamente a Gemini 1.5 Flash/Pro (soporta hasta 1M tokens)
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      {
        inlineData: {
          mimeType: 'application/pdf',
          data: base64Pdf
        }
      },
      {
        text: `ACTÚA COMO INGENIERO SENIOR DE HARDWARE.
        Analiza este documento PDF (puede ser un Esquema Eléctrico, Boardview o Datasheet).

        OBJETIVO: Extraer información técnica vital para reparaciones y guardarla en la base de datos.

        SI ES UN ESQUEMA/BOARDVIEW DE UNA PLACA:
        - Extrae: Marca, Modelo, Plataforma (Board Number).
        - Resume: Rails de voltaje principales, secuencia de encendido (si está), y notas de revisión.

        SI ES UN DATASHEET DE COMPONENTE:
        - Extrae: Número de parte, Descripción, Pinout crítico, Voltajes máximos/típicos.

        SI ES UN MANUAL DE SERVICIO:
        - Extrae: Lista de fallas comunes y soluciones.

        Salida JSON estrictamente:
        {
          "title": "Ej: Esquema MacBook A1466 820-00165",
          "tags": ["Marca", "Modelo", "TipoDocumento", "ComponentesClave"],
          "content": "Resumen técnico denso..."
        }`
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
            title: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            content: { type: Type.STRING }
        },
        required: ["title", "tags", "content"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

// 1. Función para destilar conocimiento desde input del usuario (RAG Ingestion)
export const distillKnowledge = async (text: string, source: string) => {
  const ai = getAI();

  const isYoutube = text.toLowerCase().includes('youtube.com') || text.toLowerCase().includes('youtu.be');
  const sourceContext = isYoutube ? 'VIDEO YOUTUBE' : 'PÁGINA WEB / TEXTO';

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `
    ACTÚA COMO UN ANALISTA TÉCNICO EXPERTO EN REPARACIONES.

    ENTRADA (${sourceContext}): ${text}

    OBJETIVO: Generar una ficha de conocimiento para una base de datos de taller.

    INSTRUCCIONES DE PROCESAMIENTO:
    1. USA SIEMPRE LA HERRAMIENTA 'googleSearch' para investigar la URL proporcionada. Busca el título exacto y el resumen del contenido.

    2. SI ES UNA GUÍA (Ej: iFixit, Foros):
       - Extrae: Dispositivo, Problema y Solución/Pasos Clave.
       - Si es un paso a paso largo, resúmelo en los puntos críticos de precaución o medición.

    3. SI ES YOUTUBE:
       - Busca información sobre el video (título, descripción) en Google.
       - Extrae la falla y la solución propuesta por el técnico.

    4. SI LA BÚSQUEDA FALLA O NO PUEDES ACCEDER:
       - ¡NO DEVUELVAS ERROR!
       - INFIERE el contenido basándote únicamente en las palabras de la URL (Ej: si la URL es '.../iphone-7-audio-ic...', asume que trata sobre la falla de audio del iPhone 7).
       - En 'content', indica: "[Inferido por URL] Posible guía sobre..." seguido de tu deducción.

    FORMATO JSON OBLIGATORIO (No dejes campos vacíos):
    {
      "title": "Título técnico claro (Ej: Cambio Batería iPhone 11)",
      "tags": ["Marca", "Modelo", "Componente", "Falla"],
      "content": "Resumen denso de la información técnica (máx 400 caracteres)."
    }
    `,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
            title: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } },
            content: { type: Type.STRING }
        },
        required: ["title", "tags", "content"]
      }
    }
  });

  // Fallback robusto
  try {
      const result = JSON.parse(response.text || '{}');
      // Verificación extra: si devuelve campos vacíos, poner valores por defecto
      if (!result.content || result.content.trim() === "") {
          result.content = "No se pudo extraer detalle automáticamente. Edita esta tarjeta.";
      }
      if (!result.title || result.title.trim() === "") {
          result.title = "Nuevo Conocimiento (Sin Título)";
      }
      return result;
  } catch (e) {
      return {
          title: "Error de Procesamiento",
          tags: ["Revisar"],
          content: "La IA no generó un JSON válido. Por favor edita esta entrada manualmente con la información correcta."
      };
  }
};

// 2. Diagnóstico enriquecido con conocimiento local
export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const ai = getAI();

  // A. Historial de Reparaciones (Memoria Episódica)
  let repairHistoryContext = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) {
      repairHistoryContext = `HISTORIAL DEL TALLER: Se encontraron ${similar.length} casos previos. Anomalías: ${similar.map(s => s.pcbResult.detectedAnomalies.join(", ")).join("; ")}.`;
    }
  }

  // B. Base de Conocimientos (Memoria Semántica / Expert Knowledge)
  // Buscamos conocimiento relevante basado en el modelo y el problema actual
  const query = `${pcbModel || ''} ${currentIssue}`;
  const knowledgeBaseContext = await searchKnowledgeContext(query);

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: [
      ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
      { role: 'user', parts: [{ text: currentIssue }] }
    ],
    config: {
      systemInstruction: `Eres Gusrepart AI, experto senior en microelectrónica.

      CONTEXTO DE APRENDIZAJE:
      ${repairHistoryContext}
      ${knowledgeBaseContext}

      Instrucciones:
      1. Si la 'Base de Conocimientos Expertos' tiene información sobre esta falla específica (ej: tips de YouTube guardados), ÚSALA como fuente principal y menciónalo ("Según tus notas guardadas...").
      2. Razona paso a paso como un ingeniero.
      `,
      thinkingConfig: { thinkingBudget: 32768 }
    }
  });
  return response.text;
};

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string, base64Image?: string): Promise<MeasurementPoint[]> => {
  const ai = getAI();

  // Inyectamos conocimiento también en el plan de medición
  const knowledgeContext = await searchKnowledgeContext(`${pcbResult.model} ${pcbResult.identifiedComponents.join(' ')}`);

  const promptText = `
    Análisis HW: ${JSON.stringify(pcbResult)}. 
    Funcional: ${functionalAnalysis}.
    ${knowledgeContext ? `NOTA IMPORTANTE: El usuario tiene este conocimiento guardado sobre esta placa: ${knowledgeContext}. Si menciona voltajes o puntos específicos, inclúyelos.` : ''}

    TAREA: Genera un plan de medición JSON (4-6 puntos críticos).

    VISIÓN COMPUTADORA:
    Observa la imagen proporcionada. Intenta LOCALIZAR VISUALMENTE los componentes que pides medir.
    Devuelve 'coordinates' como [ymin, xmin, ymax, xmax] en porcentaje (0 a 100) para dibujar un recuadro sobre el componente en la imagen.
    Si no puedes ubicarlo con certeza, devuelve coordinates: [].
  `;

  const contents = [];
  if (base64Image) {
      contents.push({ inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } });
  }
  contents.push({ text: promptText });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview', // Usamos el modelo Pro para mejor razonamiento visual
    contents: contents,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            component: { type: Type.STRING },
            testPoint: { type: Type.STRING },
            mode: { type: Type.STRING },
            expectedValue: { type: Type.STRING },
            description: { type: Type.STRING },
            coordinates: { 
                type: Type.ARRAY, 
                items: { type: Type.NUMBER },
                description: "Bounding box [ymin, xmin, ymax, xmax] en % (0-100)"
            }
          },
          required: ["id", "component", "testPoint", "mode", "expectedValue", "description"]
        }
      }
    }
  });

  return JSON.parse(response.text || '[]');
};

