// Helper para extraer JSON de respuestas "sucias" de modelos locales
const extractJSON = (text: string): any => {
    try {
        // Intento directo
        return JSON.parse(text);
    } catch (e) {
        // Buscar el primer { y el último }
        const start = text.indexOf('{');
        const end = text.lastIndexOf('}');
        if (start !== -1 && end !== -1) {
            try {
                return JSON.parse(text.substring(start, end + 1));
            } catch (e2) {
                console.error("JSON parsing failed", text);
                return {};
            }
        }
        return {};
    }
};

export const ollamaGenerate = async (prompt: string, images?: string[], system?: string, formatJSON: boolean = false): Promise<string> => {
    const settings = getSettings();
    const model = images && images.length > 0 ? settings.ollamaVisionModel : settings.ollamaTextModel;
    const url = `${settings.ollamaUrl.replace(/\/$/, '')}/api/generate`;

    // Para modelos de vision (LLaVA), el sistema suele ir en el prompt o ignorarse
    const fullPrompt = system ? `${system}\n\nUser: ${prompt}` : prompt;

    const payload: any = {
        model: model,
        prompt: fullPrompt,
        stream: false,
        options: {
            temperature: 0.2, // Baja temperatura para análisis técnicos
            num_ctx: 4096     // Contexto más amplio
        }
    };

    if (images && images.length > 0) {
        // Ollama espera base64 crudo
        payload.images = images.map(img => img.includes(',') ? img.split(',')[1] : img);
    }

    if (formatJSON) {
        payload.format = "json";
    }

    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            throw new Error(`Ollama Error: ${response.statusText}. Asegúrate de ejecutar 'ollama serve' y configurar CORS.`);
        }

        const data = await response.json();
        return data.response;
    } catch (error) {
        console.error("Ollama connection failed:", error);
        throw new Error("No se pudo conectar con Ollama. Verifica que se esté ejecutando en tu PC.");
    }
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext, getSettings } from "./storage";
import { ollamaGenerate } from "./ollama";

// --- GESTIÓN DE PROVEEDOR ---

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    // Si estamos en modo Gemini y no hay clave, es un error.
    // Pero si el usuario seleccionó Ollama, no necesitamos clave.
    const settings = getSettings();
    if (settings.aiProvider === 'gemini') {
        alert("¡ERROR CRÍTICO! No se detectó la API KEY de Gemini.");
        throw new Error("API Key missing");
    }
  }
  return new GoogleGenAI({ apiKey: apiKey || 'dummy' });
};

// --- IMPLEMENTACIONES HÍBRIDAS ---

// Esta función decide si usar Gemini u Ollama internamente
const smartGenerate = async (
    prompt: string, 
    options: {
        images?: string[], 
        jsonMode?: boolean,
        system?: string,
        modelGemini?: string
    }
): Promise<string> => {
    const settings = getSettings();

    // RUTA OLLAMA
    if (settings.aiProvider === 'ollama') {
        return await ollamaGenerate(prompt, options.images, options.system, options.jsonMode);
    }

    // RUTA GEMINI
    const ai = getAI();

    // Configuración especial para Imágenes
    if (options.images && options.images.length > 0) {
        const imageParts = options.images.map(img => ({
            inlineData: { data: img.split(',')[1], mimeType: 'image/jpeg' }
        }));

        const response = await ai.models.generateContent({
            model: options.modelGemini || 'gemini-3-pro-preview',
            contents: [
                { role: 'user', parts: [...imageParts, { text: prompt }] }
            ],
            config: options.jsonMode ? { responseMimeType: "application/json" } : {}
        });
        return response.text || "";
    }

    // Texto normal
    const response = await ai.models.generateContent({
        model: options.modelGemini || 'gemini-3-flash-preview',
        contents: prompt,
        config: {
            systemInstruction: options.system,
            responseMimeType: options.jsonMode ? "application/json" : undefined,
            tools: options.modelGemini?.includes('flash') ? [{googleSearch: {}}] : undefined // Solo Gemini tiene Google Search
        }
    });
    return response.text || "";
};

