export const exportDatabase = async (): Promise<string> => {
  const history = await getAllRepairs();
  const knowledge = await getAllKnowledge();
  return JSON.stringify({ history, knowledge }, null, 2);
};

export const importDatabase = async (jsonContent: string): Promise<boolean> => {
  try {
    const data = JSON.parse(jsonContent);
    const historyData = Array.isArray(data) ? data : data.history || [];
    const knowledgeData = data.knowledge || [];

    // NOTA IMPORTANTE: Importar un backup NO sobrescribe la configuración (Settings)
    // Esto evita que una clave API antigua o inválida reemplace la actual.

    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onsuccess = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            const transaction = db.transaction([HISTORY_STORE, KNOWLEDGE_STORE], 'readwrite');

            const historyStore = transaction.objectStore(HISTORY_STORE);
            historyData.forEach((item: any) => { if (item.timestamp) historyStore.put(item); });

            const knowledgeStore = transaction.objectStore(KNOWLEDGE_STORE);
            knowledgeData.forEach((item: any) => { if (item.id) knowledgeStore.put(item); });

            transaction.oncomplete = () => { db.close(); resolve(true); };
            transaction.onerror = () => { db.close(); reject(false); };
        };
        request.onerror = () => reject(false);
    });
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import { getSettings } from "./storage";

export const ollamaGenerate = async (prompt: string, images?: string[], system?: string, formatJSON: boolean = false): Promise<string> => {
    const settings = getSettings();
    const model = images && images.length > 0 ? settings.ollamaVisionModel : settings.ollamaTextModel;
    const baseUrl = settings.ollamaUrl.replace(/\/$/, '');
    const url = `${baseUrl}/api/generate`;

    const fullPrompt = system ? `${system}\n\nUser: ${prompt}` : prompt;

    const payload: any = {
        model: model,
        prompt: fullPrompt,
        stream: false,
        options: { temperature: 0.2, num_ctx: 4096 }
    };

    if (images && images.length > 0) {
        payload.images = images.map(img => img.includes(',') ? img.split(',')[1] : img);
    }
    if (formatJSON) payload.format = "json";

    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (!response.ok) throw new Error(`Ollama Error: ${response.statusText}`);
        const data = await response.json();
        return data.response;
    } catch (error) {
        console.error("Ollama connection failed:", error);
        throw new Error("No se pudo conectar con Ollama. Verifica la URL en configuración.");
    }
};

