export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const settings = getSettings();

  let context = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) context += `HISTORIAL TALLER: ${similar.length} casos previos. `;
  }
  const kb = await searchKnowledgeContext(`${pcbModel || ''} ${currentIssue}`);

  const system = `Eres Gusrepart AI, experto senior en microelectrónica.
  CONTEXTO: ${context} ${kb}
  Razona paso a paso. Sé breve y técnico.`;

  if (settings.aiProvider === 'gemini') {
      const ai = getAI();
      const modelName = settings.geminiModel || 'gemini-2.0-flash';
      // CORRECCIÓN CRÍTICA: Solo activar 'thinking' si el modelo es v3 o v2.5.
      // Si usas una key nueva en un modelo standard, esto fallaba.
      const useThinking = modelName.includes('gemini-3');

      const response = await ai.models.generateContent({
        model: modelName,
        contents: [
            ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
            { role: 'user', parts: [{ text: currentIssue }] }
        ],
        config: { 
            systemInstruction: system,
            thinkingConfig: useThinking ? { thinkingBudget: 1024 } : undefined 
        }
      });
      return response.text;
  } else {
      const fullPrompt = `${system}\n\nChat:\n${history.map(h => h.content).join('\n')}\nUser: ${currentIssue}`;
      return await smartGenerate(fullPrompt, {});
  }
};

