import { GoogleGenAI, Type, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext, getSettings } from "./storage";
import { ollamaGenerate } from "./ollama";

// --- GESTIÓN DINÁMICA DE API KEY Y MODELO ---

const getAI = () => {
  const settings = getSettings();
  const apiKey = (settings.geminiApiKey && settings.geminiApiKey.trim() !== '') 
                 ? settings.geminiApiKey 
                 : process.env.API_KEY;

  if (!apiKey && settings.aiProvider === 'gemini') {
    alert("¡ERROR DE CREDENCIALES!\nNo se ha detectado ninguna API Key.\n\nVe a Configuración e introduce tu clave de Google AI Studio.");
    throw new Error("API Key missing");
  }
  return new GoogleGenAI({ apiKey: apiKey || 'dummy' });
};

// --- CEREBRO HÍBRIDO CON FALLBACK AUTOMÁTICO ---
const smartGenerate = async (
    prompt: string, 
    options: {
        images?: string[], 
        jsonMode?: boolean,
        system?: string,
        modelGemini?: string
    }
): Promise<string> => {
    const settings = getSettings();

    // 1. MODO LOCAL (OLLAMA)
    if (settings.aiProvider === 'ollama') {
        return await ollamaGenerate(prompt, options.images, options.system, options.jsonMode);
    }

    // 2. MODO NUBE (GEMINI)
    const ai = getAI();
    let targetModel = options.modelGemini || settings.geminiModel || 'gemini-2.0-flash';

    // Función auxiliar para realizar la llamada
    const executeCall = async (model: string) => {
        // Solo habilitamos thinking para los modelos serie 3 que lo soportan
        const useThinking = model.includes('gemini-3');
        const thinkingBudget = useThinking ? 2048 : undefined;

        if (options.images && options.images.length > 0) {
            const imageParts = options.images.map(img => ({
                inlineData: { data: img.split(',')[1], mimeType: 'image/jpeg' }
            }));

            const response = await ai.models.generateContent({
                model: model,
                contents: [
                    { role: 'user', parts: [...imageParts, { text: prompt }] }
                ],
                config: options.jsonMode ? { responseMimeType: "application/json" } : {}
            });
            return response.text || "";
        }

        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
            config: {
                systemInstruction: options.system,
                responseMimeType: options.jsonMode ? "application/json" : undefined,
                tools: useThinking ? [] : [{googleSearch: {}}], // Search tool a veces choca con thinking models
                thinkingConfig: thinkingBudget ? { thinkingBudget } : undefined
            }
        });
        return response.text || "";
    };

    try {
        return await executeCall(targetModel);
    } catch (error: any) {
        // FALLBACK SYSTEM: Si falla el modelo elegido (ej: 1.5 Pro por 404), intentamos con el 2.0 Flash
        if (targetModel !== 'gemini-2.0-flash') {
            console.warn(`Modelo ${targetModel} falló (${error.message}). Reintentando con Gemini 2.0 Flash...`);
            try {
                return await executeCall('gemini-2.0-flash');
            } catch (fallbackError) {
                console.error("Fallback falló también:", fallbackError);
                throw error; // Lanzamos el error original si ambos fallan
            }
        }
        throw error;
    }
};

