export const processTechnicalPDF = async (base64Pdf: string) => {
  const settings = getSettings();
  if (settings.aiProvider === 'ollama') {
      alert("El análisis de PDF requiere Gemini (Nube).");
      throw new Error("Feature not supported in Ollama");
  }

  const ai = getAI();
  const modelName = 'gemini-2.0-flash'; // Forzamos Flash 2.0 para PDFs por su gran ventana de contexto

  const response = await ai.models.generateContent({
    model: modelName,
    contents: [
      { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
      { text: `Extrae info técnica en JSON: { "title": "...", "tags": [...], "content": "..." }` }
    ],
    config: { responseMimeType: "application/json" }
  });

  return JSON.parse(response.text || '{}');
};

export const distillKnowledge = async (text: string, source: string) => {
    const prompt = `ENTRADA (${source}): ${text}
    OBJETIVO: Generar ficha de conocimiento para taller.
    FORMATO JSON: { "title": "...", "tags": [...], "content": "..." }`;

    const res = await smartGenerate(prompt, { jsonMode: true });
    try { return JSON.parse(res); } catch { return { title: "Error", tags: [], content: "Error parseando JSON." }; }
};

export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  const settings = getSettings();

  let context = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) context += `HISTORIAL TALLER: ${similar.length} casos previos. `;
  }
  const kb = await searchKnowledgeContext(`${pcbModel || ''} ${currentIssue}`);

  const system = `Eres Gusrepart AI, experto senior en microelectrónica.
  CONTEXTO: ${context} ${kb}
  Razona paso a paso. Sé breve y técnico.`;

  // Construimos el prompt completo para pasarlo a smartGenerate que maneja el fallback
  const chatHistory = history.map(h => `${h.role === 'user' ? 'Técnico' : 'AI'}: ${h.content}`).join('\n');
  const fullPrompt = `Chat Histórico:\n${chatHistory}\n\nNueva Consulta Técnico: ${currentIssue}`;

  return await smartGenerate(fullPrompt, { system });
};

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string, base64Image?: string): Promise<MeasurementPoint[]> => {
  const knowledgeContext = await searchKnowledgeContext(`${pcbResult.model} ${pcbResult.identifiedComponents.join(' ')}`);

  const prompt = `
    Placa: ${pcbResult.model}. Componentes: ${pcbResult.identifiedComponents}.
    Análisis Funcional: ${functionalAnalysis}.
    ${knowledgeContext ? `CONOCIMIENTO PREVIO: ${knowledgeContext}` : ''}

    Genera un plan de medición (4-6 puntos críticos).
    Si ves la imagen, intenta estimar coordenadas [ymin, xmin, ymax, xmax] 0-100.
    FORMATO JSON Array de MeasurementPoint.
  `;

  const res = await smartGenerate(prompt, { 
      images: base64Image ? [base64Image] : undefined,
      jsonMode: true
  });

  try { return JSON.parse(res); } catch { return []; }
};

