  CONTEXTO: Modelo: ${userContext?.model || "?"}, Síntomas: ${userContext?.symptoms || "?"}.
  ${expertKnowledge}

  Devuelve JSON: { manufacturer, model, boardNumber, confidence, identifiedComponents, detectedAnomalies }`;

