export const enhancePCBImage = async (base64Image: string): Promise<string> => {
   try {
       const ai = getAI();
       const response = await ai.models.generateContent({
            model: 'gemini-2.0-flash', // Flash 2.0 maneja imágenes mejor que 1.5 en general
            contents: {
            parts: [
                { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
                { text: 'Mejorar nitidez y contraste para leer serigrafía de componentes.' },
            ],
            },
        });

        // No todas las respuestas devuelven imagen mejorada directamente, a veces describen
        // Esta función es experimental en la API estándar.
        const candidate = response.candidates?.[0];
        if (candidate?.content?.parts) {
            for (const part of candidate.content.parts) {
                if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
            }
        }
        return base64Image;
   } catch {
       return base64Image; 
   }
};

