import { GoogleGenAI, Type, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext, getSettings } from "./storage";
import { ollamaGenerate } from "./ollama";

// --- GESTIÓN DE CREDENCIALES ---

const getAI = () => {
  const settings = getSettings();
  // Prioridad: 1. Clave en Configuración, 2. Clave en .env
  const apiKey = (settings.geminiApiKey && settings.geminiApiKey.trim() !== '') 
                 ? settings.geminiApiKey 
                 : process.env.API_KEY;

  if (!apiKey && settings.aiProvider === 'gemini') {
    // No lanzamos alerta intrusiva aquí para no romper flujos en background,
    // pero el error se capturará más adelante.
    console.error("API Key no encontrada en Configuración ni en .env");
  }
  return new GoogleGenAI({ apiKey: apiKey || 'dummy_key_to_prevent_crash' });
};

// --- CEREBRO INTELIGENTE (SMART GENERATE) ---
// Esta función maneja automáticamente los errores y cambia de modelo si es necesario.

const smartGenerate = async (
    prompt: string, 
    options: {
        images?: string[], 
        jsonMode?: boolean,
        system?: string,
        modelGemini?: string
    }
): Promise<string> => {
    const settings = getSettings();

    // 1. MODO LOCAL (OLLAMA)
    if (settings.aiProvider === 'ollama') {
        return await ollamaGenerate(prompt, options.images, options.system, options.jsonMode);
    }

    // 2. MODO NUBE (GEMINI)
    const ai = getAI();

    // Si el usuario no ha configurado nada, usamos el modelo más seguro y estable: 1.5 Flash
    let targetModel = settings.geminiModel || 'gemini-1.5-flash';

    // Función interna para intentar la llamada
    const executeCall = async (modelToUse: string) => {
        const isThinkingModel = modelToUse.includes('gemini-3'); // Solo modelos v3 soportan thinking

        // Configuración base
        const config: any = {
             systemInstruction: options.system,
             responseMimeType: options.jsonMode ? "application/json" : undefined,
        };

        // Thinking vs Search (Son mutuamente excluyentes a veces en versiones preview)
        if (isThinkingModel) {
            config.thinkingConfig = { thinkingBudget: 1024 };
        } else {
             config.tools = [{googleSearch: {}}];
        }

        // Preparar contenido
        let contents;
        if (options.images && options.images.length > 0) {
            // Modo Visión
            const imageParts = options.images.map(img => ({
                inlineData: { data: img.split(',')[1], mimeType: 'image/jpeg' }
            }));
            contents = [
                { role: 'user', parts: [...imageParts, { text: prompt }] }
            ];
            // Los modelos de visión a veces no soportan search tools, limpiamos tools si hay imagenes
            delete config.tools; 
        } else {
            // Modo Texto
            contents = prompt;
        }

        const response = await ai.models.generateContent({
            model: modelToUse,
            contents: contents,
            config: config
        });

        return response.text || "";
    };

    try {
        return await executeCall(targetModel);
    } catch (error: any) {
        console.warn(`Error usando modelo ${targetModel}:`, error);

        // FALLBACK DE SEGURIDAD
        // Si falla (404, Quota, Overloaded), intentamos con Gemini 1.5 Flash que es el "todo terreno".
        const SAFE_MODEL = 'gemini-1.5-flash';

        if (targetModel !== SAFE_MODEL) {
            console.log(`Intentando fallback a ${SAFE_MODEL}...`);
            try {
                return await executeCall(SAFE_MODEL);
            } catch (fallbackError: any) {
                console.error("Fallback falló:", fallbackError);
                throw new Error(`Error de IA: ${fallbackError.message || "Verifica tu API Key"}`);
            }
        }
        throw error;
    }
};

