const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const newMessages = [...messages, { role: 'user' as const, text: input }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const settings = getSettings();
      // Usar clave de configuración o fallback a env
      const apiKey = settings.geminiApiKey || process.env.API_KEY || '';

      if (!apiKey && settings.aiProvider === 'gemini') {
          setMessages([...newMessages, { role: 'model', text: "⚠️ Error: No veo la API Key. Por favor agrégala en Configuración." }]);
          setLoading(false);
          return;
      }

      const ai = new GoogleGenAI({ apiKey });

      // Usamos Gemini 1.5 Flash por defecto para el chat rápido
      const modelName = 'gemini-1.5-flash';

      const chat = ai.chats.create({ 
        model: modelName,
