            systemInstruction: "Eres un asistente experto en electrónica de Gusrepart. Ayuda a los técnicos con dudas rápidas." 
        }
      });

      const response = await chat.sendMessage({ message: input });
      setMessages([...newMessages, { role: 'model', text: response.text || '' }]);
    } catch (err: any) {
      console.error(err);
      setMessages([...newMessages, { role: 'model', text: `Error: ${err.message || 'No se pudo conectar con la IA.'}` }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
