import React, { useState, useRef } from 'react';
import { analyzePCBImage, enhancePCBImage, searchSchematics, getFunctionalAnalysis } from '../services/gemini';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  onUpdate: (images: string[], result: PCBAnalysisResult, schematics: any, functional: string) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, onUpdate }) => {
  const [images, setImages] = useState<string[]>(persistedImages);
  const [analyzing, setAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (ev.target?.result) {
          const newImages = [...images, ev.target.result as string];
          setImages(newImages);
        }
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const runAnalysis = async () => {
    if (images.length === 0) return;
    setAnalyzing(true);
    try {
      // 1. Analizar Imagen
      const result = await analyzePCBImage(images);

      // 2. Buscar Esquemas en paralelo
      const schemPromise = searchSchematics(`${result.model} ${result.boardNumber} schematic`);

      // 3. Análisis Funcional
      const funcPromise = getFunctionalAnalysis(result.identifiedComponents, result.model);

      const [schem, func] = await Promise.all([schemPromise, funcPromise]);

      onUpdate(images, result, schem, func);
    } catch (e) {
      console.error(e);
      alert("Error en el análisis AI");
    } finally {
      setAnalyzing(false);
    }
  };

  return (
    <div className="flex h-full flex-col md:flex-row overflow-hidden">
      {/* Panel Izquierdo: Imágenes */}
      <div className="w-full md:w-1/2 p-6 bg-background-dark border-r border-border-dark flex flex-col gap-4 overflow-y-auto">
        <h2 className="text-2xl font-bold">Evidencia Visual</h2>

        <div className="grid grid-cols-2 gap-4">
          {images.map((img, idx) => (
            <div key={idx} className="aspect-square rounded-xl overflow-hidden border border-border-dark relative group">
              <img src={img} className="w-full h-full object-cover" />
              <button 
                onClick={() => {
                   const newImgs = images.filter((_, i) => i !== idx);
                   setImages(newImgs);
                   onUpdate(newImgs, persistedResult!, null, ""); 
                }}
                className="absolute top-2 right-2 bg-red-500/80 p-1 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <span className="material-symbols-outlined text-sm">close</span>
              </button>
            </div>
          ))}

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="aspect-square rounded-xl border-2 border-dashed border-border-dark flex flex-col items-center justify-center text-text-secondary hover:border-primary hover:text-primary transition-colors bg-surface-dark/50"
          >
            <span className="material-symbols-outlined text-4xl mb-2">add_a_photo</span>
            <span className="text-sm font-bold">Agregar Foto</span>
          </button>
        </div>
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

        <button 
          onClick={runAnalysis}
          disabled={analyzing || images.length === 0}
          className="mt-auto bg-primary hover:bg-primary-hover text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-primary/20 transition-all flex items-center justify-center gap-2"
        >
          {analyzing ? (
             <><span className="material-symbols-outlined animate-spin">progress_activity</span> Analizando...</>
          ) : (
             <><span className="material-symbols-outlined">psychology</span> Analizar con IA</>
          )}
        </button>
      </div>

      {/* Panel Derecho: Resultados */}
      <div className="w-full md:w-1/2 p-6 bg-[#101622] overflow-y-auto">
        {persistedResult ? (
          <div className="space-y-6 animate-in slide-in-from-right-8">
            <div className="bg-surface-dark border border-border-dark rounded-2xl p-6">
               <h3 className="text-text-secondary text-sm uppercase font-bold mb-4">Identificación</h3>
               <div className="space-y-4">
                 <div>
                    <label className="text-xs text-text-secondary">Modelo Detectado</label>
                    <div className="text-2xl font-black text-white">{persistedResult.model}</div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-xs text-text-secondary">Fabricante</label>
                        <div className="text-lg font-medium text-white">{persistedResult.manufacturer}</div>
                    </div>
                    <div>
                        <label className="text-xs text-text-secondary">Board Number</label>
                        <div className="text-lg font-mono text-primary bg-primary/10 px-2 rounded w-fit">{persistedResult.boardNumber}</div>
                    </div>
                 </div>
               </div>
            </div>

            <div className="bg-surface-dark border border-border-dark rounded-2xl p-6">
                <h3 className="text-text-secondary text-sm uppercase font-bold mb-4">Componentes Clave</h3>
                <div className="flex flex-wrap gap-2">
                    {persistedResult.identifiedComponents.map((c, i) => (
                        <span key={i} className="px-3 py-1 bg-white/5 border border-white/10 rounded-full text-sm text-gray-300">
                            {c}
                        </span>
                    ))}
                </div>
            </div>

            {persistedResult.detectedAnomalies.length > 0 && (
                <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-6">
                    <h3 className="text-red-400 text-sm uppercase font-bold mb-2 flex items-center gap-2">
                        <span className="material-symbols-outlined">warning</span> Anomalías Visuales
                    </h3>
                    <ul className="list-disc list-inside text-red-200 text-sm">
                        {persistedResult.detectedAnomalies.map((a, i) => <li key={i}>{a}</li>)}
                    </ul>
                </div>
            )}
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-text-secondary opacity-50">
            <span className="material-symbols-outlined text-6xl mb-4">analytics</span>
            <p>Sube fotos y presiona Analizar para comenzar.</p>
          </div>
        )}
      </div>
    </div>
  );
};

