export default BoardviewSchematics;

import React, { useState } from 'react';
import { generateMeasurementPlan, getFinalVerdict } from '../services/gemini';
import { MeasurementPoint, PCBAnalysisResult } from '../types';

interface GuidedMeasurementProps {
  pcbImages: string[];
  pcbResult: PCBAnalysisResult | null;
  functionalAI: string;
  persistedPoints: MeasurementPoint[];
  onUpdate: (points: MeasurementPoint[]) => void;
  onVerdictGenerated: (verdict: string) => void;
}

const GuidedMeasurement: React.FC<GuidedMeasurementProps> = ({ 
    pcbImages, pcbResult, functionalAI, persistedPoints, onUpdate, onVerdictGenerated 
}) => {
  const [generating, setGenerating] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);

  const handleGeneratePlan = async () => {
    if (!pcbResult) return;
    setGenerating(true);
    try {
        const points = await generateMeasurementPlan(pcbResult, functionalAI, pcbImages[0]);
        const pointsWithId = points.map((p, i) => ({ ...p, id: `mp-${Date.now()}-${i}`, status: 'pending' as const }));
        onUpdate(pointsWithId);
    } catch (e) {
        alert("Error generando plan");
    } finally {
        setGenerating(false);
    }
  };

  const handleValueChange = (id: string, val: string) => {
      const newPoints = persistedPoints.map(p => p.id === id ? { ...p, measuredValue: val } : p);
      onUpdate(newPoints);
  };

  const markStatus = (id: string, status: 'ok' | 'fail') => {
      const newPoints = persistedPoints.map(p => p.id === id ? { ...p, status } : p);
      onUpdate(newPoints);
  };

  const submitForVerdict = async () => {
      setAnalyzing(true);
      try {
          const verdict = await getFinalVerdict(pcbResult, persistedPoints);
          onVerdictGenerated(verdict);
      } catch (e) {
          alert("Error analizando resultados");
      } finally {
          setAnalyzing(false);
      }
  };

  if (!pcbResult) return <div className="p-10 text-center text-text-secondary">Identifica la placa primero.</div>;

  return (
    <div className="flex h-full flex-col md:flex-row">
        {/* Panel Izquierdo: Lista */}
        <div className="w-full md:w-1/2 bg-background-dark p-6 overflow-y-auto border-r border-border-dark">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">Plan de Medición</h2>
                {persistedPoints.length === 0 && (
                    <button 
                        onClick={handleGeneratePlan} 
                        disabled={generating}
                        className="bg-primary hover:bg-primary-hover text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2"
                    >
                        {generating ? <span className="material-symbols-outlined animate-spin">refresh</span> : <span className="material-symbols-outlined">genetics</span>}
                        Generar Puntos
                    </button>
                )}
            </div>

            <div className="space-y-4">
                {persistedPoints.map((point) => (
                    <div key={point.id} className={`p-4 rounded-xl border transition-all ${point.status === 'ok' ? 'bg-green-500/5 border-green-500/30' : point.status === 'fail' ? 'bg-red-500/5 border-red-500/30' : 'bg-surface-dark border-border-dark'}`}>
                        <div className="flex justify-between mb-2">
                            <span className="font-bold text-white">{point.component} ({point.testPoint})</span>
                            <span className="text-xs bg-white/10 px-2 py-0.5 rounded text-text-secondary">{point.mode}</span>
                        </div>
                        <p className="text-sm text-text-secondary mb-3">{point.description}</p>
                        <p className="text-xs font-mono text-primary mb-3">Valor Esperado: {point.expectedValue}</p>

                        <div className="flex gap-2 items-center">
                            <input 
                                placeholder="Valor medido..." 
                                className="flex-1 bg-black/30 border border-border-dark rounded-lg px-3 py-2 text-sm text-white"
                                value={point.measuredValue || ''}
                                onChange={(e) => handleValueChange(point.id, e.target.value)}
                            />
                            <button onClick={() => markStatus(point.id, 'ok')} className={`p-2 rounded-lg border ${point.status === 'ok' ? 'bg-green-500 text-white border-green-500' : 'border-border-dark text-gray-500 hover:text-green-500'}`}>
                                <span className="material-symbols-outlined">check</span>
                            </button>
                            <button onClick={() => markStatus(point.id, 'fail')} className={`p-2 rounded-lg border ${point.status === 'fail' ? 'bg-red-500 text-white border-red-500' : 'border-border-dark text-gray-500 hover:text-red-500'}`}>
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </div>
                    </div>
                ))}
            </div>

            {persistedPoints.length > 0 && (
                <button 
                    onClick={submitForVerdict}
                    disabled={analyzing}
                    className="w-full mt-6 py-4 bg-primary hover:bg-primary-hover text-white rounded-xl font-bold shadow-lg transition-all"
                >
                    {analyzing ? 'Analizando Resultados...' : 'Obtener Veredicto Final'}
                </button>
            )}
        </div>

        {/* Panel Derecho: Imagen Referencia */}
        <div className="w-full md:w-1/2 bg-[#101622] p-6 flex flex-col items-center justify-center relative overflow-hidden">
            {pcbImages[0] ? (
                <div className="relative w-full max-w-lg">
                    <img src={pcbImages[0]} className="w-full rounded-lg shadow-2xl opacity-50" />
                    {/* Overlay de puntos estimados */}
                    {persistedPoints.map((p) => (
                        p.coordinates && (
                            <div 
                                key={p.id}
                                className="absolute size-4 bg-red-500 border-2 border-white rounded-full animate-pulse shadow-[0_0_15px_rgba(239,68,68,0.8)] cursor-pointer hover:scale-150 transition-transform"
                                style={{
                                    top: `${(p.coordinates[0] + p.coordinates[2])/2}%`,
                                    left: `${(p.coordinates[1] + p.coordinates[3])/2}%`
                                }}
                                title={p.testPoint}
                            />
                        )
                    ))}
                    <div className="absolute bottom-4 left-4 bg-black/60 backdrop-blur-md px-4 py-2 rounded-lg text-xs text-white">
                        <p>Los puntos rojos son estimaciones de IA.</p>
                    </div>
                </div>
            ) : (
                <p className="text-text-secondary">Sin imagen de referencia.</p>
            )}
        </div>
    </div>
  );
};

export default GuidedMeasurement;

import React, { useState, useEffect, useRef } from 'react';
import { DiagnosticTurn, PCBAnalysisResult } from '../types';
import { getDiagnosticAdvice, textToSpeech } from '../services/gemini';

interface Props {
  persistedHistory: DiagnosticTurn[];
  pcbResult: PCBAnalysisResult | null;
  onUpdate: (history: DiagnosticTurn[]) => void;
}

const DiagnosticDecisionTree: React.FC<Props> = ({ persistedHistory, pcbResult, onUpdate }) => {
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [persistedHistory]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;
    const userMsg: DiagnosticTurn = { role: 'user', content: input, timestamp: Date.now() };
    const newHistory = [...persistedHistory, userMsg];
    onUpdate(newHistory);
    setInput("");
    setLoading(true);

    try {
        const responseText = await getDiagnosticAdvice(newHistory, input, pcbResult?.model);
        const aiMsg: DiagnosticTurn = { role: 'assistant', content: responseText, timestamp: Date.now() };
        onUpdate([...newHistory, aiMsg]);
    } catch (e) {
        onUpdate([...newHistory, { role: 'assistant', content: "Error de conexión con IA.", timestamp: Date.now() }]);
    } finally {
        setLoading(false);
    }
  };

  const playTTS = (text: string) => {
      textToSpeech(text, (buffer) => {
          const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
          const source = ctx.createBufferSource();
          source.buffer = buffer;
          source.connect(ctx.destination);
          source.start(0);
      });
  };

  return (
    <div className="flex flex-col h-full bg-background-dark max-w-4xl mx-auto border-x border-border-dark">
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {persistedHistory.length === 0 && (
                <div className="text-center text-text-secondary mt-20">
                    <span className="material-symbols-outlined text-6xl mb-4 text-primary">forum</span>
                    <h2 className="text-xl font-bold text-white">Asistente de Diagnóstico</h2>
                    <p>Describe el síntoma o pregunta sobre la placa identificada.</p>
                </div>
            )}

            {persistedHistory.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[80%] rounded-2xl p-4 ${msg.role === 'user' ? 'bg-primary text-white rounded-tr-none' : 'bg-surface-dark border border-border-dark text-gray-200 rounded-tl-none'}`}>
                        <div className="prose prose-invert prose-sm" dangerouslySetInnerHTML={{__html: msg.content.replace(/\n/g, '<br/>')}} />
                        {msg.role === 'assistant' && (
                            <button onClick={() => playTTS(msg.content)} className="mt-2 text-text-secondary hover:text-primary">
                                <span className="material-symbols-outlined text-sm">volume_up</span>
                            </button>
                        )}
                    </div>
                </div>
            ))}
            {loading && (
                <div className="flex justify-start">
                    <div className="bg-surface-dark border border-border-dark rounded-2xl p-4 flex gap-2 items-center">
                        <span className="size-2 bg-primary rounded-full animate-bounce"></span>
                        <span className="size-2 bg-primary rounded-full animate-bounce delay-100"></span>
                        <span className="size-2 bg-primary rounded-full animate-bounce delay-200"></span>
                    </div>
                </div>
            )}
            <div ref={bottomRef} />
        </div>

        <div className="p-4 bg-surface-dark border-t border-border-dark">
            <div className="flex gap-2">
                <input 
                    value={input}
                    onChange={e => setInput(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && handleSend()}
                    placeholder="Escribe el síntoma (ej: No enciende, consumo 0.05A)..."
                    className="flex-1 bg-background-dark border border-border-dark rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-2 focus:ring-primary transition-all"
                />
                <button onClick={handleSend} disabled={loading} className="bg-primary hover:bg-primary-hover text-white p-3 rounded-xl transition-colors">
                    <span className="material-symbols-outlined">send</span>
                </button>
            </div>
        </div>
    </div>
  );
};

export default DiagnosticDecisionTree;

import React, { useEffect, useState } from 'react';
import { getAllRepairs, deleteRepairFromHistory, exportDatabase, importDatabase } from '../services/storage';

interface Props {
  onLoadRepair: (repair: any) => void;
}

const DatabaseScreen: React.FC<Props> = ({ onLoadRepair }) => {
  const [repairs, setRepairs] = useState<any[]>([]);
  const [search, setSearch] = useState("");

  const loadData = async () => {
    const data = await getAllRepairs();
    setRepairs(data.sort((a, b) => b.timestamp - a.timestamp));
  };

  useEffect(() => { loadData(); }, []);

  const handleDelete = async (ts: number, e: React.MouseEvent) => {
      e.stopPropagation();
      if (confirm("¿Borrar reparación permanentemente?")) {
          await deleteRepairFromHistory(ts);
          loadData();
      }
  };

  const handleExport = async () => {
      const json = await exportDatabase();
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `gusrepart_backup_${Date.now()}.json`;
      a.click();
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          const text = await e.target.files[0].text();
          if (await importDatabase(text)) {
              alert("Importación exitosa.");
              loadData();
          } else {
              alert("Error al importar.");
          }
      }
  };

  const filtered = repairs.filter(r => 
      r.pcbResult?.model?.toLowerCase().includes(search.toLowerCase()) || 
      r.pcbResult?.boardNumber?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="p-6 md:p-10 h-full overflow-y-auto bg-background-dark">
      <div className="max-w-6xl mx-auto space-y-6">
        <div className="flex justify-between items-end">
            <div>
                <h1 className="text-3xl font-bold text-white">Base de Datos</h1>
                <p className="text-text-secondary">{repairs.length} reparaciones registradas.</p>
            </div>
            <div className="flex gap-2">
                <button onClick={handleExport} className="px-4 py-2 border border-border-dark rounded-lg text-sm hover:bg-white/5 transition-colors">Exportar JSON</button>
                <label className="px-4 py-2 bg-surface-dark border border-border-dark rounded-lg text-sm hover:bg-white/5 cursor-pointer transition-colors">
                    Importar JSON
                    <input type="file" className="hidden" accept=".json" onChange={handleImport} />
                </label>
            </div>
        </div>

        <input 
            placeholder="Buscar por modelo o serial..." 
            className="w-full bg-surface-dark border border-border-dark rounded-xl px-4 py-3 text-white focus:ring-1 focus:ring-primary outline-none"
            value={search}
            onChange={e => setSearch(e.target.value)}
        />

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filtered.map((repair) => (
                <div 
                    key={repair.timestamp}
                    onClick={() => onLoadRepair(repair)}
                    className="bg-surface-dark border border-border-dark hover:border-primary/50 p-4 rounded-xl cursor-pointer group transition-all relative"
                >
                    <div className="flex items-start gap-4">
                        <div className="size-16 bg-black/40 rounded-lg shrink-0 overflow-hidden">
                             {repair.pcbImages?.[0] ? (
                                 <img src={repair.pcbImages[0]} className="w-full h-full object-cover opacity-80" />
                             ) : (
                                 <span className="material-symbols-outlined text-2xl text-text-secondary m-4">memory</span>
                             )}
                        </div>
                        <div className="flex-1 min-w-0">
                            <h3 className="font-bold text-white truncate">{repair.pcbResult?.model || "Desconocido"}</h3>
                            <p className="text-xs text-text-secondary truncate">{repair.pcbResult?.boardNumber || "N/S"}</p>
                            <span className="text-[10px] bg-white/5 px-2 py-0.5 rounded text-gray-400 mt-2 inline-block">
                                {new Date(repair.timestamp).toLocaleDateString()}
                            </span>
                        </div>
                    </div>
                    <button 
                        onClick={(e) => handleDelete(repair.timestamp, e)}
                        className="absolute top-2 right-2 p-1 text-text-secondary hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                        <span className="material-symbols-outlined text-lg">delete</span>
                    </button>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

export default DatabaseScreen;

