import React, { useState, useEffect } from 'react';
import { getAllKnowledge, addKnowledgeEntry, deleteKnowledgeEntry } from '../services/storage';
import { processTechnicalPDF, distillKnowledge } from '../services/gemini';
import { KnowledgeEntry } from '../types';

const KnowledgeBase: React.FC = () => {
  const [entries, setEntries] = useState<KnowledgeEntry[]>([]);
  const [processing, setProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'list' | 'upload' | 'manual'>('list');

  // Manual inputs
  const [manualText, setManualText] = useState("");
  const [manualTitle, setManualTitle] = useState("");

  useEffect(() => {
      getAllKnowledge().then(setEntries);
  }, []);

  const handlePdfUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          setProcessing(true);
          try {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = async (ev) => {
                  const base64 = (ev.target?.result as string).split(',')[1];
                  const extracted = await processTechnicalPDF(base64);

                  const newEntry: KnowledgeEntry = {
                      id: `kb_${Date.now()}`,
                      title: extracted.title || file.name,
                      tags: extracted.tags || ['pdf'],
                      content: extracted.content || "Sin contenido extraído.",
                      source: "PDF Upload",
                      timestamp: Date.now()
                  };

                  await addKnowledgeEntry(newEntry);
                  setEntries(await getAllKnowledge());
                  setActiveTab('list');
              };
              reader.readAsDataURL(file);
          } catch (error) {
              alert("Error procesando PDF. Asegúrate de configurar Gemini.");
          } finally {
              setProcessing(false);
          }
      }
  };

  const handleManualSubmit = async () => {
      if (!manualText) return;
      setProcessing(true);
      try {
          const distilled = await distillKnowledge(manualText, "Nota Manual");
          const newEntry: KnowledgeEntry = {
              id: `kb_${Date.now()}`,
              title: manualTitle || distilled.title,
              tags: distilled.tags,
              content: distilled.content,
              source: "Manual Input",
              timestamp: Date.now()
          };
          await addKnowledgeEntry(newEntry);
          setEntries(await getAllKnowledge());
          setManualText("");
          setManualTitle("");
          setActiveTab('list');
      } catch (e) {
          alert("Error guardando nota.");
      } finally {
          setProcessing(false);
      }
  };

  const handleDelete = async (id: string) => {
      if (confirm("¿Borrar entrada?")) {
          await deleteKnowledgeEntry(id);
          setEntries(await getAllKnowledge());
      }
  };

  return (
    <div className="p-6 md:p-10 h-full overflow-y-auto bg-background-dark">
        <div className="max-w-5xl mx-auto space-y-6">
            <div className="flex justify-between items-center">
                <h1 className="text-3xl font-bold text-white">Base de Conocimiento</h1>
                <div className="flex bg-surface-dark rounded-lg p-1 border border-border-dark">
                    <button onClick={() => setActiveTab('list')} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'list' ? 'bg-primary text-white' : 'text-text-secondary hover:text-white'}`}>Biblioteca</button>
                    <button onClick={() => setActiveTab('upload')} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'upload' ? 'bg-primary text-white' : 'text-text-secondary hover:text-white'}`}>Subir PDF</button>
                    <button onClick={() => setActiveTab('manual')} className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'manual' ? 'bg-primary text-white' : 'text-text-secondary hover:text-white'}`}>Nota Rápida</button>
                </div>
            </div>

            {activeTab === 'list' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {entries.map(entry => (
                        <div key={entry.id} className="bg-surface-dark border border-border-dark p-6 rounded-xl hover:border-primary/30 transition-colors group relative">
                            <h3 className="font-bold text-lg text-white mb-2">{entry.title}</h3>
                            <div className="flex flex-wrap gap-2 mb-4">
                                {entry.tags.map((t, i) => <span key={i} className="text-[10px] bg-white/5 px-2 py-0.5 rounded uppercase tracking-wider text-text-secondary">{t}</span>)}
                            </div>
                            <p className="text-sm text-gray-400 line-clamp-3 mb-2">{entry.content}</p>
                            <span className="text-[10px] text-primary">{entry.source}</span>
                            <button onClick={() => handleDelete(entry.id)} className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-text-secondary hover:text-red-500 transition-opacity">
                                <span className="material-symbols-outlined">delete</span>
                            </button>
                        </div>
                    ))}
                    {entries.length === 0 && <p className="text-text-secondary italic">La base de datos está vacía.</p>}
                </div>
            )}

            {activeTab === 'upload' && (
                <div className="flex flex-col items-center justify-center h-64 border-2 border-dashed border-border-dark rounded-2xl hover:bg-surface-dark/50 transition-colors">
                    {processing ? (
                        <div className="text-center">
                            <span className="material-symbols-outlined text-4xl animate-spin text-primary mb-2">settings</span>
                            <p className="text-white font-bold">La IA está leyendo el PDF...</p>
                            <p className="text-text-secondary text-sm">Esto puede tardar unos segundos.</p>
                        </div>
                    ) : (
                        <label className="cursor-pointer text-center">
                            <span className="material-symbols-outlined text-6xl text-text-secondary mb-4">upload_file</span>
                            <h3 className="text-xl font-bold text-white mb-1">Arrastra o Click para subir PDF</h3>
