                    )}
                </div>
            )}

            {activeTab === 'manual' && (
                <div className="bg-surface-dark border border-border-dark rounded-2xl p-6 space-y-4">
                    <input 
                        value={manualTitle}
                        onChange={e => setManualTitle(e.target.value)}
