                        className="w-full bg-background-dark border border-border-dark rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-1 focus:ring-primary"
                    />
                    <textarea 
                        value={manualText}
                        onChange={e => setManualText(e.target.value)}
