                        className="w-full h-40 bg-background-dark border border-border-dark rounded-xl px-4 py-3 text-white focus:outline-none focus:ring-1 focus:ring-primary resize-none"
                    />
                    <div className="flex justify-end">
                        <button 
                            onClick={handleManualSubmit}
                            disabled={processing || !manualText}
                            className="bg-primary hover:bg-primary-hover text-white px-6 py-2 rounded-lg font-bold disabled:opacity-50"
                        >
                            {processing ? 'Destilando con IA...' : 'Guardar Conocimiento'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

