import { GoogleGenAI, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext, getSettings } from "./storage";
import { ollamaGenerate } from "./ollama";

// --- GESTIÓN DE CREDENCIALES ---

const getAI = () => {
  const settings = getSettings();
  // Prioridad: 1. Clave en Configuración, 2. Clave en .env
  const apiKey = (settings.geminiApiKey && settings.geminiApiKey.trim() !== '') 
                 ? settings.geminiApiKey 
                 : process.env.API_KEY;

  if (!apiKey && settings.aiProvider === 'gemini') {
    console.error("API Key no encontrada en Configuración ni en .env");
  }
  return new GoogleGenAI({ apiKey: apiKey || 'dummy_key_to_prevent_crash' });
};

// --- CEREBRO INTELIGENTE (SMART GENERATE) ---

const smartGenerate = async (
    prompt: string, 
    options: {
        images?: string[], 
        jsonMode?: boolean,
        system?: string,
        modelGemini?: string
    }
): Promise<string> => {
    const settings = getSettings();

    // 1. MODO LOCAL (OLLAMA)
    if (settings.aiProvider === 'ollama') {
        return await ollamaGenerate(prompt, options.images, options.system, options.jsonMode);
    }

    // 2. MODO NUBE (GEMINI)
    const ai = getAI();

    // Mapeo de modelos legacy a modelos nuevos soportados
    let targetModel = settings.geminiModel || 'gemini-3-flash-preview';
    if (targetModel.includes('1.5')) {
        targetModel = 'gemini-3-flash-preview';
    }

    const executeCall = async (modelToUse: string) => {
        const isThinkingModel = modelToUse.includes('gemini-3') && !modelToUse.includes('flash');

        const config: any = {
             systemInstruction: options.system,
             responseMimeType: options.jsonMode ? "application/json" : undefined,
        };

        // Configuración específica para modelos con pensamiento (Pro) vs Flash
        if (isThinkingModel) {
            config.thinkingConfig = { thinkingBudget: 1024 };
        } else if (!options.images) {
             // Search solo permitido sin imágenes
             config.tools = [{googleSearch: {}}];
        }

        let contents;
        if (options.images && options.images.length > 0) {
            const imageParts = options.images.map(img => ({
                inlineData: { data: img.split(',')[1], mimeType: 'image/jpeg' }
            }));
            contents = [
                { role: 'user', parts: [...imageParts, { text: prompt }] }
            ];
            // Visión + Tools suele fallar en algunos modelos, aseguramos limpieza
            delete config.tools; 
        } else {
            contents = prompt;
        }

        const response = await ai.models.generateContent({
            model: modelToUse,
            contents: contents,
            config: config
        });

        return response.text || "";
    };

    try {
        return await executeCall(targetModel);
    } catch (error: any) {
        console.warn(`Error usando modelo ${targetModel}:`, error);

        // FALLBACK SYSTEM: Intentar con Gemini 3 Flash Preview (El más robusto actualmente)
        const SAFE_MODEL = 'gemini-3-flash-preview';
        if (targetModel !== SAFE_MODEL) {
            console.log(`Reintentando con modelo seguro: ${SAFE_MODEL}...`);
            try {
                return await executeCall(SAFE_MODEL);
            } catch (fallbackError: any) {
                console.error("Fallback falló:", fallbackError);
                throw new Error(`Error IA: ${fallbackError.message}`);
            }
        }
        throw error;
    }
};

// --- EXPORTACIONES ---

export const processTechnicalPDF = async (base64Pdf: string) => {
  const settings = getSettings();
  if (settings.aiProvider === 'ollama') throw new Error("PDF no soportado en Ollama");

  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview', 
    contents: [
      { inlineData: { mimeType: 'application/pdf', data: base64Pdf } },
      { text: `Extrae info técnica en JSON: { "title": "...", "tags": [...], "content": "..." }` }
    ],
    config: { responseMimeType: "application/json" }
  });

  return JSON.parse(response.text || '{}');
};

export const distillKnowledge = async (text: string, source: string) => {
    const prompt = `ENTRADA (${source}): ${text}
    OBJETIVO: Generar ficha de conocimiento técnico.
    FORMATO JSON: { "title": "...", "tags": [...], "content": "..." }`;

    const res = await smartGenerate(prompt, { jsonMode: true });
    try { return JSON.parse(res); } catch { return { title: "Info", tags: [], content: res }; }
};

export const getDiagnosticAdvice = async (history: {role: string, content: string}[], currentIssue: string, pcbModel?: string) => {
  let context = "";
  if (pcbModel) {
    const similar = await findSimilarRepairs(pcbModel);
    if (similar.length > 0) context += `HISTORIAL: ${similar.length} casos previos. `;
  }
  const kb = await searchKnowledgeContext(`${pcbModel || ''} ${currentIssue}`);

  const system = `Eres Gusrepart AI, experto en reparación. CONTEXTO: ${context} ${kb}. Responde breve y técnico.`;

  const chatStr = history.map(h => `${h.role === 'user' ? 'Técnico' : 'AI'}: ${h.content}`).join('\n');
  const fullPrompt = `Historial:\n${chatStr}\n\nConsulta: ${currentIssue}`;

  return await smartGenerate(fullPrompt, { system });
};

export const generateMeasurementPlan = async (pcbResult: any, functionalAnalysis: string, base64Image?: string): Promise<MeasurementPoint[]> => {
  const kb = await searchKnowledgeContext(`${pcbResult.model} ${pcbResult.identifiedComponents.join(' ')}`);

  const prompt = `
    Placa: ${pcbResult.model}. Componentes: ${pcbResult.identifiedComponents}.
    Contexto: ${functionalAnalysis} ${kb}
    Genera plan de medición (4-6 puntos). Estima coordenadas visuales [ymin, xmin, ymax, xmax] 0-100 si ves la imagen.
    FORMATO JSON Array de MeasurementPoint.
  `;

  const res = await smartGenerate(prompt, { 
      images: base64Image ? [base64Image] : undefined,
      jsonMode: true 
  });

  try { return JSON.parse(res); } catch { return []; }
};

export const getFinalVerdict = async (pcbResult: any, measurements: MeasurementPoint[]): Promise<string> => {
  const prompt = `Analiza mediciones: ${JSON.stringify(measurements)} para ${pcbResult.model}. Veredicto técnico.`;
  return await smartGenerate(prompt, {});
};

