export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
    try {
        const ai = getAI(); 
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            const binaryString = atob(base64Audio);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
            const channelData = buffer.getChannelData(0);
            for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
            onAudioReady(buffer);
        }
    } catch (e) {
        console.warn("TTS no disponible", e);
    }
};

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { getSettings } from '../services/storage';

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const newMessages = [...messages, { role: 'user' as const, text: input }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const settings = getSettings();
      const apiKey = settings.geminiApiKey || process.env.API_KEY || '';

      if (!apiKey && settings.aiProvider === 'gemini') {
          setMessages([...newMessages, { role: 'model', text: "⚠️ Configura tu API Key en Ajustes." }]);
          setLoading(false);
          return;
      }

      const ai = new GoogleGenAI({ apiKey });

      // Forzamos modelo rápido para chat (Gemini 3 Flash)
      const chat = ai.chats.create({ 
        model: 'gemini-3-flash-preview',
        config: { 
            systemInstruction: "Eres un asistente experto en electrónica de Gusrepart." 
        }
      });

      const response = await chat.sendMessage({ message: input });
      setMessages([...newMessages, { role: 'model', text: response.text || '' }]);
    } catch (err: any) {
      console.error(err);
      setMessages([...newMessages, { role: 'model', text: `Error: ${err.message}` }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {!isOpen && (
        <button 
          onClick={() => setIsOpen(true)}
          className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform flex items-center justify-center"
