  const kb = await searchKnowledgeContext(`${pcbResult.model} ${pcbResult.identifiedComponents.join(' ')}`);

  const prompt = `
    Placa: ${pcbResult.model}. Componentes: ${pcbResult.identifiedComponents}.
    Contexto: ${functionalAnalysis} ${kb}
    Genera plan de medición (4-6 puntos). Estima coordenadas visuales [ymin, xmin, ymax, xmax] 0-100 si ves la imagen.
    FORMATO JSON Array de MeasurementPoint.
  `;

  const res = await smartGenerate(prompt, { 
      images: base64Image ? [base64Image] : undefined,
      jsonMode: true 
  });

  try { return JSON.parse(res); } catch { return []; }
};

