export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
    try {
        const ai = getAI(); 
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            const binaryString = atob(base64Audio);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
            const channelData = buffer.getChannelData(0);
            for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
            onAudioReady(buffer);
        }
    } catch (e) {
        console.warn("TTS no disponible", e);
    }
};

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { getSettings } from '../services/storage';

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const newMessages = [...messages, { role: 'user' as const, text: input }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const settings = getSettings();
      const apiKey = settings.geminiApiKey || process.env.API_KEY || '';

      if (!apiKey && settings.aiProvider === 'gemini') {
          setMessages([...newMessages, { role: 'model', text: "⚠️ Configura tu API Key en Ajustes." }]);
          setLoading(false);
          return;
      }

      const ai = new GoogleGenAI({ apiKey });

      // USAMOS EL MODELO ELEGIDO EN CONFIGURACIÓN
      const modelToUse = settings.geminiModel || 'gemini-3-flash-preview';

      const chat = ai.chats.create({ 
        model: modelToUse,
        config: { 
            systemInstruction: "Eres un asistente experto en electrónica de Gusrepart." 
        }
      });

      const response = await chat.sendMessage({ message: input });
      setMessages([...newMessages, { role: 'model', text: response.text || '' }]);
    } catch (err: any) {
      console.error(err);
      // Mensaje de error amigable si el modelo falla (ej: 404)
      let errorMsg = `Error: ${err.message}`;
      if (err.message.includes("404")) {
          errorMsg = `Error: El modelo seleccionado no está disponible. Ve a Configuración y prueba otro (ej: Gemini 2.0 Flash o Gemini 1.5 Flash Latest).`;
      }
      setMessages([...newMessages, { role: 'model', text: errorMsg }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {!isOpen && (
        <button 
          onClick={() => setIsOpen(true)}
          className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform flex items-center justify-center"
        >
          <span className="material-symbols-outlined">smart_toy</span>
        </button>
      )}

      {isOpen && (
        <div className="w-80 md:w-96 h-[500px] bg-surface-dark border border-border-dark rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-4">
          <div className="p-4 bg-primary text-white flex justify-between items-center">
            <h3 className="font-bold flex items-center gap-2">
              <span className="material-symbols-outlined">smart_toy</span> Asistente Técnico
            </h3>
            <button onClick={() => setIsOpen(false)}><span className="material-symbols-outlined">close</span></button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-background-dark">
            {messages.length === 0 && (
              <p className="text-center text-text-secondary text-sm mt-10">¿En qué puedo ayudarte hoy?</p>
