import { GoogleGenAI, Modality } from "@google/genai";
import { MeasurementPoint } from "../types";
import { findSimilarRepairs, searchKnowledgeContext, getSettings } from "./storage";
import { ollamaGenerate } from "./ollama";

// --- GESTIÓN DE CREDENCIALES ---

const getAI = () => {
  const settings = getSettings();
  // Prioridad: 1. Clave en Configuración, 2. Clave en .env
  const apiKey = (settings.geminiApiKey && settings.geminiApiKey.trim() !== '') 
                 ? settings.geminiApiKey 
                 : process.env.API_KEY;

  if (!apiKey && settings.aiProvider === 'gemini') {
    console.error("API Key no encontrada en Configuración ni en .env");
  }
  return new GoogleGenAI({ apiKey: apiKey || 'dummy_key_to_prevent_crash' });
};

// --- CEREBRO INTELIGENTE (SMART GENERATE) ---

const smartGenerate = async (
    prompt: string, 
    options: {
        images?: string[], 
        jsonMode?: boolean,
        system?: string,
        modelGemini?: string
    }
): Promise<string> => {
    const settings = getSettings();

    // 1. MODO LOCAL (OLLAMA)
    if (settings.aiProvider === 'ollama') {
        return await ollamaGenerate(prompt, options.images, options.system, options.jsonMode);
    }

    // 2. MODO NUBE (GEMINI)
    const ai = getAI();

    // USAR EXACTAMENTE EL MODELO ELEGIDO EN CONFIGURACIÓN
    let targetModel = settings.geminiModel || 'gemini-3-flash-preview';

    const executeCall = async (modelToUse: string) => {
        const isThinkingModel = modelToUse.includes('gemini-3') && !modelToUse.includes('flash');
        const isOldModel = modelToUse.includes('1.5');

        const config: any = {
             systemInstruction: options.system,
             responseMimeType: options.jsonMode ? "application/json" : undefined,
        };

        // Configuración específica: Thinking solo en v3 Pro, Tools solo si no hay imágenes (limitación actual)
        if (isThinkingModel) {
            config.thinkingConfig = { thinkingBudget: 1024 };
        } else if (!options.images && !isOldModel) {
             // Search solo suele funcionar bien en modelos 2.0+, en 1.5 a veces da error de compatibilidad de tools
             // Lo desactivamos para 1.5 para máxima estabilidad
             config.tools = [{googleSearch: {}}];
        }

        let contents;
        if (options.images && options.images.length > 0) {
            const imageParts = options.images.map(img => ({
                inlineData: { data: img.split(',')[1], mimeType: 'image/jpeg' }
            }));
            contents = [
                { role: 'user', parts: [...imageParts, { text: prompt }] }
            ];
            delete config.tools; // Limpieza asegurada para visión
        } else {
            contents = prompt;
        }

        const response = await ai.models.generateContent({
            model: modelToUse,
            contents: contents,
            config: config
        });

        return response.text || "";
    };

    try {
        return await executeCall(targetModel);
    } catch (error: any) {
        console.warn(`Error usando modelo ${targetModel}:`, error);

        // FALLBACK SYSTEM: Si falla el modelo elegido, probamos el que el usuario confirmó que funciona (3.0 Flash)
        const SAFE_MODEL = 'gemini-3-flash-preview'; 

        if (targetModel !== SAFE_MODEL) {
            console.log(`Reintentando con modelo de respaldo seguro: ${SAFE_MODEL}...`);
            try {
                return await executeCall(SAFE_MODEL);
            } catch (fallbackError: any) {
                console.error("Fallback falló:", fallbackError);
                throw new Error(`Error IA (${targetModel} y Fallback): ${fallbackError.message}`);
            }
        }
        throw error;
    }
};

