};

// --- INITIALIZATION & SEEDING ---

export const initializeDatabase = async () => {
    try {
        const existing = await getAllKnowledge();
        if (existing.length === 0) {
            console.log("Base de datos vacía. Sembrando datos iniciales...");
            for (const entry of INITIAL_KNOWLEDGE) {
                await addKnowledgeEntry(entry);
            }
            return true;
        }
        return false;
    } catch (e) {
        console.error("Error inicializando DB:", e);
        return false;
    }
};

// --- SESSION & HISTORY ---

export const saveSessionData = async (key: string, data: any) => {
  if (key === 'pcbImages') {
    return performOperation(SESSION_STORE, 'readwrite', (store) => store.put(data, key));
  } else {
    try {
      localStorage.setItem(LS_PREFIX + key, JSON.stringify(data));
      return Promise.resolve();
    } catch (e) {
      console.warn("LocalStorage full or error", e);
      return Promise.resolve();
    }
  }
};

export const QK = async (key: string): Promise<any> => {
  if (key === 'pcbImages') {
    try {
      return await performOperation(SESSION_STORE, 'readonly', (store) => store.get(key));
    } catch { return null; }
  } else {
    const item = localStorage.getItem(LS_PREFIX + key);
    return item ? JSON.parse(item) : null;
  }
};

// Fix export name mismatch
export const getSessionData = async (key: string): Promise<any> => {
    return QK(key);
}

export const clearSessionStorage = async () => {
  Object.keys(localStorage).forEach(k => {
    if (k.startsWith(LS_PREFIX)) localStorage.removeItem(k);
  });
  try {
    await performOperation(SESSION_STORE, 'readwrite', (store) => store.clear());
  } catch (e) { console.error("Error clearing DB images", e); }
};

export const saveRepairToHistory = async (repair: any): Promise<number> => {
  const timestamp = Number(repair.timestamp || Date.now());
  const record = { ...repair, timestamp, lastModified: Date.now() };
  await performOperation(HISTORY_STORE, 'readwrite', (store) => store.put(record));
  return timestamp;
};

export const QH = async (): Promise<any[]> => {
  try {
    const result = await performOperation(HISTORY_STORE, 'readonly', (store) => store.getAll());
    return result || [];
  } catch (e) { return []; }
};
export const getAllRepairs = async (): Promise<any[]> => QH();

export const deleteRepairFromHistory = async (timestamp: number): Promise<boolean> => {
  try {
    await performOperation(HISTORY_STORE, 'readwrite', (store) => store.delete(Number(timestamp)));
    return true;
  } catch (e) { return false; }
};

export const findSimilarRepairs = async (model: string) => {
  try {
    const repairs = await getAllRepairs();
    if (!model) return [];
    const search = model.toLowerCase();
    return repairs.filter((h: any) => 
      h.pcbResult?.model?.toLowerCase().includes(search) ||
      h.pcbResult?.boardNumber?.toLowerCase().includes(search)
    );
  } catch (e) { return []; }
};

// --- KNOWLEDGE BASE SYSTEM ---

export const addKnowledgeEntry = async (entry: any) => {
    return performOperation(KNOWLEDGE_STORE, 'readwrite', (store) => store.put(entry));
};

export const getAllKnowledge = async (): Promise<any[]> => {
    try {
        const result = await performOperation(KNOWLEDGE_STORE, 'readonly', (store) => store.getAll());
        return result || [];
    } catch (e) { return []; }
};

export const searchKnowledgeContext = async (query: string): Promise<string> => {
    if (!query) return "";
    try {
        const all = await getAllKnowledge();
        const searchTerms = query.toLowerCase().split(' ');

        const relevant = all.filter(entry => {
            const text = (entry.title + " " + entry.tags.join(" ") + " " + entry.content).toLowerCase();
            return searchTerms.some(term => term.length > 2 && text.includes(term));
        });

        if (relevant.length === 0) return "";

        return `\n[BASE DE CONOCIMIENTOS EXPERTOS (APRENDIDO DEL USUARIO)]:\n${relevant.map(r => `- Título: ${r.title}\n  Nota: ${r.content}\n  Fuente: ${r.source}`).join('\n')}\n(Usa esta información PRIORITARIAMENTE para el diagnóstico).`;
    } catch (e) {
        return "";
    }
};

export const deleteKnowledgeEntry = async (id: string) => {
    return performOperation(KNOWLEDGE_STORE, 'readwrite', (store) => store.delete(id));
};

// --- BACKUP SYSTEM ---

export const exportDatabase = async (): Promise<string> => {
  const history = await getAllRepairs();
  const knowledge = await getAllKnowledge();
  return JSON.stringify({ history, knowledge }, null, 2);
};

export const importDatabase = async (jsonContent: string): Promise<boolean> => {
  try {
    const data = JSON.parse(jsonContent);
    const historyData = Array.isArray(data) ? data : data.history || [];
    const knowledgeData = data.knowledge || [];

    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onsuccess = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            const transaction = db.transaction([HISTORY_STORE, KNOWLEDGE_STORE], 'readwrite');

            const historyStore = transaction.objectStore(HISTORY_STORE);
            historyData.forEach((item: any) => { if (item.timestamp) historyStore.put(item); });

            const knowledgeStore = transaction.objectStore(KNOWLEDGE_STORE);
            knowledgeData.forEach((item: any) => { if (item.id) knowledgeStore.put(item); });

            transaction.oncomplete = () => { db.close(); resolve(true); };
            transaction.onerror = () => { db.close(); reject(false); };
        };
        request.onerror = () => reject(false);
    });
  } catch (e) {
    console.error("Import failed", e);
    return false;
  }
};

import React, { useState } from 'react';
import { GoogleGenAI, FunctionDeclaration, Type } from "@google/genai";
import { getSettings, getSessionData, addKnowledgeEntry } from '../services/storage';
import { useLocation } from 'react-router-dom';

const ChatBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const location = useLocation();

  // --- HERRAMIENTAS DEL CHATBOT ---

  const saveKnowledgeTool: FunctionDeclaration = {
      name: "save_knowledge_entry",
      description: "Guarda información técnica importante, resúmenes de webs/videos o soluciones en la Base de Conocimientos del usuario para uso futuro.",
      parameters: {
          type: Type.OBJECT,
          properties: {
              title: { type: Type.STRING, description: "Título breve y descriptivo del conocimiento." },
              content: { type: Type.STRING, description: "El contenido técnico detallado, resumen o solución." },
              tags: { type: Type.STRING, description: "Etiquetas separadas por comas (ej: 'iPhone, Carga, IC')." },
              source: { type: Type.STRING, description: "Origen de la info (ej: 'ChatBot', URL, 'Análisis Web')." }
          },
          required: ["title", "content", "tags", "source"]
      }
  };

  const getContextTool: FunctionDeclaration = {
      name: "get_current_repair_context",
      description: "Obtiene los datos de la reparación que el usuario tiene abierta actualmente en pantalla (Modelo, Placa, Fallas detectadas). Úsalo si el usuario pregunta '¿qué estoy reparando?' o pide ayuda sobre la placa actual.",
      parameters: { type: Type.OBJECT, properties: {} } // Sin parámetros
  };

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const newMessages = [...messages, { role: 'user' as const, text: input }];
    setMessages(newMessages);
    setInput('');
    setLoading(true);

    try {
      const settings = getSettings();
      const apiKey = settings.geminiApiKey || process.env.API_KEY || '';

      if (!apiKey) {
          setMessages([...newMessages, { role: 'model', text: "⚠️ Configura tu API Key en Ajustes." }]);
          setLoading(false);
          return;
      }

      const ai = new GoogleGenAI({ apiKey });
      const modelToUse = settings.geminiModel || 'gemini-3-flash-preview';

      // Incluimos la ruta actual en el sistema para contexto básico
      const currentScreen = location.pathname;

      const chat = ai.chats.create({ 
        model: modelToUse,
        config: { 
            systemInstruction: `Eres Gusrepart Assistant. Estás integrado en una app de reparación electrónica.
            Ubicación actual del usuario: ${currentScreen}.

            TIENES PODERES (TOOLS):
            1. PUEDES GUARDAR CONOCIMIENTO: Si encuentras info útil o el usuario te pide guardar algo, usa 'save_knowledge_entry'.
            2. PUEDES VER LA REPARACIÓN: Si el usuario pregunta por la placa actual, usa 'get_current_repair_context'.

            Si te dan una URL, analízala y ofrece guardar un resumen.`,
            tools: [{ functionDeclarations: [saveKnowledgeTool, getContextTool] }]
        }
      });

      // Añadir historial previo para contexto de conversación
      // Nota: En una implementación real más compleja, mapearíamos 'messages' al formato de historial de Gemini
      // Por simplicidad aquí enviamos el último mensaje pero mantenemos el historial visual.

      const result = await chat.sendMessage({ message: input });

      let responseText = result.text || "";

      // --- MANEJO DE FUNCTION CALLS ---
      const functionCalls = result.functionCalls;

      if (functionCalls && functionCalls.length > 0) {
          const call = functionCalls[0]; // Procesamos la primera llamada (normalmente solo una)

          if (call.name === 'save_knowledge_entry') {
              const args: any = call.args;
              await addKnowledgeEntry({
                  id: crypto.randomUUID(),
                  title: args.title,
                  content: args.content,
                  tags: args.tags ? args.tags.split(',').map((t:string) => t.trim()) : [],
                  source: args.source || "ChatBot Agent",
                  timestamp: Date.now()
              });

              // Enviamos respuesta de la herramienta a la IA
              const toolResponse = await chat.sendMessage({
                  message: [{
                      functionResponse: {
                          name: 'save_knowledge_entry',
                          response: { result: "Guardado exitosamente en Base de Conocimientos." }
                      }
                  }]
              });
              responseText = toolResponse.text || "He guardado esa información en tu biblioteca.";
          }

          else if (call.name === 'get_current_repair_context') {
              const pcbResult = await getSessionData('pcbResult');
              const contextData = pcbResult ? JSON.stringify(pcbResult) : "No hay reparación activa o datos detectados.";

              const toolResponse = await chat.sendMessage({
                  message: [{
                      functionResponse: {
                          name: 'get_current_repair_context',
                          response: { result: contextData }
                      }
                  }]
              });
              responseText = toolResponse.text || "";
          }
      }

      setMessages(prev => [...prev, { role: 'model', text: responseText }]);

    } catch (err: any) {
      console.error(err);
      let errorMsg = `Error: ${err.message}`;
      setMessages(prev => [...prev, { role: 'model', text: errorMsg }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {!isOpen && (
        <button 
          onClick={() => setIsOpen(true)}
          className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform flex items-center justify-center"
        >
          <span className="material-symbols-outlined">smart_toy</span>
        </button>
      )}

      {isOpen && (
        <div className="w-80 md:w-96 h-[500px] bg-surface-darkHP border border-border-dark rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-4 bg-[#1a2332]">
          <div className="p-4 bg-primary text-white flex justify-between items-center">
            <h3 className="font-bold flex items-center gap-2">
              <span className="material-symbols-outlined">smart_toy</span> Agente Gusrepart
            </h3>
            <button onClick={() => setIsOpen(false)}><span className="material-symbols-outlined">close</span></button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-background-dark">
            {messages.length === 0 && (
              <p className="text-center text-text-secondary text-sm mt-10">
                  Hola. Soy tu Agente Técnico.<br/>
                  Puedo ver tu reparación actual y guardar notas por ti.<br/>
                  ¿Qué necesitas?
              </p>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`p-3 rounded-lg text-sm max-w-[85%] ${m.role === 'user' ? 'bg-primary' : 'bg-border-dark'}`}>
                  {m.text}
                </div>
              </div>
            ))}
            {loading && <div className="text-xs text-text-secondary animate-pulse">Procesando...</div>}
          </div>
          <div className="p-3 border-t border-border-dark flex gap-2">
            <input 
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
              placeholder="Ej: Guarda esto, o Analiza esta URL..."
              className="flex-1 bg-background-dark border border-border-dark rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary text-white"
            />
            <button onClick={handleSend} className="p-2 text-primary hover:bg-white/5 rounded"><span className="material-symbols-outlined">send</span></button>
          </div>
        </div>
      )}
    </div>
  );
};

