export const distillKnowledge = async (text: string, source: string) => {
    // DETECCIÓN INTELIGENTE DE URL
    const isUrl = /^(http|https):\/\/[^ "]+$/.test(text);

    if (isUrl) {
        // ESTRATEGIA DE 2 PASOS PARA URLS (MÁS ROBUSTA)
        // 1. Buscar y extraer texto plano (sin forzar JSON para evitar errores de grounding)
        const searchPrompt = `Navega a esta URL y extrae toda la información técnica, soluciones o pasos de reparación: ${text}. 
        Si es YouTube, resume el procedimiento del video. Si es un datasheet, extrae valores límite.
        Dame un resumen detallado en texto plano.`;

        const rawSummary = await smartGenerate(searchPrompt, { useSearch: true, jsonMode: false });

        // 2. Formatear ese texto a JSON
        const formatPrompt = `Convierte este texto técnico en un objeto JSON válido con la estructura: { "title": "...", "tags": ["..."], "content": "..." }.
        TEXTO: ${rawSummary}`;

        const jsonRes = await smartGenerate(formatPrompt, { useSearch: false, jsonMode: true });

        try { 
            return JSON.parse(jsonRes); 
        } catch { 
            // Fallback si falla el parseo del paso 2
            return { 
                title: "Resumen Web (Formato Texto)", 
                tags: ["Web", "Investigación"], 
                content: rawSummary 
            }; 
        }

    } else {
        // Texto normal, procesar directo
        const prompt = `ENTRADA (${source}): ${text}
        OBJETIVO: Generar ficha de conocimiento técnico.
        FORMATO JSON: { "title": "...", "tags": [...], "content": "..." }`;

        const res = await smartGenerate(prompt, { jsonMode: true, useSearch: false });
        try { return JSON.parse(res); } catch { return { title: "Info", tags: [], content: res }; }
    }
};

