export const textToSpeech = async (text: string, onAudioReady: (buffer: AudioBuffer) => void) => {
    try {
        const ai = getAI(); 
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
            const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            const binaryString = atob(base64Audio);
            const bytes = new Uint8Array(binaryString.length);
            for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = audioContext.createBuffer(1, dataInt16.length, 24000);
            const channelData = buffer.getChannelData(0);
            for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
            onAudioReady(buffer);
        }
    } catch (e) {
        console.warn("TTS no disponible", e);
    }
};

import React, { useState, useRef, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { analyzePCBImage, searchSchematics, getFunctionalAnalysis } from '../services/gemini';
import { findSimilarRepairs } from '../services/storage';
import { PCBAnalysisResult } from '../types';

interface PCBIdentificationProps {
  persistedImages: string[];
  persistedResult: PCBAnalysisResult | null;
  persistedReceptionData?: { model: string, serial: string, symptoms: string };
  onUpdate: (images: string[], result?: PCBAnalysisResult | null, schematics?: any, functional?: string, receptionData?: any) => void;
}

const PCBIdentification: React.FC<PCBIdentificationProps> = ({ persistedImages, persistedResult, persistedReceptionData, onUpdate }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState<number | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [enhancedSlots, setEnhancedSlots] = useState<boolean[]>([false, false]); // Control de filtros CSS

  // Datos de recepción manuales (Input del técnico)
  // Inicializamos con lo que viene de App.tsx para persistencia
  const [receptionData, setReceptionData] = useState({
      model: persistedReceptionData?.model || '',
      serial: persistedReceptionData?.serial || '',
      symptoms: persistedReceptionData?.symptoms || ''
  });

  // ESTADO INICIAL
  const [images, setImages] = useState<string[]>(
    (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""]
  );

  const [result, setResult] = useState<PCBAnalysisResult | null>(persistedResult);
  const [status, setStatus] = useState<string>("");
  const [similarCases, setSimilarCases] = useState<any[]>([]);

  const [zoomImage, setZoomImage] = useState<string | null>(null);
  const [scale, setScale] = useState(1);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeSlot, setActiveSlot] = useState<number | null>(null);

  useEffect(() => {
    // Sincronizar imagenes y resultados si cambian desde fuera (ej: reset)
    const targetImages = (persistedImages && persistedImages.length > 0) ? persistedImages : ["", ""];
    if (JSON.stringify(targetImages) !== JSON.stringify(images)) {
      setImages(targetImages);
    }
    if (persistedResult && JSON.stringify(persistedResult) !== JSON.stringify(result)) {
      setResult(persistedResult);
    }
    // Sincronizar recepción
    if (persistedReceptionData) {
        if(persistedReceptionData.model !== receptionData.model || 
           persistedReceptionData.serial !== receptionData.serial || 
           persistedReceptionData.symptoms !== receptionData.symptoms) {
             setReceptionData(persistedReceptionData);
        }
    }
  }, [persistedImages, persistedResult, persistedReceptionData]);

  useEffect(() => {
    if (result?.model) {
      findSimilarRepairs(result.model).then(setSimilarCases);
    } else {
      setSimilarCases([]);
    }
  }, [result?.model]);

  // Manejador de cambios en inputs para persistencia inmediata
  const handleInputChange = (field: string, value: string) => {
      const newData = { ...receptionData, [field]: value };
      setReceptionData(newData);
      // Actualizamos al padre inmediatamente
      onUpdate(images, result, undefined, undefined, newData);
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || activeSlot === null) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64 = event.target?.result as string;
      const newImages = [...images];
      newImages[activeSlot] = base64;
      setImages(newImages);
      // Reset filter when new image loaded
      const newEnhanced = [...enhancedSlots];
      newEnhanced[activeSlot] = false;
      setEnhancedSlots(newEnhanced);

      onUpdate(newImages, result || undefined, undefined, undefined, receptionData);
      setActiveSlot(null);
      if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsDataURL(file);
  };

  const handleEnhance = async (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    if (!images[slot]) return;

    // Simular proceso de mejora visual
    setIsEnhancing(slot);
    setTimeout(() => {
        const newEnhanced = [...enhancedSlots];
        newEnhanced[slot] = !newEnhanced[slot]; // Toggle filtro
        setEnhancedSlots(newEnhanced);
        setIsEnhancing(null);
    }, 800);
  };

  const handleRemoveImage = (e: React.MouseEvent, slot: number) => {
    e.stopPropagation();
    const newImages = [...images];
    newImages[slot] = "";
    setImages(newImages);

    const newEnhanced = [...enhancedSlots];
    newEnhanced[slot] = false;
    setEnhancedSlots(newEnhanced);

    onUpdate(newImages, result || undefined, undefined, undefined, receptionData);
  };

  // FLUJO COMPLETO: Análisis Visual -> Búsqueda Datos -> Análisis Funcional
  const runVisualAnalysis = async () => {
    const activeImages = images.filter(img => img && img.length > 0);
    if (activeImages.length === 0) {
        alert("Por favor, sube al menos una imagen de la placa para confirmar visualmente el diagnóstico.");
        return;
    }

    setIsAnalyzing(true);
    setStatus("Integrando síntomas y analizando placa...");

    try {
      const pureBase64s = activeImages.map(img => img.split(',')[1]);

      const contextModel = receptionData.model || result?.model || "";
      const contextSerial = receptionData.serial || result?.boardNumber || "";
      const contextSymptoms = receptionData.symptoms || "";

      // 1. ANÁLISIS VISUAL CON CONTEXTO INTELIGENTE
      const analysis = await analyzePCBImage(pureBase64s, {
          model: contextModel,
          serial: contextSerial,
          symptoms: contextSymptoms
      });

      setResult(analysis);

      // 2. AUTOMATIZACIÓN DE BÚSQUEDA Y FUNCIONALIDAD
      if (analysis.model || analysis.boardNumber) {
          setStatus("Localizando esquemas y generando análisis funcional...");
          const query = `${analysis.manufacturer || ''} ${analysis.model || ''} ${analysis.boardNumber || ''}`;

          const [schematics, functional] = await Promise.all([
            searchSchematics(query),
            getFunctionalAnalysis(analysis.identifiedComponents || [], analysis.boardNumber || analysis.model || '')
          ]);

          // Guardamos todo de una vez
          onUpdate(images, analysis, schematics, functional, receptionData);
      } else {
          // Si no detectó modelo, guardamos solo lo visual
          onUpdate(images, analysis, undefined, undefined, receptionData);
      }

    } catch (error) {
      console.error(error);
      setStatus("Hubo un error en el proceso de análisis.");
    } finally {
      setIsAnalyzing(false);
      setStatus("");
    }
  };

  const updateResultField = (field: keyof PCBAnalysisResult, value: any) => {
    const newResult = result ? { ...result, [field]: value } : { 
      manufacturer: field === 'manufacturer' ? value : '', 
      model: field === 'model' ? value : '', 
      boardNumber: field === 'boardNumber' ? value : '', 
      confidence: 1, identifiedComponents: [], detectedAnomalies: [] 
    };
    setResult(newResult);
    onUpdate(images, newResult, undefined, undefined, receptionData);
  };

  // Handlers UI
  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setScale(prev => Math.min(Math.max(1, prev + (e.deltaY > 0 ? -0.2 : 0.2)), 5));
  };
  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - position.x, y: e.clientY - position.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setPosition({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  return (
    <div className="flex h-full flex-col lg:flex-row overflow-hidden relative">
      {zoomImage && (
        <div 
          className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center p-4 overflow-hidden"
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => setIsDragging(false)}
          style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
        >
          <div className="absolute top-6 right-6 z-10">
            <button onClick={() => setZoomImage(null)} className="p-3 bg-red-500 rounded-full text-white shadow-xl">
              <span className="material-symbols-outlined">close</span>
            </button>
          </div>
          <div style={{ transform: `translate(${position.x}px, ${position.y}px) scale(${scale})` }}>
            <img src={zoomImage} className="max-w-none h-[85vh] object-contain select-none" draggable={false} />
          </div>
        </div>
      )}

      <div className="flex flex-col flex-1 bg-[#1a2332] overflow-y-auto lg:border-r border-border-dark">
        <div className="p-6 md:p-10 flex flex-col h-full max-w-5xl mx-auto w-full">
          <div className="flex flex-col gap-2 mb-6">
            <h1 className="text-3xl md:text-4xl font-black text-white">Recepción y Análisis</h1>
            <p className="text-text-secondary">Paso 1: Introduce los datos del equipo y sube imágenes. La IA realizará el diagnóstico completo.</p>
          </div>

          {/* PANEL DE DATOS DE RECEPCIÓN */}
          <div className="bg-[#111722] border border-border-dark rounded-2xl p-6 mb-8 shadow-lg">
              <h2 className="text-white font-bold text-lg mb-4 flex items-center gap-2">
                  <span className="material-symbols-outlined text-primary">assignment</span>
                  Datos de Entrada
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                      <label className="text-xs text-text-secondary uppercase font-bold mb-1 block">Modelo del Equipo</label>
                      <input 
                        value={receptionData.model}
                        onChange={(e) => handleInputChange('model', e.target.value)}
                        placeholder="Ej: HP Pavilion 15-cw" 
                        className="w-full bg-black/30 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-primary outline-none"
                      />
                  </div>
                  <div>
                      <label className="text-xs text-text-secondary uppercase font-bold mb-1 block">Número de Serie / ID</label>
                      <input 
                        value={receptionData.serial}
                        onChange={(e) => handleInputChange('serial', e.target.value)}
                        placeholder="Ej: 5CD84..." 
                        className="w-full bg-black/30 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-primary outline-none font-mono"
                      />
                  </div>
                  <div className="md:col-span-2">
                      <label className="text-xs text-text-secondary uppercase font-bold mb-1 block">Síntomas de Avería / Notas del Cliente</label>
                      <textarea 
                        value={receptionData.symptoms}
                        onChange={(e) => handleInputChange('symptoms', e.target.value)}
                        placeholder="Ej: No enciende, LED de carga parpadea, se mojó hace una semana..." 
                        className="w-full bg-black/30 border border-border-dark rounded-xl px-4 py-3 text-white focus:border-primary outline-none h-20 resize-none"
                      />
                  </div>
              </div>
          </div>

          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 min-h-[300px]">
            {[0, 1].map((slot) => (
              <div key={slot} className={`relative flex items-center justify-center rounded-2xl border-2 border-dashed ${images[slot] ? 'border-primary' : 'border-border-dark'} bg-[#111722] hover:bg-[#161e2c] transition-all group overflow-hidden shadow-lg`}>
                {images[slot] ? (
                  <>
                    <img 
                        src={images[slot]} 
                        className="absolute inset-0 w-full h-full object-cover transition-all duration-500" 
                        style={{ filter: enhancedSlots[slot] ? 'contrast(1.2) brightness(1.1) drop-shadow(0 0 1px white)' : 'none', opacity: enhancedSlots[slot] ? 1 : 0.6 }}
                    />
                    {enhancedSlots[slot] && <div className="absolute top-2 right-2 bg-primary text-white text-[10px] px-2 py-1 rounded font-bold z-10">MEJORADO</div>}

                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center gap-4 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                      <button onClick={() => setZoomImage(images[slot])} className="p-4 bg-primary text-white rounded-full shadow-2xl hover:scale-110 transition-transform">
                        <span className="material-symbols-outlined text-3xl">zoom_in</span>
                      </button>
                      <button onClick={(e) => handleEnhance(e, slot)} className={`p-3 bg-surface-dark rounded-xl text-white border border-white/10 ${isEnhancing === slot ? 'animate-spin' : ''}`}>
                        <span className="material-symbols-outlined">auto_fix</span>
                      </button>
                      <button onClick={(e) => handleRemoveImage(e, slot)} className="p-3 bg-red-500/20 text-red-500 rounded-xl border border-red-500/30">
                        <span className="material-symbols-outlined">delete</span>
                      </button>
                    </div>
                  </>
                ) : (
                  <button onClick={() => { setActiveSlot(slot); fileInputRef.current?.click(); }} className="flex flex-col items-center gap-4 p-8 w-full h-full justify-center group">
                    <div className="size-16 rounded-full bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform border border-primary/20">
                      <span className="material-symbols-outlined text-4xl">add_a_photo</span>
                    </div>
                    <p className="text-sm font-bold text-text-secondary">{slot === 0 ? 'Subir Frente' : 'Subir Reverso'}</p>
                  </button>
                )}
              </div>
            ))}
          </div>

          <div className="mt-8 flex flex-col md:flex-row items-center justify-center gap-4">
             {status && <p className="text-primary text-sm font-mono animate-pulse w-full text-center md:hidden">{status}</p>}

             <button 
               onClick={runVisualAnalysis} 
               disabled={images.filter(img => img && img.length > 0).length === 0 || isAnalyzing} 
               className="w-full md:w-auto px-8 py-4 rounded-xl font-bold text-lg bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 transition-all text-white disabled:opacity-30 flex items-center justify-center gap-3"
             >
               <span className="material-symbols-outlined">{isAnalyzing ? 'sync' : 'rocket_launch'}</span>
               <span>{isAnalyzing ? status || 'Procesando...' : 'Analizar Diagnóstico'}</span>
             </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-[420px] bg-background-dark flex flex-col border-t lg:border-t-0 overflow-y-auto p-6 shadow-2xl z-10">
        <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-bold flex items-center gap-2">
            <span className="material-symbols-outlined text-primary">analytics</span>
            Resultados IA
            </h2>
            {result && (
                <button 
                    onClick={() => setIsEditing(!isEditing)}
                    className={`p-2 rounded-lg transition-colors ${isEditing ? 'bg-primary text-white' : 'text-text-secondary hover:text-white'}`}
                    title={isEditing ? "Ver visualización" : "Editar datos"}
                >
                    <span className="material-symbols-outlined text-sm">{isEditing ? 'visibility' : 'edit'}</span>
                </button>
            )}
        </div>

        {result || images.some(i => i) ? (
          <div className="space-y-6">
            <div className={`p-6 rounded-2xl border transition-all relative overflow-hidden ${isEditing ? 'bg-[#111722] border-primary/50 ring-1 ring-primary/20' : 'bg-surface-dark border-white/5'}`}>

              {!isEditing && (
                  <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                       <span className="material-symbols-outlined text-6xl">qr_code_2</span>
                  </div>
              )}

              <div className="space-y-4">
                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Fabricante</label>
                  {isEditing ? (
                      <input 
                      type="text" 
                      value={result?.manufacturer || ''} 
                      onChange={(e) => updateResultField('manufacturer', e.target.value)}
                      placeholder="Ej: Dell, HP, Apple"
                      className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                      />
                  ) : (
                      <p className="text-lg font-bold text-white">{result?.manufacturer || <span className="text-white/20 italic">---</span>}</p>
                  )}
                </div>

                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Modelo de Equipo</label>
                   {isEditing ? (
                      <input 
                      type="text" 
                      value={result?.model || ''} 
                      onChange={(e) => updateResultField('model', e.target.value)}
                      placeholder="Ej: MacBook Pro A1708"
                      className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm font-bold text-white focus:ring-1 focus:ring-primary outline-none"
                      />
                  ) : (
                      <p className="text-lg font-bold text-white">{result?.model || <span className="text-white/20 italic">---</span>}</p>
                  )}
                </div>

                <div>
                  <label className="text-[10px] uppercase font-bold text-text-secondary tracking-widest block mb-1">Board Number / Referencia PCB</label>
                   {isEditing ? (
                      <input 
                      type="text" 
                      value={result?.boardNumber || ''} 
                      onChange={(e) => updateResultField('boardNumber', e.target.value)}
                      placeholder="Ej: 820-00840-A"
                      className="w-full bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-xs font-mono text-primary outline-none"
                      />
                  ) : (
                      <p className="text-sm font-mono text-primary tracking-wide">{result?.boardNumber || <span className="text-white/20 italic">---</span>}</p>
                  )}
                </div>
              </div>
            </div>

            <div className="space-y-4 animate-in fade-in slide-in-from-right-2">

              {result && (
                 <div className="pt-2 border-t border-white/5">
                    <Link to="/boardview" className="w-full flex items-center justify-center gap-3 rounded-xl bg-primary hover:bg-primary-hover shadow-lg shadow-primary/20 h-14 text-white font-bold text-lg transition-all group">
                        <span>Ver Resultados Completos</span>
                        <span className="material-symbols-outlined group-hover:translate-x-1 transition-transform">arrow_forward</span>
                    </Link>
                    <p className="text-center text-[10px] text-text-secondary mt-3">Esquemas y Análisis Funcional generados automáticamente.</p>
                 </div>
              )}
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-20 text-center">
            <span className="material-symbols-outlined text-8xl mb-4">memory</span>
            <p className="text-sm">Panel de Datos Vacío</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PCBIdentification;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import ConfirmDialog from './components/ConfirmDialog';
import Dashboard from './screens/Dashboard';
import PCBIdentification from './screens/PCBIdentification';
import BoardviewSchematics from './screens/BoardviewSchematics';
import GuidedMeasurement from './screens/GuidedMeasurement';
import DiagnosticDecisionTree from './screens/DiagnosticDecisionTree';
import DatabaseScreen from './screens/DatabaseScreen';
import ComponentDetails from './screens/ComponentDetails';
import KnowledgeBase from './screens/KnowledgeBase';
import Settings from './screens/Settings';
import ChatBot from './components/ChatBot';
import LiveAssistant from './components/LiveAssistant';
import { PCBAnalysisResult, MeasurementPoint, DiagnosticTurn } from './types';
import { getSessionData, saveSessionData, clearSessionStorage, saveRepairToHistory, initializeDatabase } from './services/storage';

const AppContent: React.FC = () => {
  const navigate = useNavigate();
  const [isLoaded, setIsLoaded] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isClearing, setIsClearing] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Modals & Floating UI
  const [showSaveModal, setShowSaveModal] = useState(false);
  const [showNewRepairModal, setShowNewRepairModal] = useState(false);
  const [showLiveAssistant, setShowLiveAssistant] = useState(false);

  // Estados de sesión
  const [pcbImages, setPcbImages] = useState<string[]>([]);
  const [pcbResult, setPcbResult] = useState<PCBAnalysisResult | null>(null);

  // LIFTED STATE: Reception Data (Persistencia de datos de entrada)
  const [receptionData, setReceptionData] = useState({ model: '', serial: '', symptoms: '' }); 

  const [schematicInfo, setSchematicInfo] = useState<{summary: string, sources: string} | null>(null);
  const [functionalAI, setFunctionalAI] = useState<string>("");
  const [measurements, setMeasurements] = useState<MeasurementPoint[]>([]);
  const [diagHistory, setDiagHistory] = useState<DiagnosticTurn[]>([]);
  const [currentRepairTimestamp, setCurrentRepairTimestamp] = useState<number | null>(null);

  const [tempModel, setTempModel] = useState({ manufacturer: '', model: '', boardNumber: '' });

  // Carga inicial y Sembrado de DB
  useEffect(() => {
    const initSystem = async () => {
      try {
        await initializeDatabase();
        const results = await Promise.allSettled([
          getSessionData('pcbImages'),
          getSessionData('pcbResult'),
          getSessionData('schematicInfo'),
          getSessionData('functionalAI'),
          getSessionData('measurements'),
          getSessionData('diagHistory'),
          getSessionData('currentRepairTimestamp'),
          getSessionData('receptionData') // Cargar datos de recepción guardados
        ]);

        const getVal = (idx: number) => results[idx].status === 'fulfilled' ? (results[idx] as PromiseFulfilledResult<any>).value : null;

        const imgs = getVal(0);
        const res = getVal(1);
        const schem = getVal(2);
        const func = getVal(3);
        const meas = getVal(4);
        const diag = getVal(5);
        const ts = getVal(6);
        const recData = getVal(7);

        if (imgs) setPcbImages(imgs);
        if (res) setPcbResult(res);
        if (schem) setSchematicInfo(schem);
        if (func) setFunctionalAI(func);
        if (meas) setMeasurements(meas);
        if (diag) setDiagHistory(diag);
        if (ts) setCurrentRepairTimestamp(ts);
        if (recData) setReceptionData(recData);

      } catch (e) { 
          console.error("Critical Load Error", e); 
      } finally { 
          setIsLoaded(true); 
      }
    };
    initSystem();
  }, []); 

  // Auto-guardado
  useEffect(() => {
    if (isLoaded && !isClearing) {
      const timer = setTimeout(() => {
        if (pcbImages.length > 0 || pcbResult || diagHistory.length > 0 || receptionData.model) {
            saveSessionData('pcbImages', pcbImages);
            saveSessionData('pcbResult', pcbResult);
            saveSessionData('schematicInfo', schematicInfo);
            saveSessionData('functionalAI', functionalAI);
            saveSessionData('measurements', measurements);
            saveSessionData('diagHistory', diagHistory);
            saveSessionData('currentRepairTimestamp', currentRepairTimestamp);
            saveSessionData('receptionData', receptionData);
        }
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [pcbImages, pcbResult, schematicInfo, functionalAI, measurements, diagHistory, currentRepairTimestamp, receptionData, isLoaded, isClearing]);

  const handleNewRepairConfirm = async () => {
    setIsClearing(true); 
    try {
        await clearSessionStorage();
    } catch(e) { console.error(e); }

    setPcbImages([]);
    setPcbResult(null);
    setSchematicInfo(null);
    setFunctionalAI("");
    setMeasurements([]);
    setDiagHistory([]);
    setCurrentRepairTimestamp(null);
    setReceptionData({ model: '', serial: '', symptoms: '' });
    setTempModel({ manufacturer: '', model: '', boardNumber: '' });

    setShowNewRepairModal(false);
    // Redirigir DIRECTAMENTE al analizador, saltando safety
    navigate('/pcb-id');

    setTimeout(() => {
        setIsClearing(false);
    }, 500);
  };

  const executeSave = async (metadata?: any) => {
    setIsSaving(true);
    try {
      const ts = currentRepairTimestamp || Date.now();

      // Combinar datos manuales con detectados para el registro final
      const finalRes = { 
          ...(pcbResult || {}), 
          ...(metadata || {}),
          model: metadata?.model || receptionData.model || pcbResult?.model,
          boardNumber: metadata?.boardNumber || receptionData.serial || pcbResult?.boardNumber
      };

      const record = {
        timestamp: ts,
        pcbImages,
        pcbResult: finalRes,
        schematicInfo,
        functionalAI,
        measurements, 
        diagHistory,
        receptionData // Guardar explícitamente
      };

      await saveRepairToHistory(record);

      setCurrentRepairTimestamp(ts);
      if (finalRes) setPcbResult(finalRes as PCBAnalysisResult);

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 2000);
      setShowSaveModal(false);
    } catch (e) {
      alert("Error guardando. Intente de nuevo.");
      console.error(e);
    } finally {
      setIsSaving(false);
    }
  };

  const handleGlobalSave = () => {
    if (currentRepairTimestamp && (pcbResult?.model || receptionData.model)) {
      executeSave();
    } else {
      setTempModel({ 
        manufacturer: pcbResult?.manufacturer || '', 
        model: receptionData.model || pcbResult?.model || '', 
        boardNumber: receptionData.serial || pcbResult?.boardNumber || '' 
      });
      setShowSaveModal(true);
    }
  };

  const handleMeasurementVerdict = (verdict: string) => {
    const verdictTurn: DiagnosticTurn = {
        role: 'assistant',
        content: `🔍 **RESULTADO DE MEDICIONES:**\n${verdict}\n\n¿Cómo procedemos ahora?`,
        timestamp: Date.now()
    };

    setDiagHistory(prev => [...prev, verdictTurn]);
    navigate('/diagnostics');
  };

  const loadRepair = (repair: any) => {
    setIsClearing(true);
    setPcbImages(repair.pcbImages || []);
    setPcbResult(repair.pcbResult || null);
    setSchematicInfo(repair.schematicInfo || null);
    setFunctionalAI(repair.functionalAI || "");
    setMeasurements(repair.measurements || []); 
    setDiagHistory(repair.diagHistory || []);   
    setCurrentRepairTimestamp(repair.timestamp || null);

    // Cargar datos de recepción
    if (repair.receptionData) {
        setReceptionData(repair.receptionData);
    } else if (repair.pcbResult) {
        // Fallback para registros antiguos
        setReceptionData({
            model: repair.pcbResult.model || '',
            serial: repair.pcbResult.boardNumber || '',
            symptoms: ''
        });
    }

    setTimeout(() => setIsClearing(false), 500);
  };

  if (!isLoaded) return <div className="h-screen w-full bg-background-dark flex items-center justify-center"><span className="material-symbols-outlined text-4xl animate-spin text-primary">settings</span></div>;

  return (
    <div className="flex h-screen w-full bg-background-dark text-white overflow-hidden font-display relative">
      <Sidebar />
      <div className="flex-1 flex flex-col min-w-0 relative">
        <Header 
            onSave={handleGlobalSave} 
            isSaving={isSaving} 
            isSuccess={saveSuccess}
            onToggleLive={() => setShowLiveAssistant(!showLiveAssistant)}
            isLiveActive={showLiveAssistant}
        />
        <main className="flex-1 overflow-hidden relative">
          <Routes>
            <Route path="/" element={<Dashboard onLoadRepair={(r) => { loadRepair(r); navigate('/pcb-id'); }} onNewRepair={() => setShowNewRepairModal(true)} />} />
            {/* RUTA DE SAFETY ELIMINADA */}
            <Route path="/pcb-id" element={
                <PCBIdentification 
                    persistedImages={pcbImages} 
                    persistedResult={pcbResult} 
                    persistedReceptionData={receptionData}
                    onUpdate={(imgs, res, schem, func, recData) => { 
                        if (!isClearing) {
                          if (imgs) setPcbImages([...imgs]);
                          if (res !== undefined) setPcbResult(res);
                          if (schem !== undefined) setSchematicInfo(schem);
                          if (func !== undefined) setFunctionalAI(func);
                          if (recData !== undefined) setReceptionData(recData);
                        }
                    }} 
                />
            } />
            <Route path="/boardview" element={<BoardviewSchematics pcbResult={pcbResult} schematicInfo={schematicInfo} functionalAI={functionalAI} />} />
            <Route 
                path="/measure" 
                element={
                    <GuidedMeasurement 
                        pcbImages={pcbImages} 
                        pcbResult={pcbResult} 
                        functionalAI={functionalAI} 
                        persistedPoints={measurements} 
                        onUpdate={(p) => !isClearing && setMeasurements(p)} 
                        onVerdictGenerated={handleMeasurementVerdict}
                    />
                } 
            />
            <Route path="/diagnostics" element={<DiagnosticDecisionTree persistedHistory={diagHistory} pcbResult={pcbResult} onUpdate={(h) => !isClearing && setDiagHistory(h)} />} />
            <Route path="/component" element={<ComponentDetails />} />
            <Route path="/knowledge" element={<KnowledgeBase />} />
            <Route path="/database" element={<DatabaseScreen onLoadRepair={loadRepair} />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>
        </main>
        <ChatBot />
