// --- GESTIÓN DE CREDENCIALES ---

const getAI = () => {
  const settings = getSettings();
  const apiKey = (settings.geminiApiKey && settings.geminiApiKey.trim() !== '') 
                 ? settings.geminiApiKey 
                 : process.env.API_KEY;

  if (!apiKey) {
    console.error("API Key no encontrada en Configuración ni en .env");
    throw new Error("API Key faltante. Configúrala en Ajustes.");
  }
  return new GoogleGenAI({ apiKey });
};

// --- CEREBRO INTELIGENTE (SMART GENERATE) ---

const smartGenerate = async (
    prompt: string, 
    options: {
        images?: string[], 
        jsonMode?: boolean,
        system?: string,
        modelGemini?: string,
        useSearch?: boolean 
    }
): Promise<string> => {
    const settings = getSettings();
    const ai = getAI();

    // USAR EXACTAMENTE EL MODELO ELEGIDO EN CONFIGURACIÓN
    let targetModel = settings.geminiModel || 'gemini-3-flash-preview';

    // Función ejecutora
    const executeCall = async (modelToUse: string) => {
        const config: any = {
             systemInstruction: options.system,
        };

        // REGLA DE ORO: SI USAMOS SEARCH, NO PODEMOS USAR JSON MODE EN LA MISMA LLAMADA (Para Gemini 3 Flash)
        if (options.useSearch) {
             config.tools = [{googleSearch: {}}];
             // Forzamos desactivar JSON MIME type si hay búsqueda para evitar conflictos de API
             config.responseMimeType = undefined;
        } else if (options.jsonMode) {
             config.responseMimeType = "application/json";
        }

        // Configuración de Thinking (Solo modelos compatibles)
        if (modelToUse.includes('gemini-3') && !modelToUse.includes('flash')) {
            config.thinkingConfig = { thinkingBudget: 1024 };
        }

        let contents;
        if (options.images && options.images.length > 0) {
            // Limpiamos base64 header si existe
            const imageParts = options.images.map(img => {
                const base64Data = img.includes('base64,') ? img.split('base64,')[1] : img;
                return {
                    inlineData: { data: base64Data, mimeType: 'image/jpeg' }
                };
            });

            contents = [
                { role: 'user', parts: [...imageParts, { text: prompt }] }
            ];
            // IMPORTANTE: Desactivar tools complejos si enviamos imágenes para evitar sobrecarga en modelos preview
            delete config.tools; 
        } else {
            contents = prompt;
        }

        console.log(`[Gemini] Llamando a ${modelToUse} | Search: ${options.useSearch} | JSON: ${options.jsonMode}`);

        const response = await ai.models.generateContent({
            model: modelToUse,
            contents: contents,
            config: config
        });

        return response.text || "";
    };

    try {
        return await executeCall(targetModel);
    } catch (error: any) {
        console.warn(`Error usando modelo ${targetModel}:`, error);

        // Fallback a modelo seguro si falla el principal
        const SAFE_MODEL = 'gemini-2.0-flash-exp'; 
        if (targetModel !== SAFE_MODEL) {
            console.log(`Reintentando con modelo de respaldo: ${SAFE_MODEL}...`);
            return await executeCall(SAFE_MODEL);
        }
        throw error;
    }
};

