export const processTechnicalPDF = async (base64Pdf: string) => {
  const ai = getAI();
  const settings = getSettings();
  const model = settings.geminiModel || 'gemini-3-flash-preview';

  const cleanBase64 = base64Pdf.includes('base64,') ? base64Pdf.split('base64,')[1] : base64Pdf;

  const response = await ai.models.generateContent({
    model: model, 
    contents: [
      { inlineData: { mimeType: 'application/pdf', data: cleanBase64 } },
      { text: `Extrae info técnica en JSON: { "title": "...", "tags": [...], "content": "..." }` }
    ],
    config: { responseMimeType: "application/json" }
  });

  return JSON.parse(response.text || '{}');
};

export const distillKnowledge = async (text: string, source: string) => {
    // DETECCIÓN INTELIGENTE DE URL
    const isUrl = /^(http|https):\/\/[^ "]+$/.test(text);

    if (isUrl) {
        // ESTRATEGIA DE 2 PASOS ESTRICTA (Search -> Text -> JSON)

        // PASO 1: Búsqueda Pura (Sin JSON Mode)
        const searchPrompt = `Analiza esta URL: ${text}.
        Si es YouTube, resume los pasos de reparación o teoría explicada.
        Si es un Datasheet o Web, extrae especificaciones y soluciones.
        Devuelve un resumen detallado en TEXTO PLANO.`;

        console.log("Iniciando Paso 1: Navegación Web...");
        const rawSummary = await smartGenerate(searchPrompt, { 
            useSearch: true, 
            jsonMode: false // CRÍTICO: Desactivar JSON aquí
        });

        // PASO 2: Formateo Puro (Sin Search)
        const formatPrompt = `Tengo este resumen técnico:
        "${rawSummary}"

        Transfórmalo en este JSON exacto:
        { "title": "Título descriptivo", "tags": ["tag1", "tag2"], "content": "Resumen técnico..." }`;

        console.log("Iniciando Paso 2: Formateo JSON...");
        const jsonRes = await smartGenerate(formatPrompt, { 
            useSearch: false, // CRÍTICO: Desactivar Search aquí
            jsonMode: true 
        });

        try { 
            return JSON.parse(jsonRes); 
        } catch (e) { 
            console.error("Error parseando JSON en paso 2", e);
            return { 
                title: "Resumen Web (Texto)", 
                tags: ["Web", "Investigación"], 
                content: rawSummary 
            }; 
        }

    } else {
        // Texto normal, procesar directo
        const prompt = `ENTRADA (${source}): ${text}
        OBJETIVO: Generar ficha de conocimiento técnico.
        FORMATO JSON: { "title": "...", "tags": [...], "content": "..." }`;

        const res = await smartGenerate(prompt, { jsonMode: true, useSearch: false });
        try { return JSON.parse(res); } catch { return { title: "Info", tags: [], content: res }; }
    }
};

